    private static final String[] TELE_HOW = {"Spell", "Item", "Portal Nexus", "House portal", "Fairy ring", "Spirit tree", "Quetzal (Renu)", "Quetzal whistle"};
    private static final String[] TELE_HOW_KEYS = {"SPELL", "ITEM", "NEXUS", "PORTAL", FairyRings.METHOD, SpiritTrees.METHOD, Quetzals.METHOD_RENU, Quetzals.METHOD_WHISTLE};
    private static final String NEXUS_HINT = "Destination as named in your nexus, e.g. Varrock";
    private static final String PORTAL_HINT = "Portal's destination, e.g. Varrock for Varrock Portal";
    private final JComboBox<String> teleHow = combo(TELE_HOW);
    private final JComboBox<Object> spellBox = new JComboBox<>();
    private final JComboBox<Object> itemBox = new JComboBox<>();
    private final HintField nexusField = new HintField();
    private final JComboBox<String> ringBox = new JComboBox<>();
    private final JComboBox<String> quetzalBox = new JComboBox<>();
    private final JComboBox<String> treeBox = new JComboBox<>();
    /** The card both quetzal methods share: a landing-site dropdown. */
    private static final String QUETZAL_CARD = "QUETZAL_SITE";
    private final JPanel teleChoice = new JPanel(new CardLayout());

    private JPanel buildTeleport() {
        JPanel p = section();
        p.add(label("Teleport"));

        JPanel top = bareLeft(new JPanel(new BorderLayout(6, 0)));
        top.add(small("Using"), BorderLayout.WEST);
        top.add(teleHow, BorderLayout.CENTER);
        JButton remove = button("Remove");
        remove.setToolTipText("Walk there instead");
        remove.addActionListener(e -> {
            teleMethod = "WALK"; chosenSpell = null; chosenItem = null; chosenNexus = null;
            teleTouched = true;
            extraTele = false;
            refresh();
        });
        top.add(remove, BorderLayout.EAST);
        top.setMaximumSize(new Dimension(Integer.MAX_VALUE, top.getPreferredSize().height));
        p.add(top);
        p.add(Box.createVerticalStrut(6));

        spellBox.addItem("Choose a spell...");
        for (TeleportSpell sp : TeleportSpells.ALL) spellBox.addItem(sp);
        spellBox.setMaximumRowCount(14);
        spellBox.setRenderer(new DefaultListCellRenderer() {
            @Override public Component getListCellRendererComponent(JList<?> l, Object v, int i, boolean sel, boolean foc) {
                super.getListCellRendererComponent(l, v, i, sel, foc);
                if (v instanceof TeleportSpell) {
                    TeleportSpell sp = (TeleportSpell) v;
                    setText(sp.getName());
                    setIcon(TeleportPickers.spellIcon(plugin, sp, () -> { spellBox.repaint(); l.repaint(); }));
                } else {
                    setIcon(null);
                }
                return this;
            }
        });
        spellBox.addActionListener(e -> {
            if (loading) return;
            Object v = spellBox.getSelectedItem();
            chosenSpell = v instanceof TeleportSpell ? (TeleportSpell) v : null;
            teleMethod = "SPELL";
            teleportChosen(chosenSpell != null ? chosenSpell.getDestination() : null);
        });

        fillItemBox("");
        itemBox.setMaximumRowCount(14);
        itemBox.setRenderer(new DefaultListCellRenderer() {
            @Override public Component getListCellRendererComponent(JList<?> l, Object v, int i, boolean sel, boolean foc) {
                super.getListCellRendererComponent(l, v, i, sel, foc);
                if (v instanceof TeleportItem) {
                    TeleportItem it = (TeleportItem) v;
                    setText(it.getDisplayName());
                    setIcon(TeleportPickers.itemIcon(plugin, it));
                } else {
                    setIcon(null);
                }
                return this;
            }
        });
        // The box itself is the search: type part of the item or the place to narrow the list
        itemBox.setEditable(true);
        itemBox.setEditor(itemEditor);
        itemEditor.field.setHint(ITEM_PROMPT);
        itemEditor.field.setToolTipText("Type part of the item or the place, e.g. \"xeric\" or \"slayer tower\"");
        itemEditor.field.addKeyListener(new java.awt.event.KeyAdapter() {
            @Override public void keyReleased(java.awt.event.KeyEvent e) {
                int k = e.getKeyCode();
                if (k == java.awt.event.KeyEvent.VK_UP || k == java.awt.event.KeyEvent.VK_DOWN
                    || k == java.awt.event.KeyEvent.VK_ENTER || k == java.awt.event.KeyEvent.VK_ESCAPE
                    || k == java.awt.event.KeyEvent.VK_LEFT || k == java.awt.event.KeyEvent.VK_RIGHT) return;
                String typed = itemEditor.field.getText();
                int caret = itemEditor.field.getCaretPosition();
                fillItemBox(typed);
                itemEditor.field.setText(typed);
                itemEditor.field.setCaretPosition(Math.min(caret, typed.length()));
                if (itemBox.isShowing() && itemBox.getItemCount() > 0) itemBox.showPopup();
            }
        });
        itemEditor.field.addFocusListener(new java.awt.event.FocusAdapter() {
            @Override public void focusGained(java.awt.event.FocusEvent e) {
                itemEditor.field.selectAll();
                if (itemBox.isShowing()) itemBox.showPopup();
            }
            @Override public void focusLost(java.awt.event.FocusEvent e) {
                // Leaving the box puts back the picked item (or the prompt) and the whole list
                fillItemBox("");
            }
        });
        itemBox.addActionListener(e -> {
            if (loading || filteringItems) return;
            Object v = itemBox.getSelectedItem();
            TeleportItem picked = null;
            if (v instanceof TeleportItem) {
                picked = (TeleportItem) v;
            } else if (v != null && "comboBoxEdited".equals(e.getActionCommand())) {
                // Enter on typed text: the item it names, else the first match
                String typed = v.toString().trim();
                picked = TeleportItems.getByDisplayName(typed);
                if (picked == null && !typed.isEmpty() && itemBox.getItemCount() > 0
                    && itemBox.getItemAt(0) instanceof TeleportItem) picked = (TeleportItem) itemBox.getItemAt(0);
            }
            if (picked == null || picked == chosenItem) return;
            chosenItem = picked;
            teleMethod = "ITEM";
            itemEditor.setItem(picked);
            teleportChosen(chosenItem.getDestination());
        });

        // The nexus and the house portals share this field: both are named by destination.
        nexusField.setHint(NEXUS_HINT);
        nexusField.getDocument().addDocumentListener(new Doc(() -> {
            if (loading) return;
            String t = nexusField.getText().trim();
            chosenNexus = t.isEmpty() ? null : t;
            teleMethod = TELE_HOW_KEYS[Math.max(0, teleHow.getSelectedIndex())];
            teleportChosen(null);
        }));

        // Fairy rings: every code, with where it lands
        ringBox.addItem("Choose a code...");
        for (String code : FairyRings.codes()) ringBox.addItem(ringLabel(code));
        ringBox.setMaximumRowCount(14);
        ringBox.addActionListener(e -> {
            if (loading) return;
            String code = ringBox.getSelectedIndex() > 0 ? FairyRings.normalize(String.valueOf(ringBox.getSelectedItem()).split(" - ")[0]) : null;
            chosenNexus = code;
            teleMethod = FairyRings.METHOD;
            teleportChosen(code != null ? FairyRings.destination(code) : null);
        });

        // Quetzals: every landing site, by name (Renu and the whistle fly to the same ones)
        quetzalBox.addItem("Choose a landing site...");
        for (String site : Quetzals.sites()) quetzalBox.addItem(site);
        quetzalBox.setMaximumRowCount(14);
        quetzalBox.addActionListener(e -> {
            if (loading) return;
            String site = quetzalBox.getSelectedIndex() > 0 ? String.valueOf(quetzalBox.getSelectedItem()) : null;
            chosenNexus = site;
            teleMethod = TELE_HOW_KEYS[Math.max(0, teleHow.getSelectedIndex())];
            teleportChosen(site != null ? Quetzals.destination(site) : null);
        });

        // Spirit trees: every place in the trees' menu
        treeBox.addItem("Choose a destination...");
        for (String d : SpiritTrees.destinations()) treeBox.addItem(d);
        treeBox.setMaximumRowCount(14);
        treeBox.addActionListener(e -> {
            if (loading) return;
            String dest = treeBox.getSelectedIndex() > 0 ? String.valueOf(treeBox.getSelectedItem()) : null;
            chosenNexus = dest;
            teleMethod = SpiritTrees.METHOD;
            teleportChosen(dest != null ? SpiritTrees.destination(dest) : null);
        });

        for (JComponent c : new JComponent[]{spellBox, itemBox, ringBox, quetzalBox, treeBox}) c.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        bareLeft(teleChoice);
        teleChoice.add(spellBox, "SPELL");
        teleChoice.add(itemBox, "ITEM");
        teleChoice.add(nexusField, "NEXUS");
        teleChoice.add(ringBox, FairyRings.METHOD);
        teleChoice.add(quetzalBox, QUETZAL_CARD);
        teleChoice.add(treeBox, SpiritTrees.METHOD);
        teleChoice.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        p.add(teleChoice);

        teleHow.addActionListener(e -> {
            String key = TELE_HOW_KEYS[Math.max(0, teleHow.getSelectedIndex())];
            showTeleCard(key);
            if (loading) return;
            teleMethod = key;
            // The nexus/portal text and the fairy ring code share chosenNexus: take the shown one's
            if (FairyRings.METHOD.equals(key)) {
                chosenNexus = ringBox.getSelectedIndex() > 0
                    ? FairyRings.normalize(String.valueOf(ringBox.getSelectedItem()).split(" - ")[0]) : null;
            } else if (isQuetzal(key)) {
                chosenNexus = quetzalBox.getSelectedIndex() > 0 ? String.valueOf(quetzalBox.getSelectedItem()) : null;
            } else if (SpiritTrees.METHOD.equals(key)) {
                chosenNexus = treeBox.getSelectedIndex() > 0 ? String.valueOf(treeBox.getSelectedItem()) : null;
            } else if ("NEXUS".equals(key) || "PORTAL".equals(key)) {
                String t = nexusField.getText().trim();
                chosenNexus = t.isEmpty() ? null : t;
            }
            teleTouched = true;
            refresh();
        });
        return p;
    }

    private static final String ITEM_PROMPT = "Choose an item...";
    private final ItemEditor itemEditor = new ItemEditor();
    /** Set while the item list is refilled, so the refill doesn't count as picking an item. */
    private boolean filteringItems;

    /**
     * Fill the item list with the teleports whose name has every word of {@code query} (all of
     * them for an empty query). The box then shows the picked item again, or the prompt.
     */
    private void fillItemBox(String query) {
        String[] words = query == null ? new String[0] : query.trim().toLowerCase().split("\\s+");
        filteringItems = true;
        try {
            itemBox.removeAllItems();
            for (TeleportItem it : TeleportItems.ALL) {
                String name = it.getDisplayName().toLowerCase();
                boolean all = true;
                for (String w : words) if (!w.isEmpty() && !name.contains(w)) { all = false; break; }
                if (all) itemBox.addItem(it);
            }
            itemBox.setSelectedItem(chosenItem);
            itemEditor.setItem(chosenItem);
        } finally {
            filteringItems = false;
        }
    }

    /** The item box's text field: the picked item's name, or empty with the prompt as a hint. */
    private static final class ItemEditor implements javax.swing.ComboBoxEditor {
        final HintField field = new HintField();

        @Override public Component getEditorComponent() { return field; }

        @Override public void setItem(Object o) {
            // Typed text stays put while the list is narrowed; a picked item shows its name
            if (o instanceof TeleportItem) field.setText(((TeleportItem) o).getDisplayName());
            else if (o == null) field.setText("");
        }

        @Override public Object getItem() { return field.getText(); }

        @Override public void selectAll() { field.selectAll(); }

        @Override public void addActionListener(java.awt.event.ActionListener l) { field.addActionListener(l); }

        @Override public void removeActionListener(java.awt.event.ActionListener l) { field.removeActionListener(l); }
    }

    /** Point the teleport dropdowns at what was loaded from the step. */
    private void syncTeleControls() {
        int how = Math.max(0, Arrays.asList(TELE_HOW_KEYS).indexOf(teleMethod));
        teleHow.setSelectedIndex(how);
        showTeleCard(TELE_HOW_KEYS[how]);
        if (chosenSpell != null) spellBox.setSelectedItem(chosenSpell);
        if (chosenItem != null) itemBox.setSelectedItem(chosenItem);
        if (chosenNexus != null && FairyRings.METHOD.equals(teleMethod)) {
            String code = FairyRings.normalize(chosenNexus);
            for (int i = 1; i < ringBox.getItemCount(); i++) {
                if (ringBox.getItemAt(i).startsWith(FairyRings.spaced(code) + " - ")) ringBox.setSelectedIndex(i);
            }
        } else if (chosenNexus != null && SpiritTrees.METHOD.equals(teleMethod)) {
            String dest = SpiritTrees.destinationName(chosenNexus);
            if (dest != null) treeBox.setSelectedItem(dest);
        } else if (chosenNexus != null && isQuetzal(teleMethod)) {
            String site = Quetzals.site(chosenNexus);
            if (site != null) quetzalBox.setSelectedItem(site);
        } else if (chosenNexus != null) {
            nexusField.setText(chosenNexus);
        }
    }

    private static boolean isQuetzal(String key) {
        return Quetzals.METHOD_RENU.equals(key) || Quetzals.METHOD_WHISTLE.equals(key);
    }

    /** "C K R - Karamja", as listed in the fairy ring code dropdown. */
    private static String ringLabel(String code) {
        WorldPoint dest = FairyRings.destination(code);
        return FairyRings.spaced(code) + " - " + (dest != null ? LocationNames.describe(dest) : "?");
    }

    private void showTeleCard(String key) {
        boolean portal = "PORTAL".equals(key);
        nexusField.setHint(portal ? PORTAL_HINT : NEXUS_HINT);
        ((CardLayout) teleChoice.getLayout()).show(teleChoice, portal ? "NEXUS" : isQuetzal(key) ? QUETZAL_CARD : key);
    }

    /** A teleport was picked: aim the step at where it lands (the house has no tile to aim at). */
    private void teleportChosen(WorldPoint dest) {
        teleTouched = true;
        if (dest != null) {
            tileField.setText(TeleportItems.isHouse(dest) ? "" : formatTile(dest));
        }
        refresh();
    }

    private boolean teleOn() { return extraTele; }

    private boolean hasTeleport() {
        return ("SPELL".equals(teleMethod) && chosenSpell != null) || ("ITEM".equals(teleMethod) && chosenItem != null)
            || (("NEXUS".equals(teleMethod) || "PORTAL".equals(teleMethod)) && chosenNexus != null)
            || (FairyRings.METHOD.equals(teleMethod) && FairyRings.destination(chosenNexus) != null)
            || (isQuetzal(teleMethod) && Quetzals.destination(chosenNexus) != null)
            || (SpiritTrees.METHOD.equals(teleMethod) && SpiritTrees.destination(chosenNexus) != null);
    }

