        Integer h = configManager.getConfiguration(RoutePlannerConfig.GROUP, STEP_EDITOR_HEIGHT_KEY, Integer.class);
        int width = (w != null && w > 0) ? w : STEP_EDITOR_DEFAULT_WIDTH;
