    public void deleteRoute(Route route) {
        routeHistory.forget(route);
        if (activeRoute == route) {
            resumeRoute();
            activeRoute = null;
        }
        if (pausedRoute == route) pausedRoute = null;
        routes.remove(route);
        saveRoutes();
        saveActiveRoute();
        panel.refresh();
        skillingNpcHighlighter.rebuild();
    }

    public void setActiveRoute(Route route) {
        resumeRoute();
        this.activeRoute = route;
        this.pausedRoute = null;
        autoAdvanceSections();
        saveActiveRoute();
        panel.refresh();
        skillingNpcHighlighter.rebuild();
    }

    /** Deselect the active route, remembering it so it can be resumed. */
    public void pauseRoute() {
        Route active = activeRoute;
        if (active == null) return;
        setActiveRoute(null);
        pausedRoute = active;
        saveActiveRoute();
        panel.refresh();
    }

    /** Resume the paused route, if it's still there. */
    public void resumePausedRoute() {
        if (pausedRoute != null && routes.contains(pausedRoute)) setActiveRoute(pausedRoute);
    }

    public void renameRoute(Route route, String name) {
        route.setName(name);
        saveRoutes();
        if (route == activeRoute || route == pausedRoute) saveActiveRoute();
        panel.refresh();
    }

    public void addStep(Route route, RouteStep step) {
        addStep(route, step, panel != null ? panel.getSelectedSectionId() : null);
    }

    public void addStep(Route route, RouteStep step, String sectionId) {
        if (sectionId != null) route.addStepToSection(step, sectionId);
        else route.addStepToLastSection(step);
        saveRoutes();
        panel.refresh();
        // Rebuild NPC highlights immediately when a skilling step is added
        if (step.hasHighlight()) {
            skillingNpcHighlighter.rebuild();
        }
