    public void removeStep(Route route, RouteStep step) {
        routeHistory.push(route, "Delete step \"" + step.getName() + "\"", getRouteGson());
        route.removeStep(step);
        saveRoutes();
        panel.refresh();
    }

    /**
     * Complete a step only when EVERY trackable component present on it is satisfied.
     * A component that is absent is vacuously satisfied. This is the multi-component rule:
     * e.g. a Bank-items + Skill-goal step completes only after BOTH the items are held
     * AND the skill goal is reached.
     */
    /** For trackers outside the plugin: complete the step if everything on it is now met. */
    public void tryCompleteActiveStep(RouteStep step) {
        tryCompleteStep(step);
    }

    private void tryCompleteStep(RouteStep step) {
        if (step == null) return;
        if (activeRoute != null && step == activeRoute.getTestStep() && activeRoute.isTestPassed()) return;
        boolean itemsOk  = !step.hasItems()     || itemsSatisfied(step);
        boolean skillOk  = !step.hasSkillGoal() || skillGoalSatisfied(step);
        // Location: if worldPoint set, player must have reached it
        // (a catch step's tile is just where the shoal was met; it swims on, so catching anywhere counts)
        boolean locOk    = step.getWorldPoint() == null || step.isLocationReached() || step.hasCatchGoal();
        // Note: if note present, it must be manually marked complete (locationReached used as the ack flag)
        // Kill steps: enough kills, which also stands in for acknowledging the note.
        boolean killsOk  = step.getNpcKillCount() <= 0 || step.getNpcKillProgress() >= step.getNpcKillCount();
        // (a catch step's note, "Wait here for the shoal.", is guidance; the catch completes it)
        boolean noteOk   = !step.hasNote() || step.isLocationReached() || step.getNpcKillCount() > 0
            || step.hasCatchGoal();
        // Dialogue: every option in the sequence picked (arriving alone isn't enough).
        boolean dialogOk = step.getDialogOptions() == null || step.getDialogOptions().trim().isEmpty()
            || (step == lastDialogStep && dialogProgress >= step.getDialogOptions().split(",").length);
        // Quest: when set to complete with the quest, the quest must be finished.
        boolean questOk  = !step.hasQuest() || !step.isQuestComplete() || questFinished(step);
        // Boarding (Sailing): on the boat
        boolean boardOk  = !step.hasBoarding() || step.isBoarded();
        // Catch (Sailing): enough fish caught
        boolean catchOk  = !step.hasCatchGoal() || step.getCatchProgress() >= step.getCatchGoal();
        // Farming patch: replanted (or tended), whatever was grown in it
        boolean farmOk   = !step.hasFarmPatch() || step.isFarmDone();
        if (itemsOk && skillOk && locOk && noteOk && killsOk && dialogOk && questOk && boardOk && catchOk && farmOk) {
            completeStep(step);
        }
    }

    private void takeBaselines(RouteStep step) {
        boolean items = step.countsGainedItems();
        Skill skill = step.skill();
        boolean xp = skill != null && step.getSkillingGoalType() == SkillGoalType.XP_GAIN;
        long account = client.getAccountHash();
        if ((!items && !xp) || account == -1) return;
        boolean fresh = step.getBaselineAccount() != account
            || (items && step.getPickupBaseline() == null) || (xp && step.getSkillingStartXp() <= 0);
        if (!fresh) return;

        ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
        int nowXp = xp ? client.getSkillExperience(skill) : 0;
        if ((items && inv == null) || (xp && nowXp <= 0)) return; // not loaded yet; next tick
        if (items) step.setPickupBaseline(bankItemManager.snapshotInventory(step.getItemList()));
        if (xp) {
            step.setSkillingStartXp(nowXp);
            step.setSkillingProgress(0);
        }
        step.setBaselineAccount(account);
        saveRoutes();
    }

    /** Whether the game shows the step's progress check met (false without one). */
    private boolean progressMet(RouteStep step) {
        ProgressCheck check = step.progress();
        // A repeatable route would tick itself round forever on a check that stays met
        if (check == null || client.getGameState() != GameState.LOGGED_IN
            || (activeRoute != null && activeRoute.isRepeatable())) return false;
        try {
            int value = check.kind == ProgressCheck.Kind.VARBIT ? client.getVarbitValue(check.id) : client.getVarpValue(check.id);
            return check.isMet(value);
        } catch (RuntimeException e) {
            return false; // a var the game doesn't have (a typo in the route)
        }
    }

    private boolean questFinished(RouteStep step) {
        try {
            Quest q = Quest.valueOf(step.getQuestName());
            return q.getState(client) == QuestState.FINISHED;
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    private boolean itemsSatisfied(RouteStep step) {
        if (!step.hasItems()) return true;
        if (step.getItemMode() == ItemMode.SELL) {
            return step.isSellArmed() && bankItemManager.hasSoldAll(step.getItemList());
        }
        if (step.getItemMode() == ItemMode.USE_UP) {
            return step.isSellArmed() && bankItemManager.hasNoneUnnoted(step.getItemList());
        }
        if (step.countsGainedItems()) {
            // Only items picked up / bought since the step started count, never ones already carried.
            return step.getPickupBaseline() != null
                && bankItemManager.hasAllItemsAboveBaseline(step.getItemList(), step.getPickupBaseline());
        }
        return bankItemManager.hasAllItems(step.getItemList());
    }

    private boolean skillGoalSatisfied(RouteStep step) {
        if (!step.hasSkillGoal()) return true;
        Skill skill = step.skill();
        SkillGoalType goalType = step.getSkillingGoalType();
        if (skill == null || goalType == null) return false;
        if (goalType == SkillGoalType.XP_GAIN) {
            return step.getSkillingProgress() >= step.getSkillingGoalValue();
        } else if (goalType == SkillGoalType.XP_TARGET) {
            return client.getSkillExperience(skill) >= step.getSkillingGoalValue();
        } else {
            return client.getRealSkillLevel(skill) >= step.getSkillingGoalValue();
        }
    }

    /**
     * Developer mode (the client started with --developer-mode): make any step the active one to
     * try it out, without ticking the steps before it. Completing it doesn't tick it either; it
     * just says the test passed. {@link #resumeRoute()} goes back to the real active step.
     */
    public void testStep(RouteStep step) {
        if (activeRoute == null || step == null) return;
        resumeRoute();
        step.resetProgress();
        activeRoute.setTestStep(step);
        activeRoute.setTestPassed(false);
        autoAdvanceSections();
        refreshHighlights();
    }

    /** The section being re-recorded, or null. */
    @Getter private ReRecordSession reRecord;

    /**
     * Re-record a section of the active route: untick it and guide through just that section while
     * the recorder runs. {@link #endReRecord()} hands the session to the comparison afterwards.
     * Call on the client thread.
     */
    public void startReRecord(RouteSection section) {
        Route route = activeRoute;
        if (route == null || section == null || routeRecorder.isRecording()) return;
        resumeRoute();
        reRecord = new ReRecordSession(route, section);
        for (RouteStep s : section.getSteps()) {
            s.setCompleted(false);
            s.resetProgress();
        }
        route.setFocusSection(section);
        autoAdvanceSections();
        routeRecorder.start(route);
        highlightedStep = route.getActiveStep();
        refreshHighlights();
    }

    /** Stop guiding through the re-recorded section; returns its session (null if there was none). */
    public ReRecordSession endReRecord() {
        ReRecordSession session = reRecord;
        reRecord = null;
        if (session != null) {
            session.getRoute().setFocusSection(null);
            autoAdvanceSections();
            highlightedStep = activeRoute != null ? activeRoute.getActiveStep() : null;
        }
        return session;
    }

    public void resumeRoute() {
        if (activeRoute == null || activeRoute.getTestStep() == null) return;
        RouteStep step = activeRoute.getTestStep();
        activeRoute.setTestStep(null);
        activeRoute.setTestPassed(false);
        step.resetProgress();
        autoAdvanceSections();
        saveRoutes();
        refreshHighlights();
    }

    private void passStepTest(RouteStep step) {
        activeRoute.setTestPassed(true);
        String name = step.getName();
        clientThread.invokeLater(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
            "Route Planner test passed: \"" + name + "\" would tick itself off here.", null));
        if (panel != null) panel.refresh();
    }

    /** Force overlays/panel to re-read the active step immediately (e.g. after an edit). */
    public void refreshHighlights() {
        if (panel != null) panel.refresh();
        if (skillingNpcHighlighter != null) skillingNpcHighlighter.rebuild();
    }

    /**
     * Read the resource pack's overlay background color (RuneLite config "overlayBackgroundColor",
     * which resource packs set) and derive a matching HUD palette. Instant + exact + pack-aware,
     * and updates whenever the pack changes. Falls back to sprite sampling if the value is absent.
     */
    private void sampleInterfacePalette() {
        Integer argb = configManager.getConfiguration("runelite", "overlayBackgroundColor", Integer.class);
        if (argb != null) {
            Color base = new Color(argb, true); // decode ARGB, keep it opaque for the base
            Color solid = new Color(base.getRed(), base.getGreen(), base.getBlue());
            applyDerivedPalette(solid);
            return;
        }
        trySampleSprite(0);
    }

    /** Sprite IDs to try if the config color is unavailable (fallback path). */
    private static final int[] SAMPLE_SPRITE_IDS = { 297, 1035, 172, 173 };

    private void trySampleSprite(int idx) {
        if (idx >= SAMPLE_SPRITE_IDS.length) return;
        final int spriteId = SAMPLE_SPRITE_IDS[idx];
        spriteManager.getSpriteAsync(spriteId, 0, img -> {
            Color avg = averageColor(img);
            if (avg == null) {
                trySampleSprite(idx + 1);
                return;
            }
            applyDerivedPalette(avg);
        });
    }

    /** Mean RGB of the opaque pixels; null if the image is empty/too transparent. */
    private Color averageColor(BufferedImage img) {
        if (img == null) return null;
        long r = 0, g = 0, b = 0, n = 0;
        int w = img.getWidth(), h = img.getHeight();
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                int argb = img.getRGB(x, y);
                int a = (argb >>> 24) & 0xFF;
                if (a < 128) continue; // skip transparent
                r += (argb >> 16) & 0xFF;
                g += (argb >> 8) & 0xFF;
                b += argb & 0xFF;
                n++;
            }
        }
        if (n == 0) return null;
        return new Color((int)(r / n), (int)(g / n), (int)(b / n));
    }

    private Color lighten(Color c, double f) {
        int r = (int) Math.min(255, c.getRed()   + (255 - c.getRed())   * f);
        int g = (int) Math.min(255, c.getGreen() + (255 - c.getGreen()) * f);
        int b = (int) Math.min(255, c.getBlue()  + (255 - c.getBlue())  * f);
        return new Color(r, g, b);
    }

    private Color darken(Color c, double f) {
        return new Color(
            (int)(c.getRed() * (1 - f)),
            (int)(c.getGreen() * (1 - f)),
            (int)(c.getBlue() * (1 - f)));
    }

    /** Derive a full HUD palette from one sampled base color and write it to config (Theme -> Custom). */
    private void applyDerivedPalette(Color base) {
        Color body    = ColorUtil.colorWithAlpha(base, 64);
        Color border  = ColorUtil.colorWithAlpha(lighten(base, 0.35), 180);
        Color title   = lighten(base, 0.75);
        Color current = lighten(base, 0.9);
        Color next    = lighten(base, 0.55);
        Color have    = new Color(110, 210, 90); // keep green (functional signal)
        Color dim     = lighten(darken(base, 0.1), 0.4);
        Color divider = ColorUtil.colorWithAlpha(lighten(base, 0.4), 45);

        setCol("hudBgColor", body);
        setCol("hudBorderColor", border);
        setCol("hudTitleColor", title);
        setCol("hudCurrentColor", current);
        setCol("hudNextColor", next);
        setCol("hudHaveColor", have);
        setCol("hudDimColor", dim);
        setCol("hudDividerColor", divider);
        configManager.setConfiguration(RoutePlannerConfig.GROUP, "hudTheme", HudTheme.CUSTOM);
        refreshHighlights();
    }

    private void setCol(String key, Color c) {
        configManager.setConfiguration(RoutePlannerConfig.GROUP, key, c);
    }

    public void completeStep(RouteStep step) {
        if (activeRoute != null && step == activeRoute.getTestStep()) {
            passStepTest(step);
            return;
        }
        step.setCompleted(true);
        if (reRecord != null) reRecord.ticked(step, routeRecorder.getDraftCount());
        autoAdvanceSections();
        // If route is repeatable and all steps are now done, reset and restart
        if (activeRoute != null && activeRoute.isRepeatable() && reRecord == null
                && activeRoute.getActiveStep() == null) {
            resetRoute(activeRoute);
            return;
        }
        saveRoutes();
        panel.refresh();
        // The NPC highlighter only re-checks NPCs when told: drop the finished step's highlights now.
        skillingNpcHighlighter.rebuild();
        highlightedStep = activeRoute != null ? activeRoute.getActiveStep() : null;
    }

    /** Collapse any fully-completed OR not-yet-started section, and expand the one holding the
     *  active step. Runs after completing a step, and also once when a route is first activated --
     *  the latter matters because a freshly-selected route (nothing completed anywhere yet) would
     *  otherwise leave every section exactly as it was serialized/imported, which for a multi-
     *  section route (e.g. a large imported guide) means everything shows expanded at once. */
    private void autoAdvanceSections() {
        if (activeRoute == null) return;
        RouteSection activeSection = activeRoute.sectionOf(activeRoute.getActiveStep());
        for (RouteSection sec : activeRoute.getSections()) {
            if (sec == activeSection) {
                sec.setCollapsed(false);
                continue;
            }
            boolean hasSteps = sec.getSteps() != null && !sec.getSteps().isEmpty();
            boolean allDone = hasSteps && sec.getSteps().stream().allMatch(RouteStep::isCompleted);
            boolean noneDone = hasSteps && sec.getSteps().stream().noneMatch(RouteStep::isCompleted);
            if (allDone || noneDone) {
                sec.setCollapsed(true);
            }
            // A section that's partially in progress (some steps done, some not) but isn't the
            // active section is left as-is: the user may have manually expanded it on purpose.
        }
    }

    /**
     * Agility steps point at the course's first obstacle. The preset start tiles are estimates, so
     * once that obstacle is in the loaded scene, move the step onto it (and save). Works the same
     * for recorded, hand-made and Hub routes.
     */
    /** The agility step already on its first obstacle; it isn't scanned for again. */
    private RouteStep snappedAgilityStep;

    private void snapAgilityStart(RouteStep step) {
        if (step == snappedAgilityStep) return;
        if (step.isLocationReached() || !"AGILITY".equalsIgnoreCase(step.getSkillingSkill())) return;
        String name = step.getRecipeLabel() != null ? step.getRecipeLabel() : step.getAgilityCourse();
        if (name == null) return;
        AgilityCourse course = null;
        for (AgilityCourse c : AgilityCoursePresets.ALL) {
            if (c.getName().equalsIgnoreCase(name)) { course = c; break; }
        }
        if (course == null || course.getObstacles().isEmpty()) return;
        AgilityObstacle first = course.getObstacles().get(0);

        WorldPoint current = step.getWorldPoint();
        WorldPoint best = null;
        int bestDist = Integer.MAX_VALUE;
        WorldView wv = client.getTopLevelWorldView();
        if (wv == null || wv.isInstance()) return;
        Tile[][] plane = wv.getScene().getTiles()[wv.getPlane()];
        for (Tile[] row : plane) {
            for (Tile t : row) {
                if (t == null) continue;
                // Checked in place: a list per tile meant ~10,000 throwaway lists per scan.
                for (GameObject g : t.getGameObjects()) {
                    if (!SceneObjects.isObject(g)) continue;
                    WorldPoint at = obstacleAt(g, first);
                    if (at != null && obstacleDistance(current, at) < bestDist) { bestDist = obstacleDistance(current, at); best = at; }
                }
                for (int i = 0; i < 3; i++) {
                    TileObject o = i == 0 ? t.getWallObject() : i == 1 ? t.getDecorativeObject() : t.getGroundObject();
                    WorldPoint at = obstacleAt(o, first);
                    if (at != null && obstacleDistance(current, at) < bestDist) { bestDist = obstacleDistance(current, at); best = at; }
                }
            }
        }
        if (best == null) return; // not in the loaded scene yet; look again later
        snappedAgilityStep = step;
        if (current != null && current.getPlane() == best.getPlane() && current.distanceTo2D(best) <= 1) return;
        step.setWorldPoint(best);
        pathfinderOverlay.clearPath();
        saveRoutes();
    }

    private static WorldPoint obstacleAt(TileObject o, AgilityObstacle obstacle) {
        return o != null && obstacle.matchesId(o.getId()) ? o.getWorldLocation() : null;
    }

    private static int obstacleDistance(WorldPoint current, WorldPoint at) {
        return current == null || current.getPlane() != at.getPlane() ? 0 : current.distanceTo2D(at);
    }

    /** Hand the side panel's step card this tick's progress (only while the panel is open). */
    private void pushLive(RouteStep step) {
        if (panel == null || !panel.isShowing()) return;
        if (step == null) { panel.updateLive(null); return; }

        int dist = StepLive.NO_TARGET;
        WorldPoint wp = step.getWorldPoint();
        if (wp != null && lastPlayerLocation != null) {
            dist = PathfinderOverlay.otherFloor(wp, lastPlayerLocation) ? StepLive.OTHER_FLOOR
                : lastPlayerLocation.distanceTo2D(wp);
        }

        String header = null;
        List<BankItemManager.ItemProgress> items = null;
        if (step.hasItems() && step.getItemList() != null) {
            ItemMode mode = step.getItemMode();
            if (mode == ItemMode.SELL) {
                header = "Sell";
                items = new ArrayList<>();
                for (String[] st : bankItemManager.getSellStatusList(step.getItemList())) {
                    items.add(bankItemManager.soldLine(st[0], "SOLD".equals(st[1])));
                }
            } else {
                boolean gathering = step.getSkillingTargetNpc() != null || step.getSkillingTargetObject() != null;
                header = mode == ItemMode.SHOP ? "Buy" : mode == ItemMode.PICKUP ? (gathering ? "Gather" : "Pick up") : "Bring";
                items = bankItemManager.getItemProgress(step.getItemList(),
                    step.countsGainedItems() ? step.getPickupBaseline() : null);
            }
        }

        String skillLabel = null;
        long have = 0, need = 0;
        Skill sk = step.skill();
        SkillGoalType goal = step.getSkillingGoalType();
        if (sk != null && goal != null) {
            String name = sk.getName();
            need = step.getSkillingGoalValue();
            if (goal == SkillGoalType.XP_GAIN) { skillLabel = name + " XP gained"; have = step.getSkillingProgress(); }
            else if (goal == SkillGoalType.XP_TARGET) { skillLabel = name + " XP"; have = client.getSkillExperience(sk); }
            else { skillLabel = name + " level"; have = client.getRealSkillLevel(sk); }
        }
        int dialogDone = step == lastDialogStep ? dialogProgress : 0;
        panel.updateLive(new StepLive(step, dist, header, items, skillLabel, have, need, dialogDone));
    }

    public void resetRoute(Route route) {
        route.resetProgress();
        pathfinderOverlay.clearPath();
        saveRoutes();
        panel.refresh();
    }

    private Gson routeGson;
    private Gson exportGson;

    /** Reads and writes routes compactly: saves and undo snapshots aren't read by people, and
     *  indentation made them 2-3 times bigger. Either form reads back the same. */
    public Gson getRouteGson() {
        if (routeGson == null) {
            routeGson = gson.newBuilder()
                .registerTypeAdapter(WorldPoint.class, new RouteSerializer.WorldPointAdapter())
                .create();
        }
        return routeGson;
    }

    /** Like getRouteGson, but indented, for exported files people open and share. */
    public Gson getExportGson() {
        if (exportGson == null) exportGson = getRouteGson().newBuilder().setPrettyPrinting().create();
        return exportGson;
    }

    /**
     * Flip edit mode. Backed by the "mode" config key so the choice survives restarts; the panel
     * toggle is just the control surface. onConfigChanged refreshes the panel in response.
     */
    public void setMode(RouteMode mode) {
        configManager.setConfiguration(RoutePlannerConfig.GROUP, "mode", mode);
    }

    /** Undo the last structural edit on the active route. @return label undone, or null. */
    public String undoActive() {
        Route r = getActiveRoute();
        if (r == null) return null;
        String label = routeHistory.undo(r, getRouteGson());
        if (label != null) {
            saveRoutes();
            if (panel != null) panel.refresh();
        }
        return label;
    }

    /** Redo the last undone structural edit on the active route. @return label redone, or null. */
    public String redoActive() {
        Route r = getActiveRoute();
        if (r == null) return null;
        String label = routeHistory.redo(r, getRouteGson());
        if (label != null) {
            saveRoutes();
            if (panel != null) panel.refresh();
        }
        return label;
    }

    private static final String ACTIVE_ROUTE_KEY = "activeRoute";
    /** "true" when no route is active: the one under ACTIVE_ROUTE_KEY (if any) is paused. */
    private static final String ROUTE_PAUSED_KEY = "activeRoutePaused";

    /**
     * Saves the active (or paused) route for the logged-in character, and globally as the
     * fallback for characters that haven't picked a route yet.
     */
    private void saveActiveRoute() {
        Route remembered = activeRoute != null ? activeRoute : pausedRoute;
        boolean paused = activeRoute == null;
        boolean perCharacter = configManager.getRSProfileKey() != null;
        if (remembered != null) {
            configManager.setConfiguration(RoutePlannerConfig.GROUP, ACTIVE_ROUTE_KEY, remembered.getName());
            if (perCharacter) {
                configManager.setRSProfileConfiguration(RoutePlannerConfig.GROUP, ACTIVE_ROUTE_KEY, remembered.getName());
            }
        } else {
            configManager.unsetConfiguration(RoutePlannerConfig.GROUP, ACTIVE_ROUTE_KEY);
            if (perCharacter) configManager.unsetRSProfileConfiguration(RoutePlannerConfig.GROUP, ACTIVE_ROUTE_KEY);
        }
        configManager.setConfiguration(RoutePlannerConfig.GROUP, ROUTE_PAUSED_KEY, paused);
        if (perCharacter) configManager.setRSProfileConfiguration(RoutePlannerConfig.GROUP, ROUTE_PAUSED_KEY, paused);
    }

    /** The route that was active (or paused) last time. With nothing saved yet, the first route is active. */
    private void restoreActiveRoute() {
        String savedName = configManager.getConfiguration(RoutePlannerConfig.GROUP, ACTIVE_ROUTE_KEY);
        boolean paused = "true".equals(configManager.getConfiguration(RoutePlannerConfig.GROUP, ROUTE_PAUSED_KEY));
        Route saved = findRoute(savedName);
        if (paused) {
            pausedRoute = saved;
        } else if (saved != null) {
            activeRoute = saved;
        } else if (savedName == null && !routes.isEmpty()) {
            activeRoute = routes.get(0);
        }
    }

    private Route findRoute(String name) {
        if (name == null) return null;
        return routes.stream().filter(r -> name.equals(r.getName())).findFirst().orElse(null);
    }

    /**
     * On login (or switching account/world type), switches to the route this character had.
     * A character with no saved choice keeps the current route and adopts it as its own.
     */
    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event) {
        if (configManager.getRSProfileKey() == null) return;
        String pausedValue = configManager.getRSProfileConfiguration(RoutePlannerConfig.GROUP, ROUTE_PAUSED_KEY);
        if (pausedValue == null) {
            saveActiveRoute();
            return;
        }
        String savedName = configManager.getRSProfileConfiguration(RoutePlannerConfig.GROUP, ACTIVE_ROUTE_KEY);
        Route saved = findRoute(savedName);
        boolean paused = "true".equals(pausedValue);
        Route wantActive = paused ? null : saved;
        Route wantPaused = paused ? saved : null;
        if (wantActive == activeRoute && wantPaused == pausedRoute) return;

        resumeRoute();
        activeRoute = wantActive;
        pausedRoute = wantPaused;
        autoAdvanceSections();
        saveActiveRoute();
        skillingNpcHighlighter.rebuild();
        if (panel != null) SwingUtilities.invokeLater(panel::refresh);
    }

    private static final String ROUTES_BACKUP_KEY = "routesBackup";
    /** Set when the saved routes couldn't be read: saving is then off so they aren't overwritten. */
    private boolean routesLoadFailed = false;

    public void saveRoutes() {
        if (routesLoadFailed) {
            log.warn("Route Planner: not saving, the saved routes couldn't be loaded (copy kept under '{}')", ROUTES_BACKUP_KEY);
            return;
        }
        configManager.setConfiguration(RoutePlannerConfig.GROUP, "routes", RouteSerializer.toJson(routes, getRouteGson()));
    }

    private void loadRoutes() {
        String json = configManager.getConfiguration(RoutePlannerConfig.GROUP, "routes");
        try {
            routes = RouteSerializer.fromJson(json, getRouteGson());
            routesLoadFailed = false;
        } catch (Exception e) {
            // Keep the unreadable text and don't save over it, so nothing is lost and a fix can recover it.
            log.error("Route Planner: couldn't load the saved routes; saving is off until this is fixed", e);
            configManager.setConfiguration(RoutePlannerConfig.GROUP, ROUTES_BACKUP_KEY, json);
            routes = new ArrayList<>();
            routesLoadFailed = true;
            clientThread.invokeLater(() -> {
                if (client.getGameState() != GameState.LOGGED_IN) return false; // try again next tick
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                    "Route Planner couldn't load your saved routes. They're kept safe and nothing will be "
                        + "saved over them; changes made now won't be saved.", null);
                return true;
            });
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        pathfinderOverlay.onGameTick();
        sailingTimers.onGameTick();

        if (client.getLocalPlayer() != null) {
            lastPlayerLocation = Sailing.position(client);
        }

        settleKills();
        RouteStep step = activeRoute != null ? activeRoute.getActiveStep() : null;
        // Any other way the step changes (undo, reset, a step marked incomplete, another route): re-light NPCs
        if (step != highlightedStep) {
            highlightedStep = step;
            skillingNpcHighlighter.rebuild();
        }
        skillingNpcHighlighter.onGameTick();
        plantedSpiritTrees.onGameTick();
        if (activeRoute == null) { pushLive(null); return; }
        pushLive(step);
        if (step == null) { lastDialogStep = null; return; }

        // The order matters: baselines before the item check, and boarding before arrival.
        if (client.getTickCount() % 5 == 0) snapAgilityStart(step);
        refreshNpcHighlights(step);
        // Baselines, taken the moment the step becomes active: the inventory for PICKUP/SHOP (so
        // carried-over items don't count; MUST happen before the completion check) and the starting
        // XP for XP_GAIN (so the very first drop counts). They're saved with the step, so a reload
        // carries on; a reset, an imported route or another account takes fresh ones.
        takeBaselines(step);
        // The game already shows this step done (a quest stage or diary task): tick it off, one
        // step a tick, so steps done before the route got to them pass by quickly.
        if (progressMet(step)) {
            completeStep(step);
            return;
        }
        // Quest steps set to complete with the quest: check now and then (it runs a client script).
        if (step.hasQuest() && step.isQuestComplete() && client.getTickCount() % 3 == 0) tryCompleteStep(step);
        checkItems(step);
        startKillCount(step);
        trackDialogue(step);
        dialogHighlighter.apply();
        checkTeleportArrival(step);
        if (checkBoarding(step)) return;
        checkArrival(step);
    }

    /** Rebuild NPC highlights now and then while a step highlights NPCs, so ones that came into
     *  the 30-tile range since they spawned light up (the overlay service only checks at spawn). */
    private void refreshNpcHighlights(RouteStep step) {
        // Kept to an area, NPCs walking in and out of it need a quicker look
        int every = step.isHighlightInAreaOnly() && areaOf(step) != null ? 2 : 10;
        if (step.isHighlightEnabled() && (step.getSkillingTargetNpc() != null || step.getNpcHighlight() != null)
                && client.getTickCount() % every == 0) {
            skillingNpcHighlighter.rebuild();
        }
    }

    private void checkItems(RouteStep step) {
        if (!step.hasItems()) return;
        boolean done;
        if (step.getItemMode() == ItemMode.DEPOSIT_ALL) {
            done = depositDone(step);
        } else {
            // SELL arms once the items are seen in the inventory, and completes only after they're gone.
            if (step.getItemMode() == ItemMode.SELL && !bankItemManager.hasSoldAll(step.getItemList())) {
                step.setSellArmed(true);
            }
            // USE_UP too: with none ever carried (a dead patch gave nothing) it waits to be ticked off,
            // rather than passing before the harvest even happened
            if (step.getItemMode() == ItemMode.USE_UP && !bankItemManager.hasNoneUnnoted(step.getItemList())) {
                step.setSellArmed(true);
            }
            done = itemsSatisfied(step);
        }
        if (done) tryCompleteStep(step);
    }

    /** Any bank counts as being there (banks have many booths). About 3 seconds after it opens,
     *  check the inventory; keep checking while it's open until it's empty. */
    private boolean depositDone(RouteStep step) {
        Widget bankWidget = client.getWidget(InterfaceID.Bankmain.ITEMS);
        boolean bankOpen = bankWidget != null && !bankWidget.isHidden();
        if (!bankOpen || step != depositStep) {
            depositStep = step;
            depositOpenTick = bankOpen ? client.getTickCount() : -1;
        } else if (depositOpenTick < 0) {
            depositOpenTick = client.getTickCount();
        }
        if (bankOpen) step.setLocationReached(true);
        if (!bankOpen || client.getTickCount() - depositOpenTick < DEPOSIT_CHECK_TICKS) return false;
        ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
        return inv != null && Arrays.stream(inv.getItems()).allMatch(i -> i.getId() <= 0);
    }

    /** Light up the NPC when a kill step becomes active. Its kills so far are saved with it. */
    private void startKillCount(RouteStep step) {
        if (step.getNpcHighlight() != null && step.getNpcKillCount() > 0 && step != lastKillStep) {
            lastKillStep = step;
            skillingNpcHighlighter.rebuild();
        }
    }

    /** Dialogue option highlighting: advance through the sequence as menus open/close. */
    private void trackDialogue(RouteStep step) {
        if (step.getDialogOptions() == null || step.getDialogOptions().trim().isEmpty()) {
            lastDialogStep = null;
            return;
        }
        if (step != lastDialogStep) {
            lastDialogStep = step;
            dialogProgress = 0;
            dialogOptionsVisibleLast = false;
            anyDialogueOpenLast = false;
        }
        Widget optWidget = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
        boolean optionsVisible = optWidget != null && !optWidget.isHidden();
        boolean anyOpen = optionsVisible || isAnyDialogueOpen();
        if (anyOpen && !anyDialogueOpenLast) {
            dialogProgress = 0;
            dialogPartnerOk = false;
        }
        if (anyOpen && !dialogPartnerOk) dialogPartnerOk = talkingToStepNpc(step);
        if (!optionsVisible && dialogOptionsVisibleLast && dialogPartnerOk) {
            dialogProgress++;
            if (dialogProgress >= step.getDialogOptions().split(",").length) {
                tryCompleteStep(step);
            }
        }
        dialogOptionsVisibleLast = optionsVisible;
        anyDialogueOpenLast = anyOpen;
    }

    /** Teleport arrival. Landing only finishes the step when the teleport spot IS the goal: no
     *  tile of its own, or a tile at the landing spot. A tile somewhere else still has to be
     *  walked to after landing (e.g. teleport to Varrock, then go to the east bank). */
    private void checkTeleportArrival(RouteStep step) {
        if (step.getTeleportDestination() == null || step.hasSkillGoal() || step.hasItems() || step.hasNote()
                || client.getLocalPlayer() == null) return;
        WorldPoint dest = step.getTeleportDestination();
        WorldPoint goal = step.getWorldPoint();
        boolean house = TeleportItems.isHouse(dest);
        boolean landingIsGoal = goal == null
            || (!house && goal.getPlane() == dest.getPlane() && goal.distanceTo2D(dest) <= 25);
        if (!landingIsGoal) return;
        WorldPoint playerPos = Sailing.position(client);
        boolean landed = house
            ? client.getTopLevelWorldView().isInstance() // the house has no fixed tile
            : playerPos.getPlane() == dest.getPlane() && playerPos.distanceTo2D(dest) <= 25;
        if (landed) {
            if (goal != null) step.setLocationReached(true);
            // Through the full check: chat options or a quest on the step still count.
            tryCompleteStep(step);
        }
    }

    /** Boarding (Sailing): getting on a boat ends the walk to the gangplank. A step that only asks
     *  you to board is then done; otherwise it carries on over the sea. @return true if that completed it */
    private boolean checkBoarding(RouteStep step) {
        if (!step.hasBoarding() || step.isBoarded() || !Sailing.isSailing(client)) return false;
        step.setBoarded(true);
        tryCompleteStep(step);
        return step.isCompleted();
    }

    private void checkArrival(RouteStep step) {
        boolean boardingPending = pathfinderOverlay.isBoardingPending(step);

        // Sticky "reached": once we arrive, nav visuals (line + tile) switch off for the rest of the step
        if (step.getWorldPoint() != null && !step.isLocationReached() && !boardingPending
                && client.getLocalPlayer() != null && isAtStep(step)) {
            step.setLocationReached(true);
            arrivalHoldTicksRemaining = config.arrivalHideDelay(); // 30 = never hide until the step completes
        }

        // Count down the arrival-hold timer each tick; at the max (30) it never counts down.
        if (arrivalHoldTicksRemaining > 0 && arrivalHoldTicksRemaining < 30) arrivalHoldTicksRemaining--;

        if (step.getWorldPoint() != null && !step.hasSkillGoal() && !step.hasItems() && !boardingPending
                && (!step.hasNote() || step.isNoteAutoComplete())) {
            if (isAtStep(step)) {
                // Through the full check: a Talk-to or quest step still waits for its picks/quest.
                tryCompleteStep(step);
            }
        }
    }

    /** The step's drawn area, or null when it goes by its tile. */
    public TileArea areaOf(RouteStep step) {
        return step != null ? step.area() : null;
    }

    /** Whether the step highlights something on tile {@code p}: anywhere, unless it keeps highlights to its area. */
    public boolean highlightAllowed(RouteStep step, WorldPoint p) {
        TileArea area = step != null && step.isHighlightInAreaOnly() ? areaOf(step) : null;
        return area == null || area.contains(p);
    }

    /** As {@link #highlightAllowed(RouteStep, WorldPoint)} for something covering w x h tiles from {@code sw}: any of them. */
    public boolean highlightAllowed(RouteStep step, WorldPoint sw, int w, int h) {
        TileArea area = step != null && step.isHighlightInAreaOnly() ? areaOf(step) : null;
        if (area == null) return true;
        if (sw.getPlane() != area.getPlane()) return false;
        for (int x = 0; x < w; x++)
            for (int y = 0; y < h; y++) if (area.contains(sw.getX() + x, sw.getY() + y)) return true;
        return false;
    }

    /** Anywhere in the step's area, or else within 3 tiles of its tile (from the hull while sailing). */
    private boolean isAtStep(RouteStep step) {
        TileArea area = areaOf(step);
        if (area != null) {
            WorldPoint at = Sailing.position(client);
            return at != null && area.contains(at);
        }
        return Sailing.isWithin(client, step.getWorldPoint(), 3);
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();
        if (step == null) return;
        Skill skill = step.skill();
        SkillGoalType goalType = step.getSkillingGoalType();
        if (skill == null || goalType == null || event.getSkill() != skill) return;

        if (goalType == SkillGoalType.XP_GAIN) {
            if (step.getSkillingStartXp() <= 0) {
                step.setSkillingStartXp(event.getXp());
                return;
            }
            long gained = event.getXp() - step.getSkillingStartXp();
            step.setSkillingProgress(gained);
            if (gained >= step.getSkillingGoalValue()) {
                tryCompleteStep(step);
            }
            // No panel rebuild per XP drop: the step card's live progress already shows it.
        } else if (goalType == SkillGoalType.XP_TARGET) {
            if (event.getXp() >= step.getSkillingGoalValue()) {
                tryCompleteStep(step);
            }
        } else if (event.getLevel() >= step.getSkillingGoalValue()) {
            tryCompleteStep(step);
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();
        if (step == null || step.getTargetId() <= 0) return; // -1 = none; 0 = left out of older saves
        // The kill is one goal; the step's others (items, location, ...) still have to be met.
        if (event.getNpc().getId() == step.getTargetId() && event.getNpc().isDead()
            && killCredit.isMine(event.getNpc(), client.getTickCount())) {
            tryCompleteStep(step);
        }
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event) {
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();
        if (step == null || !step.hasItems()) return;
        if (event.getTile().getWorldLocation().equals(step.getWorldPoint())) {
            tryCompleteStep(step);
        }
    }

    @Provides
    RoutePlannerConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(RoutePlannerConfig.class);
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (event.getActor() instanceof NPC && event.getHitsplat().isMine()) {
            killCredit.onHit(event.getActor(), client.getTickCount());
        }
    }

    @Subscribe
    public void onActorDeath(ActorDeath event) {
        if (event.getActor() instanceof NPC) pendingKills.add((NPC) event.getActor());
    }

    /** Count this tick's deaths toward the active kill step, if they're the step's NPC and the player's kill. */
    private void settleKills() {
        if (pendingKills.isEmpty()) return;
        List<NPC> deaths = new ArrayList<>(pendingKills);
        pendingKills.clear();
        RouteStep step = activeRoute != null ? activeRoute.getActiveStep() : null;
        if (step == null || step.getNpcHighlight() == null || step.getNpcKillCount() <= 0) return;
        boolean counted = false;
        for (NPC npc : deaths) {
            if (!NpcNames.matches(step.getNpcHighlight(), npc.getName())) continue;
            if (!killCredit.isMine(npc, client.getTickCount())) continue;
            step.setNpcKillProgress(step.getNpcKillProgress() + 1);
            counted = true;
        }
        if (!counted) return;
        if (step.getNpcKillProgress() >= step.getNpcKillCount()) {
            tryCompleteStep(step);
        }
        if (!step.isCompleted()) saveRoutes();
    }

    /** Trawling catches (Sailing) count toward the active step's catch goal. */
    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) return;
        if (activeRoute == null) return;
        RouteStep step = activeRoute.getActiveStep();
        if (step == null || !step.hasCatchGoal()) return;
        CatchMessages.Catch c = CatchMessages.parse(event.getMessage());
        if (c == null || !CatchMessages.sameFish(c.fish, step.getCatchFish())) return;
        step.setCatchProgress(step.getCatchProgress() + c.count);
        tryCompleteStep(step);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING) {
            sailingDocks.reset();
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!RoutePlannerConfig.GROUP.equals(event.getGroup())) return;
        if ("mode".equals(event.getKey())) {
            if (panel != null) {
                SwingUtilities.invokeLater(panel::refresh);
            }
        }
        if ("pathfinder".equals(event.getKey())) {
            pathfinderOverlay.clearPath();
        }
        if ("hudMatchInterface".equals(event.getKey()) && "true".equals(event.getNewValue())) {
            sampleInterfacePalette();
            configManager.setConfiguration(RoutePlannerConfig.GROUP, "hudMatchInterface", false);
        }
    }
}

package com.routeplanner;

import java.util.Arrays;

/**
 * The open and closed sets of one A* search in flat arrays: an open-addressing table from a packed
 * tile key to a node index, per-node cost and parent arrays, and a binary heap of node indices.
 * A route over the sea can explore a million tiles, which as HashMaps of WorldPoints takes several
 * times the memory and time.
 */
final class SearchGraph {

    static final int NONE = -1;

    private long[] tableKeys;
    private int[] tableNodes;
    private int tableMask;

    private long[] keys;
    private int[] g;
    private int[] f;
    private int[] parent;
    private int size;

    /** Queued entries as (f << 32 | node), so a node queued again at a lower cost leaves its old entry stale, not misplaced. */
    private long[] heap;
    private int heapSize;

    SearchGraph(int expected) {
        int cap = Integer.highestOneBit(Math.max(16, expected * 2) - 1) << 1;
        tableKeys = new long[cap];
        tableNodes = new int[cap];
        Arrays.fill(tableNodes, NONE);
        tableMask = cap - 1;
        keys = new long[expected];
        g = new int[expected];
        f = new int[expected];
        parent = new int[expected];
        heap = new long[expected];
    }

    static long key(int x, int y, int plane) {
        return ((long) plane << 32) | ((long) (x & 0xFFFF) << 16) | (y & 0xFFFF);
    }

    static int x(long key) { return (int) ((key >>> 16) & 0xFFFF); }
    static int y(long key) { return (int) (key & 0xFFFF); }
    static int plane(long key) { return (int) (key >>> 32); }

    int size() { return size; }
    long key(int node) { return keys[node]; }
    int g(int node) { return g[node]; }
    int parent(int node) { return parent[node]; }

    /** The node for {@code key}, or NONE if it hasn't been reached. */
    int find(long key) {
        int slot = slot(key);
        while (tableNodes[slot] != NONE) {
            if (tableKeys[slot] == key) return tableNodes[slot];
            slot = (slot + 1) & tableMask;
        }
        return NONE;
    }

    /**
     * Records reaching {@code key} at cost {@code cost} from {@code from} and queues it, unless it was
     * already reached at least as cheaply. Returns whether it was queued.
     */
    boolean offer(long key, int cost, int estimate, int from) {
        int node = find(key);
        if (node == NONE) {
            if (size == keys.length) grow();
            node = size++;
            keys[node] = key;
            insert(key, node);
        } else if (cost >= g[node]) {
            return false;
        }
        g[node] = cost;
        f[node] = cost + estimate;
        parent[node] = from;
        push(((long) f[node] << 32) | node);
        return true;
    }

    boolean isEmpty() { return heapSize == 0; }

    /**
     * Removes the queued node with the lowest estimate, skipping entries left behind when a node was
     * queued again more cheaply. Returns NONE once nothing is left.
     */
    int poll() {
        while (heapSize > 0) {
            long top = heap[0];
            heap[0] = heap[--heapSize];
            siftDown(0);
            int node = (int) top;
            if ((int) (top >>> 32) == f[node]) return node;
        }
        return NONE;
    }

    private int slot(long key) {
        long h = key * 0x9E3779B97F4A7C15L;
        return (int) (h >>> 40) & tableMask;
    }

    private void insert(long key, int node) {
        if (size * 2 > tableKeys.length) rehash();
        int slot = slot(key);
        while (tableNodes[slot] != NONE) slot = (slot + 1) & tableMask;
        tableKeys[slot] = key;
        tableNodes[slot] = node;
    }

    private void rehash() {
        long[] oldKeys = tableKeys;
        int[] oldNodes = tableNodes;
        tableKeys = new long[oldKeys.length * 2];
        tableNodes = new int[oldNodes.length * 2];
        Arrays.fill(tableNodes, NONE);
        tableMask = tableKeys.length - 1;
        for (int i = 0; i < oldKeys.length; i++) {
            if (oldNodes[i] == NONE) continue;
            int slot = slot(oldKeys[i]);
            while (tableNodes[slot] != NONE) slot = (slot + 1) & tableMask;
            tableKeys[slot] = oldKeys[i];
            tableNodes[slot] = oldNodes[i];
        }
    }

    private void grow() {
        int cap = keys.length * 2;
        keys = Arrays.copyOf(keys, cap);
        g = Arrays.copyOf(g, cap);
        f = Arrays.copyOf(f, cap);
        parent = Arrays.copyOf(parent, cap);
    }

    // Entries compare as plain longs: f is the high half, so the lowest f comes out first.
    private void push(long entry) {
        if (heapSize == heap.length) heap = Arrays.copyOf(heap, heap.length * 2);
        int i = heapSize++;
        while (i > 0) {
            int up = (i - 1) >> 1;
            if (heap[up] <= entry) break;
            heap[i] = heap[up];
            i = up;
        }
        heap[i] = entry;
    }

    private void siftDown(int i) {
        if (heapSize == 0) return;
        long entry = heap[i];
        while (true) {
            int child = 2 * i + 1;
            if (child >= heapSize) break;
            if (child + 1 < heapSize && heap[child + 1] < heap[child]) child++;
            if (heap[child] >= entry) break;
            heap[i] = heap[child];
            i = child;
        }
        heap[i] = entry;
    }
}

package com.routeplanner;

import lombok.RequiredArgsConstructor;
import com.routeplanner.transport.Transport;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.*;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.*;
import javax.inject.*;
import java.util.*;
import java.util.regex.*;

/**
 * Optional bridge to the Shortest Path plugin's cross-plugin API
 * (https://github.com/Skretzo/shortest-path/blob/master/docs/Cross-plugin-communication.md).
 *
 * Plugin Hub plugins can't share classes, so this talks to Shortest Path purely through
 * PluginMessage events: a "query" asks it to compute a path without drawing anything, and it
 * answers with a "result" carrying the same id. The answer may be posted from Shortest Path's
 * own pathfinding thread, so the handler only stashes it in a volatile field; everything else
 * here runs on the client thread via PathfinderOverlay.onGameTick.
 *
 * When Shortest Path isn't installed/enabled, or stops answering (e.g. an older version
 * without query support), isActive() goes false and the built-in A* is used instead.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ShortestPathBridge {

    private static final String NAMESPACE = "shortestpath";
    private static final String PLUGIN_NAME = "Shortest Path";
    private static final String ID_PREFIX = "routeplanner-";
    /** Pathfinder updates (every 2 game ticks) to wait for an answer before giving up. */
    private static final int RESPONSE_TIMEOUT_UPDATES = 4;
    /** Pathfinder updates to wait after a timeout before trying Shortest Path again (~2 min). */
    private static final int RETRY_AFTER_TIMEOUT_UPDATES = 100;

    /** An answer to one of our queries, already converted to plain route-planner types. */
    @RequiredArgsConstructor
    public static final class Result {
        final String id;
        final List<WorldPoint> path;
        final boolean reached;
        final boolean cancelled;
        /** Shortest Path's own description of each jump on the path (stairs, teleports...). */
        final List<Transport> jumps;

    }

    private final EventBus eventBus;
    private final PluginManager pluginManager;
    private final RoutePlannerConfig config;

    private int nextId = 0;
    private String pendingId;
    private WorldPoint pendingTarget;
    private int updatesWaiting;
    private int timeoutCooldown;
    private volatile Result latest;

    /** True when the user picked Shortest Path and it's installed, enabled and answering. */
    public boolean isActive() {
        return config.pathfinder() == PathfinderMode.SHORTEST_PATH
            && timeoutCooldown == 0
            && isShortestPathEnabled();
    }

    private boolean isShortestPathEnabled() {
        for (Plugin p : pluginManager.getPlugins()) {
            PluginDescriptor d = p.getClass().getAnnotation(PluginDescriptor.class);
            if (d != null && PLUGIN_NAME.equalsIgnoreCase(d.name())) {
                return pluginManager.isPluginEnabled(p);
            }
        }
        return false;
    }

    /**
     * Advance timers once per pathfinder update. Returns true if a pending query just timed out,
     * meaning the caller should rebuild with the built-in pathfinder right away.
     */
    public boolean tick() {
        if (timeoutCooldown > 0) timeoutCooldown--;
        if (pendingId == null) return false;
        if (++updatesWaiting <= RESPONSE_TIMEOUT_UPDATES) return false;
        reset();
        timeoutCooldown = RETRY_AFTER_TIMEOUT_UPDATES;
        return true;
    }

    /** Ask Shortest Path for a path. A no-op if we're already waiting on the same target. */
    public void request(WorldPoint start, WorldPoint target) {
        if (pendingId != null && target.equals(pendingTarget)) return;
        pendingId = ID_PREFIX + (nextId++);
        pendingTarget = target;
        updatesWaiting = 0;
        latest = null;

        Map<String, Object> data = new HashMap<>();
        data.put("id", pendingId);
        data.put("start", start);
        data.put("target", target);
        if (config.recordTrace()) log.info("[RP-TRACE] SP ASK {} from {} to {}", pendingId, start, target);
        eventBus.post(new PluginMessage(NAMESPACE, "query", data));
    }

    /** Returns the answer to the pending query for this target once it has arrived, else null. */
    public Result takeResult(WorldPoint target) {
        Result r = latest;
        if (r == null || pendingId == null || !pendingId.equals(r.id)) return null;
        boolean forTarget = target.equals(pendingTarget);
        reset();
        return forTarget ? r : null;
    }

    /** Forget any in-flight query, so a late answer to it is ignored. */
    public void reset() {
        pendingId = null;
        pendingTarget = null;
        updatesWaiting = 0;
        latest = null;
    }

    /**
     * Shortest Path's "transports" list: per jump its origin, destination, objectInfo ("Climb-down
     * Ladder 2147", none for a teleport) and displayInfo ("Guardians of the Rift Minigame Teleport").
     */
    private static List<Transport> jumps(Object raw) {
        List<Transport> out = new ArrayList<>();
        if (!(raw instanceof List)) return out;
        for (Object o : (List<?>) raw) {
            if (!(o instanceof Map)) continue;
            Map<?, ?> m = (Map<?, ?>) o;
            if (!(m.get("origin") instanceof WorldPoint) || !(m.get("destination") instanceof WorldPoint)) continue;
            String object = m.get("objectInfo") instanceof String ? ((String) m.get("objectInfo")).trim() : "";
            String display = m.get("displayInfo") instanceof String ? ((String) m.get("displayInfo")).trim() : "";
            int objectId = -1;
            String action = object;
            Matcher id = Pattern.compile("^(.*\\S)\\s+(\\d+)$").matcher(object);
            if (id.matches()) {
                action = id.group(1);
                objectId = Integer.parseInt(id.group(2));
            }
            boolean teleport = object.isEmpty();
            String text = teleport ? (display.isEmpty() ? "Teleport" : "Teleport: " + display)
                : (action.isEmpty() ? display : action);
            out.add(new Transport((WorldPoint) m.get("origin"),
                (WorldPoint) m.get("destination"), text.isEmpty() ? null : text, objectId, teleport));
        }
        return out;
    }

    @Subscribe
    public void onPluginMessage(PluginMessage message) {
        if (!NAMESPACE.equals(message.getNamespace()) || !"result".equals(message.getName())) return;
        Map<String, Object> data = message.getData();
        Object id = data.get("id");
        if (!(id instanceof String) || !((String) id).startsWith(ID_PREFIX)) return;

        List<WorldPoint> path = new ArrayList<>();
        Object rawPath = data.get("path");
        if (rawPath instanceof List) {
            for (Object o : (List<?>) rawPath) {
                if (o instanceof WorldPoint) path.add((WorldPoint) o);
            }
        }
        boolean reached = Boolean.TRUE.equals(data.get("reached"));
        boolean cancelled = "CANCELLED".equals(data.get("reason"));
        if (config.recordTrace()) {
            log.info("[RP-TRACE] SP REPLY {} reached={} reason={} tiles={} end={} closest={} jumps={} transports={}", id,
                reached, data.get("reason"), path.size(), path.isEmpty() ? null : path.get(path.size() - 1),
                data.get("closest"), PathfinderOverlay.describeJumps(path), data.get("transports"));
        }
        latest = new Result((String) id, path, reached, cancelled, jumps(data.get("transports")));
    }
}

package com.routeplanner;

import lombok.RequiredArgsConstructor;
import com.routeplanner.model.RouteStep;
import com.routeplanner.sailing.Sailing;
import com.routeplanner.teleport.Quetzals;
import com.routeplanner.util.NpcNames;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.npcoverlay.*;
import javax.inject.*;
import java.util.*;
import java.util.function.Function;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SkillingNpcHighlighter {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final NpcOverlayService npcOverlayService;
    private final Function<NPC, HighlightedNpc> highlightFunction = this::shouldHighlight;

    public void startUp() {
        npcOverlayService.registerHighlighter(highlightFunction);
    }

    public void rebuild() {
        npcOverlayService.rebuild();
    }

    public void shutDown() {
        npcOverlayService.unregisterHighlighter(highlightFunction);
    }

    // No NpcSpawned/NpcDespawned handlers: NpcOverlayService checks new NPCs itself, and a full
    // rebuild on every spawn re-ran shouldHighlight for every NPC in the scene.

    /** The target names, lower-cased, parsed once per target string instead of once per NPC. */
    private String parsedTarget;
    private List<String> targetNames = Collections.emptyList();

    private List<String> targetNames(String target) {
        if (!target.equals(parsedTarget)) {
            targetNames = NpcNames.parse(target);
            parsedTarget = target;
        }
        return targetNames;
    }

    /** Targets that an NPC in range is named exactly; their longer-named lookalikes stay dark. */
    private Set<String> exactNearby = Collections.emptySet();

    /** Once a tick: re-check which targets have an exact-named NPC in range, re-lighting if that changed. */
    public void onGameTick() {
        String target = target(activeStep());
        Set<String> exact = new HashSet<>();
        WorldPoint at = target == null ? null : Sailing.position(client);
        if (at != null && client.getTopLevelWorldView() != null) {
            List<String> names = targetNames(target);
            int range = range();
            for (NPC npc : client.getTopLevelWorldView().npcs()) {
                if (npc == null) continue;
                String t = NpcNames.exactTarget(names, npc.getName());
                if (t != null && npc.getWorldLocation().distanceTo(at) <= range) exact.add(t);
            }
        }
        if (!exact.equals(exactNearby)) {
            exactNearby = exact;
            rebuild();
        }
    }

    private RouteStep activeStep() {
        return plugin.getActiveRoute() == null ? null : plugin.getActiveRoute().getActiveStep();
    }

    /** The step's NPC target text, or null when it highlights no NPC. */
    private static String target(RouteStep step) {
        if (step == null || !step.isHighlightEnabled()) return null;
        String t = step.getSkillingTargetNpc() != null ? step.getSkillingTargetNpc() : step.getNpcHighlight();
        return t == null || t.trim().isEmpty() ? null : t;
    }

    /** How far from the player NPCs are lit: 30 tiles, or as far as the client draws at sea. */
    private int range() {
        int range = 30;
        if (Sailing.isSailing(client) && client.getTopLevelWorldView() != null) {
            range = Math.max(range, client.getTopLevelWorldView().getScene().getDrawDistance());
        }
        return range;
    }

    private HighlightedNpc shouldHighlight(NPC npc) {
        if (!isHighlighted(npc)) return null;
        return HighlightedNpc.builder()
            .npc(npc)
            .highlightColor(plugin.getConfig().npcHighlightColor())
            .outline(true)
            .hull(false)
            .tile(false)
            .nameOnMinimap(true)
            .build();
    }

    /** On a Renu quetzal step not yet flown: Renu, at any landing site in range. */
    private boolean isRenuToTake(RouteStep step, NPC npc) {
        if (!Quetzals.isRenuStep(step) || !Quetzals.RENU.equalsIgnoreCase(npc.getName())) return false;
        WorldPoint at = Sailing.position(client);
        return at != null && !Quetzals.arrived(step, at) && npc.getWorldLocation().distanceTo(at) <= range();
    }

    /** Whether the active step highlights this NPC. */
    public boolean isHighlighted(NPC npc) {
        RouteStep step = activeStep();
        if (isRenuToTake(step, npc)) return true;
        String targetName = target(step);
        if (targetName == null) return false;

        // Comma-separated NPCs with / for alternatives, e.g. "Rommik,Shop assistant/Shop keeper"
        if (!NpcNames.matches(targetNames(targetName), npc.getName(), exactNearby)) return false;

        // Only NPCs in range of the player (at sea, of the boat)
        WorldPoint at = Sailing.position(client);
        if (at == null) return false;
        if (npc.getWorldLocation().distanceTo(at) > range()) return false;
        return plugin.highlightAllowed(step, npc.getWorldLocation());
    }
}

package com.routeplanner;

import lombok.RequiredArgsConstructor;
import com.routeplanner.util.*;
import com.routeplanner.model.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import javax.inject.Inject;
import javax.swing.*;
import java.util.*;

@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class TileMenuHandler {

    private static final String ADD_LOCATION_STEP = "Add Location Step";
    private static final String SET_TRANSITION_POINT = "Set Transition Point";
    private static final String SET_TRANSITION_OBJECT = "Set Transition Object";
    private static final String ADD_TO_ITEM_STEP = "Add to Item Step";
    private static final String CREATE_ITEM_STEP = "Create Item Step";
    private static final String CLEAR_SELECTION = "Clear Item Selection";
    private static final String MENU_TARGET = "Route Planner";

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final ItemManager itemManager;

    // Items collected via shift+right-click in shops, pending bundling into one step
    private final List<String> pendingShopItems = new ArrayList<>();
    // Item name under the cursor when the menu was opened
    private String lastRightClickedShopItem = null;

    public void startUp() {
    }

    public void shutDown() {
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (plugin.getActiveRoute() == null) return;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return;
        if (step.getSkillingTargetNpc() == null) return;
        // Only pickpocketing wants its option on left click; Talk-to and kill steps
        // highlight an NPC too but keep the game's own menu order.
        if (!"THIEVING".equalsIgnoreCase(step.getSkillingSkill())) return;

        MenuEntry entry = event.getMenuEntry();
        if (!(entry.getActor() instanceof NPC)) return;
        NPC npc = (NPC) entry.getActor();
        if (npc.getName() == null) return;

        if (!NpcNames.matches(step.getSkillingTargetNpc(), npc.getName())) return;

        String option = entry.getOption();
        // Deprioritize everything except Pickpocket and Examine
        if (option.equalsIgnoreCase("Pickpocket")) {
            entry.setDeprioritized(false);
        } else if (!option.equalsIgnoreCase("Examine") && !option.equalsIgnoreCase("Cancel")) {
            entry.setDeprioritized(true);
        }
    }

    @Subscribe
    public void onMenuOpened(MenuOpened event) {
        if (plugin.getActiveRoute() == null) return;

        boolean hasWalkHere = false;
        for (MenuEntry entry : event.getMenuEntries()) {
            if (entry.getOption().equals("Walk here")) hasWalkHere = true;
        }

        if (hasWalkHere && client.isKeyPressed(KeyCode.KC_SHIFT)) {
            client.createMenuEntry(-1)
                .setOption(ADD_LOCATION_STEP)
                .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                .setType(MenuAction.RUNELITE)
                .setDeprioritized(false);
            if (plugin.getActiveRoute() != null && plugin.getActiveRoute().getActiveStep() != null) {
                client.createMenuEntry(-1)
                    .setOption(SET_TRANSITION_POINT)
                    .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                    .setType(MenuAction.RUNELITE)
                    .setDeprioritized(false);
                // Also offer object ID grab if a game object is under the cursor
                Tile tile = client.getTopLevelWorldView().getSelectedSceneTile();
                if (tile != null) {
                    for (GameObject obj : tile.getGameObjects()) {
                        if (SceneObjects.isObject(obj)) {
                            client.createMenuEntry(-1)
                                .setOption(SET_TRANSITION_OBJECT + " (ID:" + obj.getId() + ")")
                                .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                                .setType(MenuAction.RUNELITE)
                                .setDeprioritized(false);
                            break;
                        }
                    }
                }
            }
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        String opt = event.getMenuOption();

        // Add to Item Step uses the item name as target, not MENU_TARGET
        if (opt.equals(ADD_TO_ITEM_STEP)) {
            if (lastRightClickedShopItem != null
                    && !pendingShopItems.contains(lastRightClickedShopItem)) {
                pendingShopItems.add(lastRightClickedShopItem);
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                    "<col=00ff00>Route Planner:</col> added " + lastRightClickedShopItem
                    + " (" + pendingShopItems.size() + " selected)", null);
            }
            event.consume();
            return;
        }

        if (!event.getMenuTarget().contains(MENU_TARGET)) return;

        if (opt.startsWith(SET_TRANSITION_OBJECT)) {
            RouteStep activeStep = plugin.getActiveRoute() == null ? null
                : plugin.getActiveRoute().getActiveStep();
            if (activeStep == null) return;
            Tile tile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (tile == null) return;
            for (GameObject obj : tile.getGameObjects()) {
                if (SceneObjects.isObject(obj)) {
                    activeStep.setTransitionObjectId(obj.getId());
                    plugin.saveRoutes();
                    client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                        "<col=00ff00>Route Planner:</col> transition object ID set to " + obj.getId(), null);
                    break;
                }
            }
        } else if (opt.equals(SET_TRANSITION_POINT)) {
            Tile selectedTile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (selectedTile == null) return;
            RouteStep activeStep = plugin.getActiveRoute() == null ? null
                : plugin.getActiveRoute().getActiveStep();
            if (activeStep == null) return;
            WorldPoint raw = selectedTile.getWorldLocation();
            activeStep.setTransitionPoint(raw);
            plugin.saveRoutes();
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "<col=00ff00>Route Planner:</col> transition point set to " + raw, null);
        } else if (opt.equals(ADD_LOCATION_STEP)) {
            Tile selectedTile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (selectedTile == null) {
                log.warn("Route Planner: no selected tile found");
                return;
            }
            promptAddLocationStep(selectedTile.getWorldLocation());
        } else if (opt.startsWith(CREATE_ITEM_STEP)) {
            createItemStepFromSelection();
            event.consume();
        } else if (opt.equals(CLEAR_SELECTION)) {
            pendingShopItems.clear();
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "<col=ff5555>Route Planner:</col> item selection cleared", null);
            event.consume();
        }
    }

    private void createItemStepFromSelection() {
        if (pendingShopItems.isEmpty() || plugin.getActiveRoute() == null) return;
        final List<String> snapshot = new ArrayList<>(pendingShopItems);
        pendingShopItems.clear();
        SwingUtilities.invokeLater(() -> {
            String itemList = String.join(", ", snapshot);
            String firstName = snapshot.get(0);
            String stepName = "Buy: " + firstName
                + (snapshot.size() > 1 ? " +" + (snapshot.size() - 1) + " more" : "");
            RouteStep step = new RouteStep(stepName, StepType.ITEM, null, -1);
            step.setItemList(itemList);
            step.setItemMode(ItemMode.SHOP);
            plugin.addStep(plugin.getActiveRoute(), step);
        });
    }

    private void promptAddLocationStep(WorldPoint tile) {
        SwingUtilities.invokeLater(() -> {
            if (plugin.getActiveRoute() == null) {
                JOptionPane.showMessageDialog(null, "Select or create a route first.");
                return;
            }
            new QuickStepDialog(plugin, plugin.getActiveRoute(), null, tile).setVisible(true);
        });
    }
}

package com.routeplanner;

import com.routeplanner.util.DataFiles;
import com.routeplanner.transport.Transport;
import net.runelite.api.coords.WorldPoint;
import java.util.*;

/**
 * Loads transport edges (origin -> destination) from the bundled Shortest Path
 * TSV datasets. Only rows with BOTH a valid origin and destination are kept,
 * which naturally includes doors, stairs, dungeon entrances, agility shortcuts,
 * boats, ships and minecarts, and skips "from anywhere" teleports / hub types.
 */
public class TransportLoader {

    // Files that contain simple origin->destination edges
    private static final String[] FILES = {
        "transports.tsv",
        "agility_shortcuts.tsv",
        "boats.tsv",
        "ships.tsv",
        "charter_ships.tsv",
        "minecarts.tsv"
    };

    /** Files whose edges travel between places (ships, minecarts) rather than through a door or up stairs. */
    private static final Set<String> TRAVEL_FILES = new HashSet<>(Arrays.asList(
        "boats.tsv", "ships.tsv", "charter_ships.tsv", "minecarts.tsv"));
    /** Origins whose edges are all journeys from TRAVEL_FILES, mapped to those destinations. */
    private static final Map<WorldPoint, Set<WorldPoint>> TRAVEL = new HashMap<>();

    /** Whether the edge from {@code origin} to {@code destination} is a ship or minecart journey. */
    public static boolean isTravel(WorldPoint origin, WorldPoint destination) {
        Set<WorldPoint> dests = TRAVEL.get(origin);
        return dests != null && dests.contains(destination);
    }

    /** Every loaded edge with its menu text and object id, for highlighting the stairs to use. */
    private static final Map<WorldPoint, List<Transport>> DETAILS = new HashMap<>();

    /** The transport going from {@code origin} to {@code destination}, or null if none is known. */
    public static Transport find(WorldPoint origin, WorldPoint destination) {
        List<Transport> list = DETAILS.get(origin);
        if (list == null) return null;
        for (Transport t : list) if (t.destination.equals(destination)) return t;
        return null;
    }

    public static Map<WorldPoint, List<WorldPoint>> load() {
        Map<WorldPoint, List<WorldPoint>> edges = new HashMap<>();
        int total = 0;
        for (String f : FILES) {
            int count = 0;
            for (String[] cols : DataFiles.rowsAt("/com/routeplanner/transports/" + f)) {
                if (cols.length < 2) continue;
                WorldPoint origin = DataFiles.point(cols[0]);
                WorldPoint dest = DataFiles.point(cols[1]);
                if (origin == null || dest == null) continue;
                edges.computeIfAbsent(origin, k -> new ArrayList<>()).add(dest);
                if (TRAVEL_FILES.contains(f)) TRAVEL.computeIfAbsent(origin, k -> new HashSet<>()).add(dest);
                DETAILS.computeIfAbsent(origin, k -> new ArrayList<>()).add(detail(origin, dest, DataFiles.col(cols, 2)));
                count++;
            }
            total += count;
        }
        return edges;
    }

    /** "Climb-up Staircase 16671" -> action "Climb-up Staircase", object 16671. */
    private static Transport detail(WorldPoint origin, WorldPoint dest, String col) {
        String text = col.trim();
        int id = -1;
        int sp = text.lastIndexOf(' ');
        if (sp > 0) {
            try {
                id = Integer.parseInt(text.substring(sp + 1));
                text = text.substring(0, sp);
            } catch (NumberFormatException ignored) {}
        }
        return new Transport(origin, dest, text.isEmpty() ? null : text, id);
    }
}

package com.routeplanner;

import java.io.*;
import java.util.*;
import java.util.zip.*;

/**
 * Reads collision-map.zip in the format of Skretzo/shortest-path's SplitFlagMap.
 *
 * Index formula:
 *   index = (plane * 64 * 64 + (y - minY) * 64 + (x - minX)) * 4 + flag
 *
 * Flags: 0 = can travel NORTH from tile, 1 = can travel EAST from tile, 2 and 3 = the north and
 * east edges are walls or doors (unused here). South is stored as North of the tile below. West is
 * stored as East of the tile to the left. A set bit means movement IS ALLOWED (not blocked).
 */
public class WorldCollisionMap {

    public static final int NORTH = 0;
    public static final int EAST  = 1;

    private static final int REGION_SIZE = 64;
    private static final int FLAG_COUNT = 4;
    private static final int BITS_PER_PLANE = REGION_SIZE * REGION_SIZE * FLAG_COUNT;

    private static class RegionData {
        final int minX;
        final int minY;
        final BitSet flags;
        final byte planeCount;

        RegionData(int minX, int minY, byte[] data) {
            this.minX = minX;
            this.minY = minY;
            this.flags = BitSet.valueOf(data);
            int size = flags.size();
            this.planeCount = (byte) ((size + BITS_PER_PLANE - 1) / BITS_PER_PLANE);
        }

        boolean get(int x, int y, int plane, int direction) {
            if (x < minX || x >= minX + REGION_SIZE) return false;
            if (y < minY || y >= minY + REGION_SIZE) return false;
            if (plane < 0 || planeCount <= 0) return false;
            if (direction < 0 || direction >= 2) return false;
            int idx = (plane * REGION_SIZE * REGION_SIZE
                + (y - minY) * REGION_SIZE
                + (x - minX)) * FLAG_COUNT + direction;
            return flags.get(idx);
        }
    }

    // key = regionX | (regionY << 16)
    private final Map<Integer, RegionData> regions = new HashMap<>();

    public WorldCollisionMap(InputStream zipStream) throws IOException {
        try (ZipInputStream zis = new ZipInputStream(zipStream)) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                String[] parts = entry.getName().split("_");
                int regionX = Integer.parseInt(parts[0]);
                int regionY = Integer.parseInt(parts[1]);
                int key = regionX | (regionY << 16);
                int minX = regionX * REGION_SIZE;
                int minY = regionY * REGION_SIZE;
                byte[] data = zis.readAllBytes();
                regions.put(key, new RegionData(minX, minY, data));
                zis.closeEntry();
            }
        }
    }

    /**
     * Returns true if movement NORTH from (x,y,plane) is allowed.
     */
    public boolean canMoveNorth(int x, int y, int plane) {
        return getFlag(x, y, plane, NORTH);
    }

    /**
     * Returns true if movement SOUTH from (x,y,plane) is allowed.
     * South from (x,y) = North from (x, y-1).
     */
    public boolean canMoveSouth(int x, int y, int plane) {
        return getFlag(x, y - 1, plane, NORTH);
    }

    /**
     * Returns true if movement EAST from (x,y,plane) is allowed.
     */
    public boolean canMoveEast(int x, int y, int plane) {
        return getFlag(x, y, plane, EAST);
    }

    /**
     * Returns true if movement WEST from (x,y,plane) is allowed.
     * West from (x,y) = East from (x-1, y).
     */
    public boolean canMoveWest(int x, int y, int plane) {
        return getFlag(x - 1, y, plane, EAST);
    }

    private boolean getFlag(int x, int y, int plane, int direction) {
        int regionX = x / REGION_SIZE;
        int regionY = y / REGION_SIZE;
        int key = regionX | (regionY << 16);
        RegionData region = regions.get(key);
        if (region == null) return true; // unknown = assume walkable
        return region.get(x, y, plane, direction);
    }

    public boolean isLoaded() {
        return !regions.isEmpty();
    }
}

package com.routeplanner;

import com.routeplanner.model.*;
import com.routeplanner.sailing.Sailing;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;
import javax.inject.Inject;
import java.awt.*;
import java.awt.geom.*;
import java.util.*;
import java.util.List;
import net.runelite.api.Point;

public class WorldMapPathOverlay extends Overlay {

    // World map interface ID and map view child ID
    private static final int WORLD_MAP_INTERFACE = 595;
    private static final int WORLD_MAP_CHILD = 7;

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final WorldMapOverlay worldMapOverlay;
    private final PathfinderOverlay pathfinderOverlay;
    private final RoutePlannerConfig config;

    @Inject
    public WorldMapPathOverlay(Client client, RoutePlannerPlugin plugin, RoutePlannerConfig config,
                                WorldMapOverlay worldMapOverlay,
                                PathfinderOverlay pathfinderOverlay) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.worldMapOverlay = worldMapOverlay;
        this.pathfinderOverlay = pathfinderOverlay;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;
        // Until the player boards (Sailing), the dock is where they're headed.
        WorldPoint target = plugin.getPathfinderOverlay().isBoardingPending(step) ? step.getBoardPoint() : step.getWorldPoint();
        if (target == null) return null;

        // Check world map is open
        Widget mapWidget = client.getWidget(WORLD_MAP_INTERFACE, WORLD_MAP_CHILD);
        if (mapWidget == null || mapWidget.isHidden()) return null;

        Rectangle mapBounds = mapWidget.getBounds();
        if (mapBounds == null) return null;

        WorldPoint player = Sailing.position(client);
        if (player == null) return null;

        // The area first, under the line
        TileArea area = plugin.areaOf(step);
        if (area != null) {
            Shape clip = graphics.getClip();
            graphics.clip(mapBounds);
            drawArea(graphics, area);
            graphics.setClip(clip);
        }

        // A thin line with small arrowheads along it pointing the way to go
        Color lineColor = config.lineColor();
        graphics.setColor(new Color(lineColor.getRed(), lineColor.getGreen(), lineColor.getBlue()));
        graphics.setStroke(new BasicStroke(1));
        Object oldAa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        Shape oldClip = graphics.getClip();
        graphics.clip(mapBounds);
        // The route the pathfinder worked out (round coasts at sea, along roads on land); a straight
        // line to the destination until there is one
        if (!drawRoute(graphics, pathfinderOverlay.getCachedPath())) {
            Point playerMapPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(player);
            Point targetMapPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(target);
            if (playerMapPoint != null && targetMapPoint != null) {
                List<Point> run = new ArrayList<>();
                run.add(playerMapPoint);
                run.add(targetMapPoint);
                drawRun(graphics, run);
            }
        }
        graphics.setClip(oldClip);
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAa);

        // Draw destination dot
        Point destPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(target);
        if (destPoint != null && mapBounds.contains(destPoint.getX(), destPoint.getY())) {
            int size = 10;
            int x = destPoint.getX() - size / 2;
            int y = destPoint.getY() - size / 2;

            graphics.setColor(Color.BLACK);
            graphics.fill(new Ellipse2D.Double(x - 1, y - 1, size + 2, size + 2));
            graphics.setColor(new Color(255, 140, 0));
            graphics.fill(new Ellipse2D.Double(x, y, size, size));

            graphics.setColor(Color.WHITE);
            graphics.setFont(new Font("Arial", Font.BOLD, 11));
            graphics.drawString(step.getName(), destPoint.getX() + 8, destPoint.getY() + 4);
        }

        // Draw player dot
        Point playerPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(player);
        if (playerPoint != null && mapBounds.contains(playerPoint.getX(), playerPoint.getY())) {
            int size = 8;
            int x = playerPoint.getX() - size / 2;
            int y = playerPoint.getY() - size / 2;
            graphics.setColor(Color.BLACK);
            graphics.fill(new Ellipse2D.Double(x - 1, y - 1, size + 2, size + 2));
            graphics.setColor(Color.WHITE);
            graphics.fill(new Ellipse2D.Double(x, y, size, size));
        }

        return null;
    }

    /** The step's area on the map, in the tile highlight colour. */
    private void drawArea(Graphics2D graphics, TileArea area) {
        Path2D.Float fill = new Path2D.Float();
        for (int[] r : area.rects()) {
            // Outer corners: one past the far tile, so a small area still covers its tiles
            Point a = mapPoint(r[0], r[1], area.getPlane()), b = mapPoint(r[0] + r[2], r[1] + r[3], area.getPlane());
            if (a == null || b == null) return;
            fill.append(new Rectangle(Math.min(a.getX(), b.getX()), Math.min(a.getY(), b.getY()),
                Math.max(1, Math.abs(b.getX() - a.getX())), Math.max(1, Math.abs(b.getY() - a.getY()))), false);
        }
        Path2D.Float outline = new Path2D.Float();
        for (int[] e : area.edges()) {
            Point a = mapPoint(e[0], e[1], area.getPlane()), b = mapPoint(e[2], e[3], area.getPlane());
            if (a == null || b == null) return;
            outline.moveTo(a.getX(), a.getY());
            outline.lineTo(b.getX(), b.getY());
        }
        Color c = config.tileHighlightColor();
        graphics.setColor(AreaGraphics.fill(c));
        graphics.fill(fill);
        graphics.setColor(AreaGraphics.outline(c));
        graphics.setStroke(new BasicStroke(2));
        graphics.draw(outline);
    }

    private Point mapPoint(int x, int y, int plane) {
        return worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(x, y, plane));
    }

    /**
     * Draws the path on the map, broken where it jumps (stairs, a ship, a cave mouth) or goes off the
     * map view. Returns false if there's no path to draw.
     */
    private boolean drawRoute(Graphics2D graphics, List<WorldPoint> path) {
        if (path == null || path.size() < 2) return false;
        List<Point> run = new ArrayList<>();
        WorldPoint prev = null;
        for (WorldPoint wp : path) {
            Point p = worldMapOverlay.mapWorldPointToGraphicsPoint(wp);
            boolean jump = prev != null && (prev.getPlane() != wp.getPlane()
                || Math.max(Math.abs(prev.getX() - wp.getX()), Math.abs(prev.getY() - wp.getY())) > MAX_STEP_TILES);
            if (p == null || jump) {
                drawRun(graphics, run);
                run = new ArrayList<>();
            }
            prev = wp;
            if (p != null) run.add(p);
        }
        drawRun(graphics, run);
        return true;
    }

    /** One unbroken stretch of the route: the line, an arrowhead every so often, and one at its end. */
    private void drawRun(Graphics2D graphics, List<Point> run) {
        if (run.size() < 2) return;
        Path2D.Float line = new Path2D.Float();
        line.moveTo(run.get(0).getX(), run.get(0).getY());
        double[] at = new double[run.size()];  // distance along the run to each point, in pixels
        for (int i = 1; i < run.size(); i++) {
            line.lineTo(run.get(i).getX(), run.get(i).getY());
            at[i] = at[i - 1] + Math.hypot(run.get(i).getX() - run.get(i - 1).getX(), run.get(i).getY() - run.get(i - 1).getY());
        }
        graphics.draw(line);
        double total = at[run.size() - 1];
        if (total < ARROW_LENGTH) return;
        for (double d = ARROW_SPACING; d < total - ARROW_SPACING / 2; d += ARROW_SPACING) {
            drawArrowhead(graphics, run, at, d);
        }
        drawArrowhead(graphics, run, at, total);
    }

    /** A small filled arrowhead with its tip {@code d} pixels along the run, pointing along it. */
    private void drawArrowhead(Graphics2D graphics, List<Point> run, double[] at, double d) {
        // Aimed from a little way back rather than along the last segment: a path drawn tile by tile
        // zigzags on the diagonals, and the arrows would wobble with it
        double[] tip = pointAt(run, at, d);
        double[] back = pointAt(run, at, d - ARROW_LENGTH * 2);
        double angle = Math.atan2(tip[1] - back[1], tip[0] - back[0]);
        if (tip[0] == back[0] && tip[1] == back[1]) return;
        Path2D.Double head = new Path2D.Double();
        head.moveTo(0, 0);
        head.lineTo(-ARROW_LENGTH, -ARROW_LENGTH / 2);
        head.lineTo(-ARROW_LENGTH, ARROW_LENGTH / 2);
        head.closePath();
        AffineTransform tx = AffineTransform.getTranslateInstance(tip[0], tip[1]);
        tx.rotate(angle);
        graphics.fill(tx.createTransformedShape(head));
    }

    /** The point {@code d} pixels along the run (clamped to its ends). */
    private static double[] pointAt(List<Point> run, double[] at, double d) {
        if (d <= 0) return new double[]{run.get(0).getX(), run.get(0).getY()};
        for (int i = 1; i < run.size(); i++) {
            if (at[i] >= d) {
                double seg = at[i] - at[i - 1];
                double f = seg == 0 ? 0 : (d - at[i - 1]) / seg;
                Point a = run.get(i - 1), b = run.get(i);
                return new double[]{a.getX() + (b.getX() - a.getX()) * f, a.getY() + (b.getY() - a.getY()) * f};
            }
        }
        Point last = run.get(run.size() - 1);
        return new double[]{last.getX(), last.getY()};
    }

    /** Path points further apart than this are a jump (stairs, a ship, a cave mouth), not a line. */
    private static final int MAX_STEP_TILES = 5;
    /** Pixels between the arrowheads along the line, and the arrowhead's length. */
    private static final double ARROW_SPACING = 60;
    private static final double ARROW_LENGTH = 6;
}

