}

package com.routeplanner.agility;

import com.routeplanner.util.DataFiles;
import net.runelite.api.coords.WorldPoint;
import java.util.*;

/**
 * The rooftop and other agility courses, from agility_courses.tsv: a "course" row (with the map
 * region it's recognised by and the tile to walk to, both optional), then its "obstacle" rows.
 */
public class AgilityCoursePresets {

    private static final Map<Integer, AgilityCourse> BY_REGION = new HashMap<>();
    private static final Map<String, WorldPoint> STARTS = new HashMap<>();

    public static final List<AgilityCourse> ALL = load();

    private static List<AgilityCourse> load() {
        List<AgilityCourse> courses = new ArrayList<>();
        List<AgilityObstacle> obstacles = null;
        for (String[] r : DataFiles.rows("agility_courses.tsv")) {
            if ("course".equals(r[0])) {
                obstacles = new ArrayList<>();
                AgilityCourse c = new AgilityCourse(r[1], DataFiles.num(r[2]), DataFiles.dec(r[3]), obstacles);
                courses.add(c);
                if (!DataFiles.col(r, 4).isEmpty()) BY_REGION.put(DataFiles.num(r[4]), c);
                WorldPoint start = DataFiles.point(DataFiles.col(r, 5));
                if (start != null) STARTS.put(c.getName(), start);
            } else if ("obstacle".equals(r[0]) && obstacles != null) {
                obstacles.add(new AgilityObstacle(r[1], DataFiles.point(DataFiles.col(r, 3)), DataFiles.ints(r[2])));
            }
        }
        return Collections.unmodifiableList(courses);
    }

    /** The course a map region belongs to, or null. */
    public static AgilityCourse getCourseForRegion(int regionId) {
        return BY_REGION.get(regionId);
    }

    /** The tile to walk to for a course, or null when none is known. */
    public static WorldPoint startLocation(String courseName) {
        return courseName == null ? null : STARTS.get(courseName);
    }
}

package com.routeplanner.agility;

import lombok.Data;
import net.runelite.api.coords.WorldPoint;

@Data
public class AgilityObstacle {
    private final String name;
    private final int[] objectIds;
    private final WorldPoint location; // nullable - used only as hint

    public AgilityObstacle(String name, WorldPoint location, int... objectIds) {
        this.name = name;
        this.location = location;
        this.objectIds = objectIds;
    }

    public boolean matchesId(int id) {
        for (int oid : objectIds) {
            if (oid == id) return true;
        }
        return false;
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.*;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.util.*;
import javax.inject.*;
import java.awt.image.BufferedImage;
import java.util.*;

/**
 * The Route Planner tab in the bank: a game-style square button with the plugin's icon, at the
 * top right of the bank like Quest Helper's. Clicking it shows only the current step's items in
 * the bank grid and puts the step in the bank title; any other tab, "View all items" or a
 * search turns it off, the same as switching between real bank tabs.
 */
@Slf4j
@Singleton
public class BankFilterButton {

    private static final String TAB_NAME = "Route Planner";
    private static final int BANK_GROUP_ID = 12;

    // The game's own small square button, as used by its bank buttons (and Quest Helper's tab)
    private static final int BUTTON_SPRITE = 195;
    private static final int BUTTON_SPRITE_SELECTED = 196;
    private static final int TAB_SOUND = 2266;
    /** Our icon, registered under an id the game doesn't use. */
    private static final int ICON_SPRITE = -21470;

    // Placement: Quest Helper's tab sits at x=408; ours goes just left of it, or there if it's absent.
    private static final int SIZE = 25;
    private static final int QUEST_HELPER_X = 408;
    private static final int Y = 5;

    // The bank grid (same spacing as the game's own layout)
    private static final int COLUMNS = 8;
    private static final int ITEM_SPACING_X = 48;
    private static final int ITEM_SPACING_Y = 36;
    private static final int ITEM_ROW_START = 51;

    @Inject private Client client;
    @Inject private RoutePlannerPlugin plugin;
    @Inject private BankItemManager bankItemManager;
    @Inject private BankSearch bankSearch;
    @Inject private ItemManager itemManager;

    private boolean filterActive;
    private RouteStep filteredStep;
    private Widget background;
    private Widget icon;
    private boolean iconRegistered;
    private BufferedImage iconSource; // the plugin icon the sprite was made from
    /** Each grid widget's x, y and hidden flag before we filtered, to put back exactly. */
    private final Map<Integer, int[]> saved = new HashMap<>();
    private String savedTitle;

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == BANK_GROUP_ID) {
            background = null;
            icon = null;
            filterActive = false;
            filteredStep = null;
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event) {
        if (event.getGroupId() == BANK_GROUP_ID) {
            background = null;
            icon = null;
            filterActive = false;
            filteredStep = null;
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() != ScriptID.BANKMAIN_BUILD) return;
        saved.clear(); // the bank just laid itself out again; that's the new state to come back to
        savedTitle = null;
        createTab();
        if (filterActive) applyItemFilter();
    }

    /** The step changed while the bank is open: show or hide the tab, and drop a stale filter. */
    @Subscribe
    public void onGameTick(GameTick tick) {
        if (background == null) return;
        RouteStep step = stepWithItems();
        boolean show = step != null;
        if (background.isHidden() == show) {
            background.setHidden(!show);
            if (icon != null) icon.setHidden(!show);
        }
        if (filterActive && step != filteredStep) {
            if (step == null) turnOff(true);
            else applyItemFilter();
        }
    }

    /** Another tab, "View all items" or the search box replaces our view, like any bank tab. */
    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (!filterActive) return;
        String option = event.getMenuOption();
        if (option == null || isOurTab(event)) return;
        if (option.startsWith("View tab") || option.startsWith("View tag tab") || option.equals("View all items")
            || option.startsWith("Potion store") || option.equals("Search")) {
            turnOff(false);
        }
    }

    /** Our own tab's click (matched by widget, since the menu text isn't reliable to compare). */
    private boolean isOurTab(MenuOptionClicked event) {
        if (background != null && event.getParam1() == InterfaceID.Bankmain.UNIVERSE
            && event.getParam0() == background.getIndex()) return true;
        String target = event.getMenuTarget();
        return target != null && Text.removeTags(target).contains(TAB_NAME);
    }

    private RouteStep stepWithItems() {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        return step != null && step.getItemList() != null && !step.getItemList().trim().isEmpty() ? step : null;
    }

    private void createTab() {
        Widget parent = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        if (parent == null || parent.isHidden()) return;
        int x = questHelperTabPresent(parent) ? QUEST_HELPER_X - SIZE - 3 : QUEST_HELPER_X;
        registerIcon();
        if (background != null && stillThere(parent)) {
            // Quest Helper may have added its tab after ours: keep to its left
            if (background.getOriginalX() != x) {
                background.setOriginalX(x);
                background.revalidate();
                if (icon != null) { icon.setOriginalX(x + 3); icon.revalidate(); }
            }
            refreshSprites();
            return;
        }
        registerIcon();

        background = parent.createChild(-1, WidgetType.GRAPHIC);
        background.setOriginalWidth(SIZE);
        background.setOriginalHeight(SIZE);
        background.setOriginalX(x);
        background.setOriginalY(Y);
        background.setSpriteId(filterActive ? BUTTON_SPRITE_SELECTED : BUTTON_SPRITE);
        background.setAction(0, "View tab");
        background.setName("<col=ff9040>" + TAB_NAME + "</col>");
        background.setHasListener(true);
        background.setOnOpListener((JavaScriptCallback) e -> toggle());
        background.revalidate();

        icon = parent.createChild(-1, WidgetType.GRAPHIC);
        icon.setOriginalWidth(SIZE - 6);
        icon.setOriginalHeight(SIZE - 6);
        icon.setOriginalX(x + 3);
        icon.setOriginalY(Y + 3);
        icon.setSpriteId(ICON_SPRITE);
        icon.revalidate();

        boolean show = stepWithItems() != null;
        background.setHidden(!show);
        icon.setHidden(!show);
    }

    /** The bank can rebuild its interface and drop children we added; check ours survived. */
    private boolean stillThere(Widget parent) {
        Widget[] kids = parent.getDynamicChildren();
        if (kids == null) return false;
        for (Widget w : kids) {
            if (w != null && w.getName() != null && w.getName().contains(TAB_NAME)) return true;
        }
        return false;
    }

    /** Quest Helper adds a tab named "quest-helper" at the same spot; make room for it. */
    private static boolean questHelperTabPresent(Widget parent) {
        Widget[] kids = parent.getDynamicChildren();
        if (kids == null) return false;
        for (Widget w : kids) {
            if (w != null && w.getName() != null && w.getName().contains("quest-helper")) return true;
        }
        return false;
    }

    /** The plugin's icon as a game sprite, so it sits on the button like the game's own icons. */
    private void registerIcon() {
        BufferedImage img = plugin.getRouteIcon();
        if (img == null) img = ImageUtil.loadImageResource(RoutePlannerPlugin.class, "route_icon.png");
        if (iconRegistered && img == iconSource) return; // still current (re-made once the orb loads)
        iconSource = img;
        try {
            BufferedImage scaled = ImageUtil.resizeImage(img, SIZE - 6, SIZE - 6);
            SpritePixels sprite = ImageUtil.getImageSpritePixels(scaled, client);
            client.getSpriteOverrides().put(ICON_SPRITE, sprite);
            iconRegistered = true;
        } catch (RuntimeException e) {
            log.warn("Route Planner: couldn't load the bank tab icon", e);
        }
    }

    private void refreshSprites() {
        if (background != null) {
            background.setSpriteId(filterActive ? BUTTON_SPRITE_SELECTED : BUTTON_SPRITE);
            background.revalidate();
        }
    }

    private void toggle() {
        client.playSoundEffect(TAB_SOUND);
        if (filterActive) {
            turnOff(true);
        } else {
            filterActive = true;
            refreshSprites();
            applyItemFilter();
        }
    }

    /** @param resetBank put the normal bank view back (not needed when another tab takes over). */
    private void turnOff(boolean resetBank) {
        filterActive = false;
        filteredStep = null;
        refreshSprites();
        restore();
        if (resetBank) bankSearch.reset(true);
    }

    /** Put every grid item and the title back the way the bank had them. */
    private void restore() {
        Widget itemContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (itemContainer != null && !saved.isEmpty()) {
            Widget[] items = itemContainer.getDynamicChildren();
            if (items != null) {
                for (Widget item : items) {
                    if (item == null) continue;
                    int[] s = saved.get(item.getIndex());
                    if (s == null) continue;
                    item.setOriginalX(s[0]);
                    item.setOriginalY(s[1]);
                    item.setHidden(s[2] == 1);
                    item.revalidate();
                }
            }
            itemContainer.revalidateScroll();
        }
        Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
        if (title != null && savedTitle != null) title.setText(savedTitle);
        saved.clear();
        savedTitle = null;
    }

    private void applyItemFilter() {
        RouteStep step = stepWithItems();
        if (step == null) return;
        filteredStep = step;

        Set<String> requiredNames = new HashSet<>();
        for (List<String> group : bankItemManager.parseItemList(step.getItemList())) {
            for (String alt : group) requiredNames.add(bankItemManager.parseItemName(alt).toLowerCase().trim());
        }

        Widget itemContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (itemContainer == null) return;
        Widget[] items = itemContainer.getDynamicChildren();
        if (items == null) return;

        if (saved.isEmpty()) {
            for (Widget item : items) {
                if (item == null) continue;
                saved.put(item.getIndex(), new int[]{item.getOriginalX(), item.getOriginalY(), item.isHidden() ? 1 : 0});
            }
            Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
            if (title != null) savedTitle = title.getText();
        }

        // Keep this step's items, in bank order; hide everything else
        List<Widget> keep = new ArrayList<>();
        for (Widget item : items) {
            if (item == null) continue;
            int[] before = saved.get(item.getIndex());
            boolean wasHidden = before != null ? before[2] == 1 : item.isHidden();
            if (item.getItemId() <= 0 || wasHidden) { item.setHidden(true); continue; }
            String name = itemManager.getItemComposition(item.getItemId()).getName();
            boolean wanted = name != null && requiredNames.stream().anyMatch(r -> BankItemManager.nameMatches(r, name));
            if (wanted) keep.add(item);
            else item.setHidden(true);
        }
        for (int i = 0; i < keep.size(); i++) {
            Widget item = keep.get(i);
            item.setHidden(false);
            item.setOriginalX(ITEM_ROW_START + (i % COLUMNS) * ITEM_SPACING_X);
            item.setOriginalY((i / COLUMNS) * ITEM_SPACING_Y);
            item.revalidate();
        }
        int rows = (keep.size() + COLUMNS - 1) / COLUMNS;
        itemContainer.setScrollY(0);
        itemContainer.setScrollHeight(Math.max(itemContainer.getHeight(), rows * ITEM_SPACING_Y));
        itemContainer.revalidateScroll();

        Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
        if (title != null) title.setText("Route: " + step.getName());
    }

    public void reset() {
        if (filterActive) {
            restore();
            bankSearch.reset(true);
        }
        filterActive = false;
        filteredStep = null;
        background = null;
        icon = null;
        if (iconRegistered) {
            client.getSpriteOverrides().remove(ICON_SPRITE);
            iconRegistered = false;
        }
    }
}

package com.routeplanner.bank;

import lombok.RequiredArgsConstructor;
import net.runelite.api.*;
import com.routeplanner.util.Herbs;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;
import javax.inject.*;
import java.util.*;
import java.util.regex.*;

@Singleton
public class BankItemManager {

    @Inject private Client client;
    @Inject private ItemManager itemManager;

    // Parse a quantity prefix like "1k", "1m", "1mil", "500k", "2.5m" from item name
    // Returns [quantity, itemName] or [1, fullString] if no quantity found
    private long suffixMultiply(double num, String suffix) {
        if (suffix == null) return (long) num;
        switch (suffix.toLowerCase()) {
            case "k": return (long)(num * 1_000);
            case "m": case "mil": return (long)(num * 1_000_000);
            case "b": return (long)(num * 1_000_000_000);
            default: return (long) num;
        }
    }

    /** "2.5k Coins": the amount (1), its suffix (2) and the name (3). Compiled once; it runs per frame. */
    private static final Pattern QUANTITY_PREFIX = Pattern
        .compile("^([\\d.]+)\\s*(k|m|mil|b)?\\s+(.+)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern CHARGE_SUFFIX = Pattern.compile("\\(\\d+\\)");

    /** Item-list names ending in "(*)" mean any charge: "Amulet of glory(*)" matches glory(1)-(6). */
    public static final String ANY_CHARGE = "(*)";

    /**
     * True when an item-list name (without quantity) refers to the actual item name. Besides plain
     * names: "Amulet of glory(*)" is any charge, "*" is a wildcard ("Grimy *" is every grimy herb)
     * and "Any herb" is any grimy or clean herb.
     */
    public static boolean nameMatches(String listName, String actual) {
        if (listName == null || actual == null) return false;
        String want = listName.trim().toLowerCase();
        String have = actual.trim().toLowerCase();
        if (want.equals(Herbs.ANY_HERB.toLowerCase())) return Herbs.isHerb(have);
        if (want.endsWith(ANY_CHARGE)) {
            String base = want.substring(0, want.length() - ANY_CHARGE.length()).trim();
            return have.startsWith(base) && CHARGE_SUFFIX.matcher(have.substring(base.length()).trim()).matches();
        }
        if (want.contains("*")) return have.matches(globToRegex(want));
        return want.equals(have);
    }

    private static String globToRegex(String glob) {
        StringBuilder re = new StringBuilder();
        for (String part : glob.split("\\*", -1)) {
            if (re.length() > 0) re.append(".*");
            re.append(Pattern.quote(part));
        }
        return re.toString();
    }

    /** Whether an item-list name stands for several items, so counts have to be summed. */
    private static boolean isPattern(String listName) {
        String n = listName.trim();
        return n.contains("*") || n.equalsIgnoreCase(Herbs.ANY_HERB);
    }

    /** How many of an item-list name are in a name -> quantity map, summing every match for a pattern. */
    public static long countOf(Map<String, Long> qtys, String listName) {
        if (!isPattern(listName)) return qtys.getOrDefault(listName.trim().toLowerCase(), 0L);
        long total = 0;
        for (Map.Entry<String, Long> e : qtys.entrySet()) {
            if (nameMatches(listName, e.getKey())) total += e.getValue();
        }
        return total;
    }

    private static boolean anyMatches(Set<String> names, String listName) {
        for (String n : names) if (nameMatches(listName, n)) return true;
        return false;
    }

    public String parseItemName(String input) {
        input = input.trim();
        Matcher m = QUANTITY_PREFIX.matcher(input);
        if (m.matches()) return m.group(3).trim();
        return input;
    }

    public long parseQuantityValue(String input) {
        input = input.trim();
        Matcher m = QUANTITY_PREFIX.matcher(input);
        if (m.matches()) {
            try {
                double num = Double.parseDouble(m.group(1));
                String suffix = m.group(2) == null ? "" : m.group(2).toLowerCase();
                return suffixMultiply(num, suffix);
            } catch (Exception ignored) {}
        }
        return 1;
    }

    // Parse item list string into groups (each group is a list of alternatives)
    // e.g. "Spade,1mil Coins/Platinum token" ->
    //      [["Spade"], ["1mil Coins", "Platinum token"]]
    public List<List<String>> parseItemList(String itemListStr) {
        if (itemListStr == null || itemListStr.trim().isEmpty()) return Collections.emptyList();
        List<List<String>> groups = new ArrayList<>();
        for (String group : itemListStr.split(",")) {
            group = group.trim();
            if (group.isEmpty()) continue;
            List<String> alternatives = new ArrayList<>();
            for (String alt : group.split("/")) {
                alt = alt.trim();
                if (!alt.isEmpty()) alternatives.add(alt);
            }
            if (!alternatives.isEmpty()) groups.add(alternatives);
        }
        return groups;
    }

    // Check if player has all required items in inventory with quantity
    public boolean hasAllItems(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return true;

        if (client.getItemContainer(InventoryID.INVENTORY) == null) return false;
        // Worn items count too: an amulet to bring is often put straight on
        Map<String, Long> inventoryQtys = carriedQtys(true);

        for (List<String> group : groups) {
            boolean groupSatisfied = false;
            for (String alt : group) {
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                long have = countOf(inventoryQtys, itemName);
                if (have >= required) {
                    groupSatisfied = true;
                    break;
                }
            }
            if (!groupSatisfied) return false;
        }
        return true;
    }

    /** Item name (lower-cased) -> total quantity in the inventory, plus what's worn when {@code worn}. */
    private Map<String, Long> carriedQtys(boolean worn) {
        Map<String, Long> qtys = new HashMap<>();
        addQtys(qtys, null, InventoryID.INVENTORY);
        if (worn) addQtys(qtys, null, InventoryID.EQUIPMENT);
        return qtys;
    }

    /** Adds a container's items to {@code qtys}, and their first item id per name to {@code ids} if given. */
    private void addQtys(Map<String, Long> qtys, Map<String, Integer> ids, InventoryID container) {
        ItemContainer c = client.getItemContainer(container);
        if (c == null) return;
        for (Item item : c.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (name == null) continue;
            qtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
            if (ids != null) ids.putIfAbsent(name.toLowerCase(), item.getId());
        }
    }

    // PICKUP: snapshot current counts of every item referenced in the list (baseline at step start)

    // PICKUP: true once enough of each group's item has been gained since the baseline

    // PICKUP: how many gained so far (summed across groups, best alternative each), for the HUD

    /**
     * Counts of the items referenced in itemListStr, carried or worn, when the step starts.
     * Worn items count on both sides, so putting on an item that was picked up keeps it gained.
     */
    public java.util.Map<String, Long> snapshotInventory(String itemListStr) {
        java.util.Map<String, Long> snapshot = new java.util.HashMap<>();
        if (client.getItemContainer(InventoryID.INVENTORY) == null || itemListStr == null) return snapshot;
        Map<String, Long> carried = carriedQtys(true);
        for (java.util.List<String> group : parseItemList(itemListStr)) {
            for (String alt : group) {
                String name = parseItemName(alt).toLowerCase();
                snapshot.put(name, countOf(carried, name));
            }
        }
        return snapshot;
    }

    /** True when enough of each item group has been gained ABOVE the baseline snapshot. */
    public boolean hasAllItemsAboveBaseline(String itemListStr, java.util.Map<String, Long> baseline) {
        if (baseline == null) return hasAllItems(itemListStr);
        if (client.getItemContainer(InventoryID.INVENTORY) == null) return false;
        Map<String, Long> current = carriedQtys(true);
        for (java.util.List<String> group : parseItemList(itemListStr)) {
            long required = 0;
            for (String alt : group) required = Math.max(required, parseQuantityValue(alt));
            // Check if any alternative in the group satisfies the required amount above baseline
            boolean groupSatisfied = false;
            for (String alt : group) {
                String name = parseItemName(alt).toLowerCase();
                long base = baseline.getOrDefault(name, 0L);
                long gained = Math.max(0, countOf(current, name) - base);
                if (gained >= required) { groupSatisfied = true; break; }
            }
            if (!groupSatisfied) return false;
        }
        return true;
    }

    // SELL: returns true when none of the listed items remain in the inventory (all sold)
    public boolean hasSoldAll(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return true;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) return true;

        Set<String> invNames = new HashSet<>();
        for (Item item : inventory.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (name != null) invNames.add(name.toLowerCase());
        }

        for (List<String> group : groups) {
            for (String alt : group) {
                String itemName = parseItemName(alt).toLowerCase();
                if (anyMatches(invNames, itemName)) return false; // still holding one
            }
        }
        return true;
    }

    /** Names of the unnoted items in the inventory, lowercased. */
    private Set<String> unnotedInventoryNames() {
        Set<String> names = new HashSet<>();
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) return names;
        for (Item item : inventory.getItems()) {
            if (item.getId() <= 0) continue;
            net.runelite.api.ItemComposition comp = itemManager.getItemComposition(item.getId());
            if (comp.getNote() != -1) continue; // noted
            if (comp.getName() != null) names.add(comp.getName().toLowerCase());
        }
        return names;
    }

    // USE_UP: true when none of the listed items are left unnoted in the inventory
    public boolean hasNoneUnnoted(String itemListStr) {
        if (client.getItemContainer(InventoryID.INVENTORY) == null) return false;
        Set<String> names = unnotedInventoryNames();
        for (List<String> group : parseItemList(itemListStr)) {
            for (String alt : group) {
                if (anyMatches(names, parseItemName(alt))) return false;
            }
        }
        return true;
    }

    // USE_UP: [displayText, "DONE" or "LEFT"] per list entry
    public List<String[]> getUseUpStatusList(String itemListStr) {
        Set<String> names = unnotedInventoryNames();
        List<String[]> result = new ArrayList<>();
        for (List<String> group : parseItemList(itemListStr)) {
            boolean left = false;
            for (String alt : group) left |= anyMatches(names, parseItemName(alt));
            result.add(new String[]{String.join("/", group), left ? "LEFT" : "DONE"});
        }
        return result;
    }

    // SELL: returns [displayText, status] where status is "SOLD" or "HOLDING"
    public List<String[]> getSellStatusList(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Set<String> invNames = new HashSet<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) invNames.add(name.toLowerCase());
            }
        }

        for (List<String> group : groups) {
            boolean holding = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                if (anyMatches(invNames, parseItemName(alt))) holding = true;
            }
            result.add(new String[]{disp.toString(), holding ? "HOLDING" : "SOLD"});
        }
        return result;
    }

    // Returns list of [displayText, status] where status is "HAVE" or "NEED"
    // Used by the HUD to show the item checklist on screen.
    public List<String[]> getItemStatusList(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;

        Map<String, Long> invQtys = carriedQtys(true);

        for (List<String> group : groups) {
            boolean have = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                if (countOf(invQtys, itemName) >= required) {
                    have = true;
                }
            }
            result.add(new String[]{disp.toString(), have ? "HAVE" : "NEED"});
        }
        return result;
    }

    /** Same as getItemStatusList but subtracts baseline counts for PICKUP steps. */
    public List<String[]> getItemStatusList(String itemListStr, java.util.Map<String, Long> baseline) {
        if (baseline == null) return getItemStatusList(itemListStr);
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;
        Map<String, Long> invQtys = carriedQtys(true);
        for (List<String> group : groups) {
            boolean have = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                long base = baseline.getOrDefault(itemName, 0L);
                long gained = Math.max(0, countOf(invQtys, itemName) - base);
                if (gained >= required) have = true;
            }
            result.add(new String[]{disp.toString(), have ? "HAVE" : "NEED"});
        }
        return result;
    }

    /** One line of an item list with live counts, for the side panel's step card. */
    @RequiredArgsConstructor
    public static final class ItemProgress {
        public final String name;
        public final long have;
        public final long need;
        public final int itemId; // -1 when the item couldn't be identified

    }

    /**
     * Have/need counts per item-list entry, carried and worn, counting only items gained since
     * {@code baseline} when one is given. For
     * alternatives ("Coins/Platinum token") the closest one is shown. Call on the client thread.
     */
    public List<ItemProgress> getItemProgress(String itemListStr, Map<String, Long> baseline) {
        List<ItemProgress> out = new ArrayList<>();
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return out;
        Map<String, Long> invQtys = new HashMap<>();
        Map<String, Integer> invIds = new HashMap<>();
        addQtys(invQtys, invIds, InventoryID.INVENTORY);
        addQtys(invQtys, invIds, InventoryID.EQUIPMENT);
        for (List<String> group : groups) {
            ItemProgress best = null;
            for (String alt : group) {
                String name = parseItemName(alt);
                long need = parseQuantityValue(alt);
                long count = countOf(invQtys, name);
                if (baseline != null) count = Math.max(0, count - baseline.getOrDefault(name.toLowerCase(), 0L));
                long have = Math.min(count, need);
                if (best == null || (double) have / need > (double) best.have / best.need) {
                    best = new ItemProgress(name, have, need, idFor(name, invIds));
                }
            }
            if (best != null) out.add(best);
        }
        return out;
    }

    /** A Sell-step line: 1/1 once the item has left the inventory. */
    public ItemProgress soldLine(String name, boolean sold) {
        return new ItemProgress(name, sold ? 1 : 0, 1, idFor(parseItemName(name.split("/")[0]), new HashMap<>()));
    }

    private final Map<String, Integer> idCache = new java.util.concurrent.ConcurrentHashMap<>();

    /** The first listed item's id, for a step's icon; -1 when it can't be identified. */
    public int firstItemId(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return -1;
        String name = parseItemName(groups.get(0).get(0));
        int id = idFor(name, Collections.emptyMap());
        if (id <= 0) idCache.remove(name.trim().toLowerCase()); // the item list may not have loaded yet
        return id;
    }

    /** An item id for a list name, for its icon: from the inventory, else the item search. */
    private int idFor(String listName, Map<String, Integer> invIds) {
        for (Map.Entry<String, Integer> e : invIds.entrySet()) {
            if (nameMatches(listName, e.getKey())) return e.getValue();
        }
        String key = listName.trim().toLowerCase();
        Integer cached = idCache.get(key);
        if (cached != null) return cached;
        int id = -1;
        String search = key.endsWith(ANY_CHARGE) ? key.substring(0, key.length() - ANY_CHARGE.length()).trim() : key;
        for (ItemPrice p : itemManager.search(search)) {
            if (nameMatches(listName, p.getName()) || p.getName().equalsIgnoreCase(search)) { id = p.getId(); break; }
        }
        idCache.put(key, id);
        return id;
    }

}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.skilling.PotionRecipes;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;
import java.util.*;
import java.util.List;

@Singleton
public class BankOverlay extends Overlay {

    private static final Color MISSING_FILL = new Color(255, 140, 0, 120);
    private static final Color MISSING_BORDER = new Color(255, 140, 0, 220);
    private static final Color HAVE_FILL = new Color(0, 255, 0, 80);
    private static final Color HAVE_BORDER = new Color(0, 255, 0, 200);
    private static final Stroke BORDER_STROKE = new BasicStroke(2);

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public BankOverlay(Client client, RoutePlannerPlugin plugin,
                       BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;

        boolean isItem = step.hasItems();
        boolean isHerblore = step.isHighlightEnabled() && step.getHerblorePotion() != null;
        boolean isBankSkill = step.isHighlightEnabled() && step.getBankHighlightItems() != null
            && !step.getBankHighlightItems().trim().isEmpty();
        if (!isItem && !isHerblore && !isBankSkill) return null;

        // Check if the bank is open, or the Farming Guild seed vault, which lists its items
        // the same way, so the same highlighting works there for tree/farm runs. The seed vault
        // uses the generated gameval id: ComponentID.SEED_VAULT_ITEM_CONTAINER points at an
        // empty sibling (631:17) since the interface was reworked; the items are in 631:18.
        Widget container = visibleWidget(ComponentID.BANK_ITEM_CONTAINER);
        if (container == null) container = visibleWidget(InterfaceID.SeedVault.OBJ_LIST);
        if (container == null) return null;
        Widget[] items = container.getDynamicChildren();
        if (items == null) return null;

        String itemListStr;
        if (isItem) {
            itemListStr = step.getItemList();
        } else if (isHerblore) {
            PotionRecipes.Potion pot =
                PotionRecipes.getByName(step.getHerblorePotion());
            if (pot == null) return null;
            if (inventoryHasItem(pot.unfinished)) {
                itemListStr = pot.secondary;
            } else if (bankHasItem(items, pot.unfinished)) {
                itemListStr = pot.unfinished + ", " + pot.secondary;
            } else {
                itemListStr = pot.herbGrimy + "/" + pot.herbClean + ", Vial of water";
            }
        } else {
            itemListStr = step.getBankHighlightItems();
        }

        // Parse the list and count the inventory once per frame, not once per bank item.
        List<List<String>> groups = bankItemManager.parseItemList(itemListStr);
        if (groups.isEmpty()) return null;
        List<String[]> wanted = new ArrayList<>(); // {name, alt as written} in list order
        for (List<String> group : groups) {
            for (String alt : group) wanted.add(new String[]{bankItemManager.parseItemName(alt), alt});
        }
        Map<String, Long> carried = inventoryCounts();

        // Items scrolled out of view still have canvas positions; keep highlights inside the list.
        Shape savedClip = graphics.getClip();
        graphics.clip(visibleBounds(container));
        graphics.setStroke(BORDER_STROKE);
        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String itemName = itemManager.getItemComposition(item.getItemId()).getName();
            if (itemName == null) continue;

            String[] match = null;
            for (String[] w : wanted) {
                if (BankItemManager.nameMatches(w[0], itemName)) { match = w; break; }
            }
            if (match == null) continue;

            // Orange while the INVENTORY (not the bank) is still short of it, green once it's carried.
            boolean missing = BankItemManager.countOf(carried, match[0]) < bankItemManager.parseQuantityValue(match[1]);
            Rectangle bounds = new Rectangle(item.getCanvasLocation().getX(), item.getCanvasLocation().getY(),
                item.getWidth(), item.getHeight());
            graphics.setColor(missing ? MISSING_FILL : HAVE_FILL);
            graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
            graphics.setColor(missing ? MISSING_BORDER : HAVE_BORDER);
            graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
        }
        graphics.setClip(savedClip);

        return null;
    }

    /**
     * The on-screen part of a widget. A scrolled list (like the seed vault's) can be far taller
     * than its window and start above the screen, so intersect with every ancestor's bounds.
     */
    private static Rectangle visibleBounds(Widget w) {
        Rectangle r = w.getBounds();
        for (Widget p = w.getParent(); p != null; p = p.getParent()) {
            r = r.intersection(p.getBounds());
        }
        return r;
    }

    private Widget visibleWidget(int componentId) {
        Widget w = client.getWidget(componentId);
        return w == null || w.isHidden() ? null : w;
    }

    private boolean bankHasItem(Widget[] items, String name) {
        if (name == null) return false;
        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String n = itemManager.getItemComposition(item.getItemId()).getName();
            if (n != null && n.equalsIgnoreCase(name)) return true;
        }
        return false;
    }

    /** Lower-case item name -> how many are in the inventory. */
    private Map<String, Long> inventoryCounts() {
        Map<String, Long> counts = new HashMap<>();
        ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
        if (inv == null) return counts;
        for (Item invItem : inv.getItems()) {
            if (invItem.getId() <= 0) continue;
            String n = itemManager.getItemComposition(invItem.getId()).getName();
            if (n != null) counts.merge(n.toLowerCase(), (long) invItem.getQuantity(), Long::sum);
        }
        return counts;
    }

    private boolean inventoryHasItem(String name) {
        if (name == null) return false;
        ItemContainer inv =
            client.getItemContainer(InventoryID.INVENTORY);
        if (inv == null) return false;
        for (Item invItem : inv.getItems()) {
            if (invItem.getId() <= 0) continue;
            String n = itemManager.getItemComposition(invItem.getId()).getName();
            if (n != null && n.equalsIgnoreCase(name)) return true;
        }
        return false;
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.*;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;
import java.util.*;
import java.util.List;
import net.runelite.api.Point;

/**
 * Highlights matching ground items on tiles for an ITEM step in PICKUP mode.
 */
@Singleton
public class GroundItemOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public GroundItemOverlay(Client client, RoutePlannerPlugin plugin,
                             BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    // The step's item list, parsed once rather than every frame
    private String targetsFor;
    private Set<String> targets = Collections.emptySet();

    /** Target item names (lowercased) from the step's item list, "/" alternatives included. */
    private Set<String> targets(String itemList) {
        if (Objects.equals(itemList, targetsFor)) return targets;
        Set<String> names = new HashSet<>();
        for (List<String> group : bankItemManager.parseItemList(itemList)) {
            for (String alt : group) {
                String n = bankItemManager.parseItemName(alt);
                if (n != null) names.add(n.toLowerCase());
            }
        }
        targetsFor = itemList;
        targets = names;
        return names;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasItems()) return null;
        if (step.getItemMode() != ItemMode.PICKUP) return null;

        Set<String> targets = targets(step.getItemList());
        if (targets.isEmpty()) return null;

        Scene scene = client.getScene();
        if (scene == null) return null;
        Tile[][][] tiles = scene.getTiles();
        int z = client.getPlane();
        if (z < 0 || z >= tiles.length) return null;
        Tile[][] plane = tiles[z];

        for (Tile[] row : plane) {
            if (row == null) continue;
            for (Tile tile : row) {
                if (tile == null) continue;
                List<TileItem> groundItems = tile.getGroundItems();
                if (groundItems == null || groundItems.isEmpty()) continue;

                String matchName = null;
                for (TileItem gi : groundItems) {
                    if (gi == null) continue;
                    String name = itemManager.getItemComposition(gi.getId()).getName();
                    if (name != null && targets.stream().anyMatch(t -> BankItemManager.nameMatches(t, name))) {
                        matchName = name;
                        break;
                    }
                }
                if (matchName == null) continue;

                LocalPoint lp = tile.getLocalLocation();
                if (lp == null) continue;
                if (!plugin.highlightAllowed(step, tile.getWorldLocation())) continue;

                ItemLayer itemLayer = tile.getItemLayer();
                if (itemLayer != null) {
                    Shape clickbox = itemLayer.getClickbox();
                    if (clickbox != null) {
                        graphics.setColor(new Color(255, 140, 0, 70));
                        graphics.fill(clickbox);
                        graphics.setColor(new Color(255, 140, 0, 230));
                        graphics.setStroke(new BasicStroke(2));
                        graphics.draw(clickbox);
                    }
                }

                Point textLoc =
                    Perspective.getCanvasTextLocation(client, graphics, lp, matchName, 0);
                if (textLoc != null) {
                    graphics.setColor(Color.BLACK);
                    graphics.drawString(matchName, textLoc.getX() + 1, textLoc.getY() + 1);
                    graphics.setColor(new Color(255, 200, 0));
                    graphics.drawString(matchName, textLoc.getX(), textLoc.getY());
                }
            }
        }
        return null;
    }

}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;
import java.util.*;
import java.util.List;

/**
 * Outlines the active step's inventory items (its "Inventory items" highlight), for steps where
 * you use one item on another, e.g. a cocktail shaker for a Fruit Blast. Gated by the step's
 * Highlight toggle like its NPC and object. Highlight only: never clicks.
 */
@Singleton
public class InventoryItemOverlay extends Overlay {
    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final ItemManager itemManager;
    private final BankItemManager bankItemManager;

    @Inject
    public InventoryItemOverlay(Client client, RoutePlannerPlugin plugin, ItemManager itemManager,
                                BankItemManager bankItemManager) {
        this.client = client;
        this.plugin = plugin;
        this.itemManager = itemManager;
        this.bankItemManager = bankItemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.isHighlightEnabled()) return null;
        String list = step.getInventoryHighlightItems();
        if (list == null || list.trim().isEmpty()) return null;

        List<String> wanted = new ArrayList<>();
        for (String entry : list.split("[,/]")) {
            if (!entry.trim().isEmpty()) wanted.add(bankItemManager.parseItemName(entry));
        }

        Widget inv = client.getWidget(InterfaceID.Inventory.ITEMS);
        if (inv == null || inv.isHidden()) return null;
        Widget[] slots = inv.getDynamicChildren();
        if (slots == null) return null;
        for (Widget slot : slots) {
            if (slot == null || slot.isHidden() || slot.getItemId() <= 0) continue;
            String name = itemManager.getItemComposition(slot.getItemId()).getName();
            for (String want : wanted) {
                if (BankItemManager.nameMatches(want, name)) {
                    highlight(graphics, slot.getBounds());
                    break;
                }
            }
        }
        return null;
    }

    private void highlight(Graphics2D graphics, Rectangle b) {
        HighlightColors.paintSlot(graphics, b, plugin.getConfig().npcHighlightColor());
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.*;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;
import java.util.List;

@Singleton
public class ShopOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public ShopOverlay(Client client, RoutePlannerPlugin plugin,
                       BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasItems()) return null;
        boolean isSell = step.getItemMode() == ItemMode.SELL;
        boolean isShop = step.getItemMode() == ItemMode.SHOP;
        if (!isShop && !isSell) return null;

        // SHOP highlights the shop stock; SELL highlights the inventory panel beside it
        Widget container = client.getWidget(isSell
            ? InterfaceID.Shopside.ITEMS
            : InterfaceID.Shopmain.ITEMS);
        if (container == null || container.isHidden()) return null;

        List<List<String>> groups = bankItemManager.parseItemList(step.getItemList());
        if (groups.isEmpty()) return null;

        Widget[] items = container.getDynamicChildren();
        if (items == null) return null;

        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String itemName = itemManager.getItemComposition(item.getItemId()).getName();
            if (itemName == null) continue;

            boolean isRequired = false;
            boolean isMissing = false;

            for (List<String> group : groups) {
                for (String alt : group) {
                    String altName = bankItemManager.parseItemName(alt);
                    if (BankItemManager.nameMatches(altName, itemName)) {
                        isRequired = true;
                        if (isSell) {
                            // Item present in inventory = still needs selling -> orange
                            isMissing = true;
                        } else {
                            long required = bankItemManager.parseQuantityValue(alt);
                            // Count only what was bought since the step started.
                            long inInventory = countInInventory(altName);
                            if (step.getPickupBaseline() != null) {
                                inInventory -= step.getPickupBaseline().getOrDefault(altName.toLowerCase(), 0L);
                            }
                            isMissing = inInventory < required;
                        }
                        break;
                    }
                }
                if (isRequired) break;
            }

            if (isRequired) {
                Rectangle bounds = new Rectangle(
                    item.getCanvasLocation().getX(),
                    item.getCanvasLocation().getY(),
                    item.getWidth(),
                    item.getHeight()
                );
                Color highlight = isMissing
                    ? new Color(255, 140, 0, 120)
                    : new Color(0, 255, 0, 80);
                Color border = isMissing
                    ? new Color(255, 140, 0, 220)
                    : new Color(0, 255, 0, 200);

                graphics.setColor(highlight);
                graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
                graphics.setColor(border);
                graphics.setStroke(new BasicStroke(2));
                graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
            }
        }

        return null;
    }

    /** How many of the item are carried or worn, matching the step's baseline. */
    private long countInInventory(String itemName) {
        return countIn(InventoryID.INVENTORY, itemName) + countIn(InventoryID.EQUIPMENT, itemName);
    }

    private long countIn(InventoryID container, String itemName) {
        ItemContainer c = client.getItemContainer(container);
        if (c == null) return 0;
        long total = 0;
        for (Item item : c.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (BankItemManager.nameMatches(itemName, name)) {
                total += item.getQuantity();
            }
        }
        return total;
    }
}

package com.routeplanner.dialog;

import lombok.RequiredArgsConstructor;
import com.routeplanner.*;
import com.routeplanner.model.*;
import net.runelite.api.Client;
import net.runelite.api.widgets.*;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.*;
import java.util.List;

/**
 * Colours the chat option to pick for a step's dialogue sequence (e.g. "3,1"), in the chatbox
 * itself, the way Quest Helper does: the option's text takes the highlight colour, and keeps it
 * when the mouse moves off it (the game would turn it back to black).
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class DialogHighlighter {

    /** The game's colour for an option line. */
    private static final int OPTION_BLACK = 0x000000;

    private final Client client;
    private final ClientThread clientThread;
    private final RoutePlannerPlugin plugin;
    private final RoutePlannerConfig config;

    private Widget highlighted;

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded e) {
        // The options are filled in by a script after the menu loads, so colour them just after.
        if (e.getGroupId() == InterfaceID.CHATMENU) clientThread.invokeLater(this::apply);
    }

    /** Colours the option the step wants, and un-colours one it no longer wants. Call on the client thread. */
    public void apply() {
        List<Widget> options = DialogOptions.options(client);
        Widget target = target(options);
        if (highlighted != null && highlighted != target && options.contains(highlighted)) {
            Widget old = highlighted;
            old.setTextColor(OPTION_BLACK);
            old.setOnMouseLeaveListener((JavaScriptCallback) ev -> old.setTextColor(OPTION_BLACK));
        }
        highlighted = target;
        if (target == null) return;
        target.setTextColor(color());
        target.setOnMouseLeaveListener((JavaScriptCallback) ev -> target.setTextColor(color()));
    }

    /** Puts a coloured option back to black, for when the plugin stops. */
    public void clear() {
        Widget old = highlighted;
        highlighted = null;
        if (old != null && DialogOptions.options(client).contains(old)) {
            clientThread.invokeLater(() -> {
                old.setTextColor(OPTION_BLACK);
                old.setOnMouseLeaveListener((JavaScriptCallback) ev -> old.setTextColor(OPTION_BLACK));
            });
        }
    }

    private int color() {
        return config.dialogOptionColor().getRGB() & 0xFFFFFF;
    }

    /** The option line the active step wants picked next, or null. */
    private Widget target(List<Widget> options) {
        if (options.isEmpty()) return null;
        Route route = plugin.getActiveRoute();
        RouteStep step = route != null ? route.getActiveStep() : null;
        if (step == null || step.getDialogOptions() == null || step.getDialogOptions().trim().isEmpty()) return null;
        if (!plugin.isDialogPartnerOk()) return null;
        String[] parts = step.getDialogOptions().split(",");
        int progress = plugin.getDialogProgress();
        if (progress < 0 || progress >= parts.length) return null;
        int option;
        try {
            option = Integer.parseInt(parts[progress].trim());
        } catch (NumberFormatException ex) {
            return null;
        }
        return option >= 1 && option <= options.size() ? options.get(option - 1) : null;
    }
}

package com.routeplanner.dialog;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;
import java.util.*;

/**
 * Reading the chat options menu ("Select an Option"). Shared by the highlight overlay and the
 * recorder so both count options the same way: option 1 is the first line under the title.
 */
public final class DialogOptions {

    private DialogOptions() {}

    /** The open options menu's container, or null when it isn't showing. */
    public static Widget container(Client client) {
        Widget w = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
        return w == null || w.isHidden() ? null : w;
    }

    /** The option lines in order (title excluded); empty when the menu isn't open. */
    public static List<Widget> options(Client client) {
        List<Widget> out = new ArrayList<>();
        Widget container = container(client);
        if (container == null) return out;
        Widget[] kids = container.getDynamicChildren();
        if (kids == null || kids.length == 0) kids = container.getChildren();
        if (kids == null) return out;
        boolean titleSkipped = false;
        for (Widget w : kids) {
            if (w == null || w.isHidden()) continue;
            String t = w.getText();
            if (t == null || t.trim().isEmpty()) continue;
            // The first line is always the menu's title ("Select an Option", or a question
            // like "Start the quest?"), never something to pick.
            if (!titleSkipped) { titleSkipped = true; continue; }
            out.add(w);
        }
        return out;
    }

    /** The option lines' text, cleaned of colour tags. */
    public static List<String> texts(Client client) {
        List<String> out = new ArrayList<>();
        for (Widget w : options(client)) out.add(clean(w.getText()));
        return out;
    }

    public static String clean(String raw) {
        return raw == null ? "" : Text.removeTags(raw).replace(' ', ' ').trim();
    }
}

package com.routeplanner.farming;

import lombok.RequiredArgsConstructor;
import com.routeplanner.util.SceneObjects;
import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;
import javax.inject.*;

/**
 * Completes farming patch steps. A patch is known by its own object id, which stays the same
 * whatever is growing in it, so one step works for any seed:
 *
 *  - replant steps are done on "You plant ..." just after something was used on the patch
 *    (planting gives no XP of its own, and the message covers every crop: seeds, saplings,
 *    spores, coral frags);
 *  - other patch steps (a bush, a tree) once the patch gave Farming XP and has nothing left to
 *    pick, harvest or check, or once a dead crop was cleared from it.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class FarmingTracker {

    /** Farming XP counts for a patch clicked this many ticks before (walking over to it first). */
    private static final int CLICK_WINDOW_TICKS = 30;

    private final Client client;
    private final RoutePlannerPlugin plugin;

    private int clickedPatchId = -1;
    private int clickTick = -1000;
    private int lastFarmingXp = -1;
    /** The step that got Farming XP from its patch (a tended patch is then done once it has no work left). */
    private RouteStep tendedStep;

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked e) {
        if (!isObjectAction(e.getMenuAction())) return;
        clickedPatchId = e.getId();
        clickTick = client.getTickCount();
        // A dead patch gives no XP for clearing, so clearing it counts as tending it: the step is
        // done once the patch is empty (a replant step after it then has the seed planted)
        RouteStep step = activeFarmStep();
        if (step != null && !step.isFarmReplant() && e.getId() == step.getFarmPatchId()
            && "Clear".equalsIgnoreCase(e.getMenuOption()) && isDead(e.getId())) {
            tendedStep = step;
        }
    }

    /** Whether the patch, as it looks now, holds a dead crop ("Dead herbs", "Dead tree", ...). */
    private boolean isDead(int patchId) {
        ObjectComposition comp = client.getObjectDefinition(patchId);
        if (comp != null && comp.getImpostorIds() != null) comp = comp.getImpostor();
        return comp != null && comp.getName() != null && comp.getName().toLowerCase().startsWith("dead");
    }

    @Subscribe
    public void onStatChanged(StatChanged e) {
        if (e.getSkill() != Skill.FARMING) return;
        int old = lastFarmingXp;
        lastFarmingXp = e.getXp();
        if (old < 0 || e.getXp() <= old) return;
        RouteStep step = activeFarmStep();
        if (step == null || clickedPatchId != step.getFarmPatchId()
            || client.getTickCount() - clickTick > CLICK_WINDOW_TICKS) return;
        if (!step.isFarmReplant()) tendedStep = step;
    }

    @Subscribe
    public void onChatMessage(ChatMessage e) {
        if (e.getType() != ChatMessageType.SPAM && e.getType() != ChatMessageType.GAMEMESSAGE) return;
        if (!Text.removeTags(e.getMessage()).startsWith("You plant ")) return;
        RouteStep step = activeFarmStep();
        if (step == null || !step.isFarmReplant() || clickedPatchId != step.getFarmPatchId()
            || client.getTickCount() - clickTick > CLICK_WINDOW_TICKS) return;
        finish(step);
    }

    @Subscribe
    public void onGameTick(GameTick e) {
        RouteStep step = activeFarmStep();
        if (step != null && step.farmPatchUnresolved()) {
            resolvePatch(step);
            return;
        }
        if (step == null || step != tendedStep || step.isFarmReplant()) return;
        // The patch changes look a tick or so after the XP: wait until it has no work left
        if (!hasWorkLeft(step.getFarmPatchId())) finish(step);
    }

    /** How far from the step's tile its patch may be, when it's given by place rather than id. */
    private static final int RESOLVE_RADIUS = 8;

    /** Find the farming patch nearest the step's tile once it's in the scene, and keep its id. */
    private void resolvePatch(RouteStep step) {
        WorldPoint at = step.getWorldPoint();
        WorldView wv = client.getTopLevelWorldView();
        if (at == null || wv == null || wv.getScene() == null || wv.isInstance() || at.getPlane() != wv.getPlane()) return;
        Tile[][] plane = wv.getScene().getTiles()[wv.getPlane()];
        int cx = at.getX() - wv.getBaseX(), cy = at.getY() - wv.getBaseY();
        int best = -1, bestDist = Integer.MAX_VALUE;
        for (int x = Math.max(0, cx - RESOLVE_RADIUS); x <= Math.min(plane.length - 1, cx + RESOLVE_RADIUS); x++) {
            for (int y = Math.max(0, cy - RESOLVE_RADIUS); y <= Math.min(plane[x].length - 1, cy + RESOLVE_RADIUS); y++) {
                Tile tile = plane[x][y];
                if (tile == null || tile.getGameObjects() == null) continue;
                for (GameObject obj : tile.getGameObjects()) {
                    if (!SceneObjects.isObject(obj) || !FarmingPatches.isPatch(obj.getId())) continue;
                    // Distance to the nearest of the patch's tiles (tree patches are 3x3 and bigger)
                    int dx = Math.max(0, Math.max(obj.getSceneMinLocation().getX() - cx, cx - obj.getSceneMaxLocation().getX()));
                    int dy = Math.max(0, Math.max(obj.getSceneMinLocation().getY() - cy, cy - obj.getSceneMaxLocation().getY()));
                    int d = Math.max(dx, dy);
                    if (d < bestDist) { bestDist = d; best = obj.getId(); }
                }
            }
        }
        if (best < 0) return; // not loaded yet, or no patch there
        step.setFarmPatchId(best);
        plugin.saveRoutes();
    }

    private void finish(RouteStep step) {
        step.setFarmDone(true);
        step.setLocationReached(true); // worked the patch, so it was reached, from whichever side
        tendedStep = null;
        plugin.tryCompleteActiveStep(step);
    }

    private RouteStep activeFarmStep() {
        Route route = plugin.getActiveRoute();
        RouteStep step = route == null ? null : route.getActiveStep();
        return step != null && step.hasFarmPatch() && !step.isFarmDone() ? step : null;
    }

    /** Whether the patch, as it looks now, still has something to pick, harvest, check or rake. */
    private boolean hasWorkLeft(int patchId) {
        ObjectComposition comp = client.getObjectDefinition(patchId);
        if (comp != null && comp.getImpostorIds() != null) comp = comp.getImpostor();
        if (comp == null || comp.getActions() == null) return false;
        for (String a : comp.getActions()) {
            if (a == null) continue;
            String l = a.toLowerCase();
            // Not "Clear" or "Chop down": a grown bush or tree always offers them
            if (l.startsWith("pick") || l.startsWith("harvest") || l.equals("check-health")
                || l.equals("rake") || l.equals("cure") || l.equals("take") || l.equals("collect")) return true;
        }
        return false;
    }

    /** "Torstol seed -> Herb patch": the item used, "Torstol seed". */
    public static String usedItem(String target) {
        if (target == null) return null;
        int arrow = target.indexOf("->");
        return arrow < 0 ? null : target.substring(0, arrow).trim();
    }

    private static boolean isObjectAction(MenuAction a) {
        switch (a) {
            case GAME_OBJECT_FIRST_OPTION:
            case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:
            case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION:
            case WIDGET_TARGET_ON_GAME_OBJECT:
                return true;
            default:
                return false;
        }
    }
}

package com.routeplanner.hub;

/**
 * Thrown by {@link RouteHubFetcher} on any failure: network, HTTP, oversized payload, or an
 * unsafe path. The message is written to be shown directly to the user, never a stack trace.
 */
public class HubFetchException extends Exception {
    public HubFetchException(String message) {
        super(message);
    }
}

package com.routeplanner.hub;

import java.util.List;

/**
 * Deserialized shape of index.json from the Route Hub repo. Field names must match the JSON
 * exactly since Gson binds by name. Anything the catalog doesn't recognize (a newer schemaVersion,
 * or fields added later) is simply ignored by Gson rather than causing a parse failure.
 */
public class HubIndex {
    public int schemaVersion;
    public List<HubRouteEntry> routes;
}

package com.routeplanner.hub;

import com.routeplanner.util.RouteTextValidator;
import java.util.List;

/**
 * One catalog entry from index.json. It comes from the network, so nothing in it is trusted until
 * {@link HubRouteEntry#validate()} has checked the name/description length and step count and
 * scanned every free-text field for links.
 */
public class HubRouteEntry {
    public String id;
    public String name;
    public String author;
    public String description;
    public String icon;
    public String file;
    public int steps;
    public List<String> tags;
    public String updated;

    private static final int MAX_NAME_LEN = 100;
    private static final int MAX_DESC_LEN = 120;
    private static final int MAX_STEPS = 10_000;

    /**
     * @return null if the entry is safe to display/install, or a short reason if it should be
     * rejected. Never throws: a malformed catalog entry should be skipped, not crash the panel.
     */
    public String validate() {
        if (id == null || id.isEmpty()) return "missing id";
        if (id.contains("..") || id.contains("/") || id.contains("\\")) return "unsafe id";
        if (name == null || name.isEmpty()) return "missing name";
        if (name.length() > MAX_NAME_LEN) return "name too long";
        if (author == null || author.isEmpty()) return "missing author";
        if (description == null) return "missing description";
        if (description.length() > MAX_DESC_LEN) return "description too long";
        if (file == null || file.isEmpty() || file.contains("..") || file.startsWith("/")) return "unsafe file path";
        if (icon != null && (icon.contains("..") || icon.startsWith("/"))) return "unsafe icon path";
        if (steps < 0 || steps > MAX_STEPS) return "step count out of bounds";

        String linkErr = RouteTextValidator.checkField("Route name", name);
        if (linkErr == null) linkErr = RouteTextValidator.checkField("Description", description);
        if (linkErr == null && author != null) linkErr = RouteTextValidator.checkField("Author", author);
        if (linkErr != null) return linkErr;

        return null;
    }
}

package com.routeplanner.hub;

import lombok.RequiredArgsConstructor;
import com.google.gson.*;
import lombok.extern.slf4j.Slf4j;
import javax.inject.*;
import java.util.*;

/**
 * Fetches and parses the Route Hub catalog. Entries that fail {@link HubRouteEntry#validate()} are
 * dropped rather than shown or installed: a bad entry should never reach the browse panel or the
 * install path, even if it somehow got past PR review.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RouteHubCatalog {

    private final RouteHubFetcher fetcher;
    private final Gson gson;

    /** Fetches, parses, and validates the catalog. Never returns null; returns an empty list on
     *  total failure so the panel can show "couldn't load" rather than crash. */
    /** Passthrough to the fetcher for icon bytes, keeping RouteHubPanel from needing to know about
     *  RouteHubFetcher directly; it only ever talks to the catalog. */
    public byte[] fetchIconBytes(String relativeIconPath) throws HubFetchException {
        return fetcher.fetchIcon(relativeIconPath);
    }

    /** Passthrough to the fetcher for a route file's raw JSON. Deserialization and validation are
     *  the caller's responsibility (RouteHubPanel uses plugin.getRouteGson() and
     *  validateFetchedRoute()), since RouteHubCatalog only knows about catalog-level shape. */
    public String fetchRouteJson(String relativeRoutePath) throws HubFetchException {
        return fetcher.fetchRoute(relativeRoutePath);
    }

    public List<HubRouteEntry> loadValidEntries() throws HubFetchException {
        String json = fetcher.fetchIndex();
        HubIndex index;
        try {
            index = gson.fromJson(json, HubIndex.class);
        } catch (JsonSyntaxException e) {
            log.warn("Route Hub index.json failed to parse", e);
            throw new HubFetchException("The Route Hub catalog is malformed and couldn't be read.");
        }
        if (index == null || index.routes == null) {
            throw new HubFetchException("The Route Hub catalog is empty or malformed.");
        }

        List<HubRouteEntry> valid = new ArrayList<>();
        for (HubRouteEntry entry : index.routes) {
            if (entry == null) continue;
            String err = entry.validate();
            if (err != null) {
                log.warn("Skipping invalid Route Hub entry (id={}): {}", entry.id, err);
                continue;
            }
            valid.add(entry);
        }
        return valid;
    }
}

package com.routeplanner.hub;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;
import javax.inject.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

/**
 * Read-only GETs against the Route Hub's GitHub-hosted catalog. Every call is a plain HTTP GET to
 * raw.githubusercontent.com; nothing is ever uploaded or posted. Bounds (payload size caps) are
 * enforced here so a malformed or oversized response can never wedge the panel; callers get a
 * {@link HubFetchException} instead of a crash, with a message safe to show the user directly.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RouteHubFetcher {

    /** Base raw-content URL for the curated routes repo, branch pinned to avoid surprise changes. */
    private static final String BASE_URL =
        "https://raw.githubusercontent.com/BlackDeath-Osrs/route-planner-routes/main/";

    // Size caps: a response bigger than these is rejected.
    private static final long MAX_INDEX_BYTES = 1_500_000;   // ~1 MB catalog, some headroom
    private static final long MAX_ROUTE_BYTES = 15_000_000;  // 10,000 steps at up to ~1.5 KB each
    private static final long MAX_ICON_BYTES = 25_000;       // 20 KB icon cap, some headroom

    private final OkHttpClient okHttpClient;

    /** Fetches index.json as raw text. Caller is responsible for JSON parsing + schema validation. */
    public String fetchIndex() throws HubFetchException {
        return fetchText("index.json", MAX_INDEX_BYTES, "route catalog");
    }

    /** Fetches a single route file (path as given in index.json's "file" field) as raw text. */
    public String fetchRoute(String relativePath) throws HubFetchException {
        requireSafeRelativePath(relativePath);
        return fetchText(relativePath, MAX_ROUTE_BYTES, "route");
    }

    /** Fetches an icon (path as given in index.json's "icon" field) as raw bytes. */
    public byte[] fetchIcon(String relativePath) throws HubFetchException {
        requireSafeRelativePath(relativePath);
        return fetchBytes(relativePath, MAX_ICON_BYTES, "icon");
    }

    // ---- internals ----

    /**
     * index.json and route "file"/"icon" entries are relative paths we build a URL from. Reject
     * anything that looks like it is trying to escape the repo (".." segments) or specify a whole
     * new host (a scheme or a leading "//"): the catalog must only ever point within itself.
     */
    private void requireSafeRelativePath(String relativePath) throws HubFetchException {
        if (relativePath == null || relativePath.isEmpty()
            || relativePath.contains("..")
            || relativePath.startsWith("/")
            || relativePath.contains("://")) {
            throw new HubFetchException("The Route Hub catalog referenced an invalid file path.");
        }
    }

    private String fetchText(String relativePath, long maxBytes, String what) throws HubFetchException {
        byte[] bytes = fetchBytes(relativePath, maxBytes, what);
        return new String(bytes, StandardCharsets.UTF_8);
    }

    private byte[] fetchBytes(String relativePath, long maxBytes, String what) throws HubFetchException {
        Request request = new Request.Builder().url(BASE_URL + relativePath).build();
        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new HubFetchException("Couldn't reach the Route Hub (the " + what + " wasn't found or the server had an error).");
            }
            if (response.body() == null) {
                throw new HubFetchException("The Route Hub sent back an empty response for the " + what + ".");
            }
            long declaredLength = response.body().contentLength();
            if (declaredLength > maxBytes) {
                throw new HubFetchException("The " + what + " from the Route Hub was too large to load safely.");
            }
            byte[] data = response.body().bytes();
            if (data.length > maxBytes) {
                throw new HubFetchException("The " + what + " from the Route Hub was too large to load safely.");
            }
            return data;
        } catch (IOException e) {
            log.warn("Route Hub fetch failed for {}", relativePath, e);
            throw new HubFetchException("Couldn't connect to the Route Hub. Check your connection and try again.");
        }
    }
}

package com.routeplanner.hub;

import static com.routeplanner.ui.Ui.*;

import com.routeplanner.util.*;
import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import javax.imageio.ImageIO;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.event.*;
import java.awt.*;
import java.awt.event.*;
import java.io.ByteArrayInputStream;
import java.util.*;
import java.util.List;

/**
 * The Route Hub browse view: fetches the catalog of shared routes and lists them with their icons,
 * a search box and install/remove buttons. Network work runs off the EDT via SwingWorker.
 */
@Slf4j
public class RouteHubPanel extends JPanel {

    private final RoutePlannerPlugin plugin;
    private final RouteHubCatalog catalog;
    private final Runnable onBack;
    private final JPanel listPanel;
    private final JLabel statusLabel;
    private boolean loadedOnce = false;
    private JLabel footerLabel;
    private JButton back;

    /** Hidden when the Hub lives in its own tab, where there's nothing to go back to. */
    public void setBackVisible(boolean visible) {
        back.setVisible(visible);
    }

    public RouteHubPanel(RoutePlannerPlugin plugin, RouteHubCatalog catalog, Runnable onBack) {
        this.plugin = plugin;
        this.catalog = catalog;
        this.onBack = onBack;

        setLayout(new BorderLayout(0, 8));
        setBorder(new EmptyBorder(8, 8, 8, 8));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        back = new JButton("\u2039 Back");
        back.setForeground(new Color(255, 152, 31));
        back.setBorderPainted(false);
        back.setContentAreaFilled(false);
        back.setFocusPainted(false);
        back.setCursor(new Cursor(Cursor.HAND_CURSOR));
        back.addActionListener(e -> onBack.run());

        JLabel title = new JLabel("Route Hub");
        title.setForeground(Color.WHITE);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 14f));

        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.add(back, BorderLayout.WEST);
        header.add(title, BorderLayout.CENTER);

        JPanel topStack = bare(new JPanel());
        topStack.setLayout(new BoxLayout(topStack, BoxLayout.Y_AXIS));
        JTextField search = new JTextField();
        search.setBackground(ColorScheme.DARK_GRAY_COLOR.brighter());
        search.setForeground(Color.WHITE);
        search.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(60, 60, 60), 1),
            new EmptyBorder(5, 7, 5, 7)));
        search.putClientProperty("JTextField.placeholderText", "Search routes\u2026");
        search.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) { applyFilter(search.getText()); }
            public void removeUpdate(DocumentEvent e) { applyFilter(search.getText()); }
            public void changedUpdate(DocumentEvent e) { applyFilter(search.getText()); }
        });
        JPanel searchWrap = bare(new JPanel(new BorderLayout()));
        searchWrap.setBorder(new EmptyBorder(6, 0, 0, 0));
        searchWrap.add(search, BorderLayout.CENTER);

        topStack.add(header);
        topStack.add(searchWrap);
        add(topStack, BorderLayout.NORTH);

        statusLabel = new JLabel("Loading\u2026");
        statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        statusLabel.setBorder(new EmptyBorder(10, 4, 10, 4));

        listPanel = new JPanel();
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        listPanel.add(statusLabel);

        JScrollPane scroll = new JScrollPane(listPanel);
        scroll.setBorder(null);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.getVerticalScrollBar().setUnitIncrement(12);
        add(scroll, BorderLayout.CENTER);

        footerLabel = new JLabel(" ");
        footerLabel.setForeground(Color.WHITE);
        footerLabel.setFont(footerLabel.getFont().deriveFont(9.5f));
        footerLabel.setBorder(new EmptyBorder(6, 2, 2, 2));
        footerLabel.setHorizontalAlignment(SwingConstants.CENTER);
        footerLabel.setToolTipText("The date the Route Hub catalog was last changed \u2014 "
            + "not necessarily this specific route.");

        JPanel bottomStack = bare(new JPanel());
        bottomStack.setLayout(new BoxLayout(bottomStack, BoxLayout.Y_AXIS));
        bottomStack.add(footerLabel);
        bottomStack.add(buildWarningBanner());
        add(bottomStack, BorderLayout.SOUTH);
    }

    /** Called each time the Hub view is switched to; the catalog is loaded on the first visit only. */
    public void onShown() {
        if (loadedOnce) return;
        loadedOnce = true;
        load();
    }

    // Decoded icons by entry id, so redrawing the list doesn't fetch them again. Small enough to keep.
    private final Map<String, ImageIcon> iconCache = new HashMap<>();
    private List<HubRouteEntry> allEntries = Collections.emptyList();

    /** Fetches and decodes one entry's icon off the EDT, then swaps it into the label. On any
     *  failure the placeholder stays. */
    private void loadIconInto(JLabel target, HubRouteEntry entry) {
        ImageIcon cached = iconCache.get(entry.id);
        if (cached != null) {
            target.setIcon(cached);
            return;
        }
        if (entry.icon == null || entry.icon.isEmpty()) return;

        new SwingWorker<ImageIcon, Void>() {
            @Override
            protected ImageIcon doInBackground() {
                try {
                    byte[] bytes = catalog.fetchIconBytes(entry.icon);
                    Image img = ImageIO.read(new ByteArrayInputStream(bytes));
                    if (img == null) return null; // not a decodable image
                    if (img.getWidth(null) <= 0 || img.getHeight(null) <= 0) return null;
                    Image scaled = img.getScaledInstance(48, 48, Image.SCALE_SMOOTH);
                    return new ImageIcon(scaled);
                } catch (Exception e) {
                    return null;
                }
            }

            @Override
            protected void done() {
                try {
                    ImageIcon icon = get();
                    if (icon == null) return; // leave the placeholder as-is
                    iconCache.put(entry.id, icon);
                    target.setIcon(icon);
                } catch (Exception e) {
                    // failed or cancelled: the placeholder stays
                }
            }
        }.execute();
    }

    private static final int MAX_STEPS = 10_000;
    private static final int MAX_NOTE_LEN = 280;
    private static final int MAX_NAME_LEN = 100;

    /**
     * Checks every free-text field of every step in a fetched route, whatever the catalog already
     * checked: a route from the network is never trusted as is. Returns null if it's safe to
     * install, or a short reason to show the user if not.
     */
    private String validateFetchedRoute(Route route) {
        if (route == null || route.getName() == null) return "The route file is empty or malformed.";
        if (route.getName().length() > MAX_NAME_LEN) return "The route's name is too long.";

        String nameErr = RouteTextValidator.checkField("Route name", route.getName());
        if (nameErr != null) return nameErr;

        int totalSteps = 0;
        List<RouteSection> sections = route.getSections();
        if (sections == null) return null; // an empty route is unusual but not unsafe

        for (RouteSection section : sections) {
            if (section == null || section.getSteps() == null) continue;

            String secErr = RouteTextValidator.checkField("Section name", section.getName());
            if (secErr != null) return secErr;

            for (RouteStep step : section.getSteps()) {
                if (step == null) continue;
                totalSteps++;
                if (totalSteps > MAX_STEPS) return "This route has too many steps.";

                if (step.getName() != null && step.getName().length() > MAX_NAME_LEN) {
                    return "A step name is too long.";
                }
                if (step.getNoteText() != null && step.getNoteText().length() > MAX_NOTE_LEN) {
                    return "A step's note is too long.";
                }

                String err = RouteTextValidator.checkField("Step name", step.getName());
                if (err == null) err = RouteTextValidator.checkField("Note", step.getNoteText());
                if (err == null) err = RouteTextValidator.checkField("Highlight NPC", step.getNpcHighlight());
                if (err == null) err = RouteTextValidator.checkField("Dialogue options", step.getDialogOptions());
                if (err == null) err = RouteTextValidator.checkField("Items", step.getItemList());
                if (err == null) err = RouteTextValidator.checkField("Inventory items", step.getInventoryHighlightItems());
                if (err != null) return err;
            }
        }
        return null;
    }

    private void load() {
        new SwingWorker<List<HubRouteEntry>, Void>() {
            private HubFetchException failure;

            @Override
            protected List<HubRouteEntry> doInBackground() {
                try {
                    return catalog.loadValidEntries();
                } catch (HubFetchException e) {
                    failure = e;
                    return null;
                }
            }

            @Override
            protected void done() {
                listPanel.remove(statusLabel);
                if (failure != null) {
                    showMessage(failure.getMessage());
                    return;
                }
                List<HubRouteEntry> entries;
                try {
                    entries = get();
                } catch (Exception e) {
                    log.warn("Route Planner: loading the Route Hub failed", e);
                    showMessage("Something went wrong loading the Route Hub.");
                    return;
                }
                if (entries == null || entries.isEmpty()) {
                    showMessage("No routes are available yet.");
                    return;
                }
                allEntries = entries;
                applyFilter("");
                updateFooter(entries);
            }
        }.execute();
    }

    /** Rebuilds the list from allEntries, keeping rows whose name, description, author or tags
     *  contain the query (ignoring case). */
    private void applyFilter(String query) {
        listPanel.removeAll();
        String q = query == null ? "" : query.trim().toLowerCase();

        List<HubRouteEntry> matches = new ArrayList<>();
        for (HubRouteEntry entry : allEntries) {
            if (q.isEmpty() || matchesQuery(entry, q)) matches.add(entry);
        }

        if (matches.isEmpty()) {
            showMessage(q.isEmpty() ? "No routes are available yet." : "No routes match \"" + query + "\".");
        } else {
            for (HubRouteEntry entry : matches) {
                listPanel.add(buildRow(entry));
                listPanel.add(Box.createVerticalStrut(6));
            }
        }
        listPanel.revalidate();
        listPanel.repaint();
    }

    private boolean matchesQuery(HubRouteEntry entry, String lowerQuery) {
        if (entry.name != null && entry.name.toLowerCase().contains(lowerQuery)) return true;
        if (entry.description != null && entry.description.toLowerCase().contains(lowerQuery)) return true;
        if (entry.author != null && entry.author.toLowerCase().contains(lowerQuery)) return true;
        if (entry.tags != null) {
            for (String tag : entry.tags) {
                if (tag != null && tag.toLowerCase().contains(lowerQuery)) return true;
            }
        }
        return false;
    }

    /** A small footer with the catalog's most recent "updated" date. */
    private void updateFooter(List<HubRouteEntry> entries) {
        String latest = null;
        for (HubRouteEntry entry : entries) {
            if (entry.updated == null || entry.updated.isEmpty()) continue;
            if (latest == null || entry.updated.compareTo(latest) > 0) latest = entry.updated;
        }
        footerLabel.setText(latest != null ? "Route Hub last updated " + latest : " ");
    }

    private void showMessage(String text) {
        JLabel msg = new JLabel(text);
        msg.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        msg.setBorder(new EmptyBorder(10, 4, 10, 4));
        listPanel.add(msg);
        listPanel.revalidate();
        listPanel.repaint();
    }

    /** The "Community content" notice: open by default, folds to one line with the chevron, and
     *  remembers which. Shown the whole time the Hub is browsed, so installs need no confirm box. */
    private JPanel buildWarningBanner() {
        JPanel banner = new JPanel(new BorderLayout());
        banner.setBackground(new Color(42, 36, 22));
        banner.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(90, 74, 31), 1),
            new EmptyBorder(0, 0, 0, 0)));

        JLabel label = new JLabel("\u26a0 Community content");
        label.setForeground(new Color(255, 204, 102));
        label.setFont(label.getFont().deriveFont(Font.BOLD, 11f));
        label.setBorder(new EmptyBorder(8, 10, 8, 4));

        JLabel chevron = new JLabel();
        chevron.setForeground(new Color(216, 201, 143));
        chevron.setFont(chevron.getFont().deriveFont(11f));
        chevron.setBorder(new EmptyBorder(8, 4, 8, 10));
        chevron.setCursor(new Cursor(Cursor.HAND_CURSOR));

        JPanel head = bare(new JPanel(new BorderLayout()));
        head.add(label, BorderLayout.WEST);
        head.add(chevron, BorderLayout.EAST);
        head.setCursor(new Cursor(Cursor.HAND_CURSOR));

        String warningText = "These routes are made by other players, not by Route Planner. "
            + "Submissions are reviewed and links are blocked, but always be cautious \u2014 never "
            + "follow a step that asks you to visit a website, share your account, or do anything "
            + "outside the game.";

        JLabel body = new JLabel("<html><div style=\'width:180px;\'>" + warningText + "</div></html>");
        body.setForeground(new Color(216, 201, 143));
        body.setFont(body.getFont().deriveFont(10.5f));
        body.setBorder(new EmptyBorder(0, 10, 10, 10));

        // Small text to fit the width; the tooltip repeats it at a readable size.
        String tooltipHtml = "<html><div style=\'width:220px;\'>" + warningText + "</div></html>";
        body.setToolTipText(tooltipHtml);
        label.setToolTipText(tooltipHtml);

        banner.add(head, BorderLayout.NORTH);
        banner.add(body, BorderLayout.CENTER);

        Runnable applyState = () -> {
            boolean collapsed = plugin.isHubWarningCollapsed();
            body.setVisible(!collapsed);
            chevron.setText(collapsed ? "\u25b8" : "\u25be");
        };
        applyState.run();

        MouseAdapter toggle = new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                plugin.setHubWarningCollapsed(!plugin.isHubWarningCollapsed());
                applyState.run();
                banner.revalidate();
                banner.repaint();
            }
        };
        head.addMouseListener(toggle);
        chevron.addMouseListener(toggle);

        return banner;
    }

    private JPanel buildRow(HubRouteEntry entry) {
        JPanel row = new JPanel(new BorderLayout(10, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        // Little right padding, so the install "+" sits near the edge.
        row.setBorder(new EmptyBorder(9, 9, 9, -6));

        // Fixed-size icon, wrapped in a panel so BorderLayout cannot stretch it to the row's height.
        JLabel iconLabel = new JLabel();
        iconLabel.setOpaque(true);
        iconLabel.setBackground(new Color(45, 55, 65));
        iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
        iconLabel.setBorder(BorderFactory.createLineBorder(new Color(60, 70, 80), 1));
        loadIconInto(iconLabel, entry);
        JPanel iconBox = bare(new JPanel());
        iconBox.setLayout(new BoxLayout(iconBox, BoxLayout.Y_AXIS));
        iconLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        iconLabel.setMaximumSize(new Dimension(48, 48));
        iconLabel.setPreferredSize(new Dimension(48, 48));
        iconLabel.setMinimumSize(new Dimension(48, 48));
        iconBox.add(iconLabel);
        iconBox.add(Box.createVerticalStrut(6));
        // The install button goes under the icon (added below), leaving the text side its full width.

        JLabel name = left(new JLabel(HighlightColors.escapeHtml(entry.name)));
        name.setForeground(Color.WHITE);
        name.setFont(name.getFont().deriveFont(Font.BOLD, 13.5f));

        JLabel desc = left(new JLabel(HighlightColors.escapeHtml(entry.description)));
        desc.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        desc.setFont(desc.getFont().deriveFont(12f));
        desc.setBorder(new EmptyBorder(2, 0, 2, 0));
        desc.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));
        desc.setPreferredSize(new Dimension(0, 16));

        JLabel installBtn = buildInstallControl(entry);
        installBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
        // "by X · N steps" is the name's tooltip: the row is too narrow to show it. Plain text, no escaping.
        String subInfo = "by " + entry.author + " \u00b7 " + entry.steps + " steps";
        name.setToolTipText(subInfo);
        // The description can be cut off, so its tooltip shows all of it.
        desc.setToolTipText("<html><div style=\'width:220px;\'>" + HighlightColors.escapeHtml(entry.description) + "</div></html>");
        installBtn.setToolTipText("Install this route (" + subInfo + ")");
        iconBox.add(installBtn);

        JPanel textCol = bare(new JPanel());
        textCol.setLayout(new BoxLayout(textCol, BoxLayout.Y_AXIS));
        textCol.add(name);
        textCol.add(desc);

        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 95));
        row.setPreferredSize(new Dimension(0, 95));
        row.add(iconBox, BorderLayout.WEST);
        row.add(textCol, BorderLayout.CENTER);
        return row;
    }

    /** The installed route (if any) whose hubSourceId matches this catalog entry. Read from the
     *  route list itself, so deleting the route by hand turns the button back to Install. */
    private Route findInstalled(HubRouteEntry entry) {
        for (Route r : plugin.getRoutes()) {
            if (entry.id.equals(r.getHubSourceId())) return r;
        }
        return null;
    }

    /** Install/Remove control: green "+" when the route isn't in plugin.getRoutes(), red "-" when it is. */
    private JLabel buildInstallControl(HubRouteEntry entry) {
        JLabel btn = new JLabel();
        btn.setOpaque(true);
        btn.setFont(btn.getFont().deriveFont(Font.BOLD, 13f));
        btn.setHorizontalAlignment(SwingConstants.CENTER);
        btn.setCursor(new Cursor(Cursor.HAND_CURSOR));
        btn.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                Route existing = findInstalled(entry);
                if (existing != null) {
                    removeInstalled(entry, existing, btn);
                } else {
                    installEntry(entry, btn);
                }
            }
        });
        refreshInstallControl(btn, entry);
        return btn;
    }

    /** Sets the control's icon/colors/tooltip to match whether entry is currently installed. */
    private void refreshInstallControl(JLabel btn, HubRouteEntry entry) {
        boolean installed = findInstalled(entry) != null;
        if (installed) {
            btn.setText("\u2212"); // minus sign
            btn.setForeground(new Color(224, 159, 159));
            btn.setBackground(new Color(74, 46, 46));
            btn.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(107, 63, 63), 1),
                new EmptyBorder(1, 8, 1, 8)));
            btn.setToolTipText("Remove this route");
        } else {
            btn.setText("+");
            btn.setForeground(new Color(159, 224, 159));
            btn.setBackground(new Color(46, 74, 46));
            btn.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(63, 107, 63), 1),
                new EmptyBorder(1, 8, 1, 8)));
            btn.setToolTipText("Install this route");
        }
    }

    /** Fetches the route file, checks it, and installs it the same way a file import does (add,
     *  save, activate). Runs off the EDT. */
    private void installEntry(HubRouteEntry entry, JLabel btn) {
        btn.setEnabled(false);
        new SwingWorker<Void, Void>() {
            private String failureMessage;
            private Route parsedRoute;

            @Override
            protected Void doInBackground() {
                try {
                    String json = catalog.fetchRouteJson(entry.file);
                    Route route = plugin.getRouteGson().fromJson(json, Route.class);
                    if (route == null) {
                        failureMessage = "The route file is empty or malformed.";
                        return null;
                    }
                    route.migrateIfNeeded();
                    String err = validateFetchedRoute(route);
                    if (err != null) {
                        failureMessage = "This route couldn't be installed: " + err;
                        return null;
                    }
                    route.setHubSourceId(entry.id);
                    String name = route.getName();
                    boolean exists = plugin.getRoutes().stream().anyMatch(r -> r.getName().equalsIgnoreCase(name));
                    if (exists) route.setName(name + " (Hub)");
                    parsedRoute = route;
                } catch (HubFetchException e) {
                    failureMessage = e.getMessage();
                } catch (Exception e) {
                    log.warn("Failed to install hub route {}", entry.id, e);
                    failureMessage = "Something went wrong installing this route.";
                }
                return null;
            }

            @Override
            protected void done() {
                btn.setEnabled(true);
                if (failureMessage != null) {
                    JOptionPane.showMessageDialog(RouteHubPanel.this, failureMessage,
                        "Install failed", JOptionPane.WARNING_MESSAGE);
                    return;
                }
                plugin.getRoutes().add(parsedRoute);
                plugin.saveRoutes();
                plugin.setActiveRoute(parsedRoute);
                refreshInstallControl(btn, entry);
            }
        }.execute();
    }

    /** Removes a hub-installed route through plugin.deleteRoute(), like "Delete Route" in the
     *  route list: it also clears the active route, its undo history, and refreshes the panel. */
    private void removeInstalled(HubRouteEntry entry, Route route, JLabel btn) {
        int confirm = JOptionPane.showConfirmDialog(this,
            "Remove \"" + route.getName() + "\" from your routes?",
            "Remove route", JOptionPane.YES_NO_OPTION);
        if (confirm != JOptionPane.YES_OPTION) return;

        plugin.deleteRoute(route);
        refreshInstallControl(btn, entry);
    }

    /** Escapes markup in catalog text, which is shown in HTML-rendering JLabels. */
}

package com.routeplanner.model;

/** How an items step's list is met. Saved by name, so these names must never change. */
public enum ItemMode {
    /** Fetch from the bank: done while the inventory holds them. */
    BANK,
    /** Buy from a shop: counts items gained since the step started. */
    SHOP,
    /** Sell to a shop: done once they've been carried and then gone. */
    SELL,
    /** Pick up or gather: counts items gained since the step started. */
    PICKUP,
    /** Deposit everything at any bank; no list. */
    DEPOSIT_ALL,
    /** Use them all up (clean, note, drop...): done once none are left unnoted in the inventory. */
    USE_UP
}

package com.routeplanner.model;

import lombok.RequiredArgsConstructor;
import java.util.Locale;
import java.util.regex.*;

/**
 * A value the game keeps that shows a step is done, written the way it's saved on the step:
 * <ul>
 *   <li>{@code "varbit 3185 >= 4"}: a quest has reached stage 4 (quests keep their stage in a
 *   varbit or a varplayer).</li>
 *   <li>{@code "varp 107 >= 5"}: the same, for a quest kept in a varplayer.</li>
 *   <li>{@code "varp 1194 bit 6"}: an achievement diary task (each region's tasks are bits of one
 *   varplayer).</li>
 * </ul>
 */
@RequiredArgsConstructor
public final class ProgressCheck {

    public enum Kind { VARBIT, VARP }

    private static final Pattern AT_LEAST = Pattern.compile("^(varbit|varp)\\s+(\\d+)\\s*>=\\s*(\\d+)$");
    private static final Pattern BIT = Pattern.compile("^varp\\s+(\\d+)\\s+bit\\s+(\\d{1,2})$");

    public final Kind kind;
    public final int id;
    /** The bit that must be set (0-31), or -1 to compare the whole value. */
    public final int bit;
    /** The value the var must reach, when not a bit. */
    public final int atLeast;

    /** The check written in {@code text}, or null if it isn't one. */
    public static ProgressCheck parse(String text) {
        if (text == null) return null;
        String t = text.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
        try {
            Matcher m = AT_LEAST.matcher(t);
            if (m.matches()) {
                return new ProgressCheck(m.group(1).equals("varbit") ? Kind.VARBIT : Kind.VARP,
                    Integer.parseInt(m.group(2)), -1, Integer.parseInt(m.group(3)));
            }
            m = BIT.matcher(t);
            if (m.matches()) {
                int bit = Integer.parseInt(m.group(2));
                return bit < 32 ? new ProgressCheck(Kind.VARP, Integer.parseInt(m.group(1)), bit, 0) : null;
            }
        } catch (NumberFormatException e) {
            return null; // a number too big for an int
        }
        return null;
    }

    /** Whether the var's current value meets the check. */
    public boolean isMet(int value) {
        return bit >= 0 ? (value & (1 << bit)) != 0 : value >= atLeast;
    }

    @Override
    public String toString() {
        String var = (kind == Kind.VARBIT ? "varbit " : "varp ") + id;
        return bit >= 0 ? var + " bit " + bit : var + " >= " + atLeast;
    }
}

package com.routeplanner.model;

import com.google.gson.annotations.SerializedName;
import com.routeplanner.agility.AgilityCoursePresets;
import lombok.Data;
import net.runelite.api.coords.WorldPoint;
import java.util.*;

@Data
public class Route {
    private String name;
    private List<RouteSection> sections = new ArrayList<>();

    /** Set only when this route was installed from the Route Hub; holds the hub catalog's entry id.
     *  Null for manually created or file-imported routes. This is how the browse panel knows a route
     *  is already installed (and can offer Remove instead of Install) without a second, separate
     *  persisted set that could drift out of sync with the real route list. */
    private String hubSourceId;
    private boolean repeatable = false; // if true, resets and restarts when last step completes

    // Developer test: while set, this step stands in as the active step, wherever it is in the
    // route and whether or not it's ticked. Never saved, so a restart always resumes the route.
    private transient RouteStep testStep;
    private transient boolean testPassed;
    // Re-recording a section: while set, the route guides through this section only (its first
    // unticked step is the active one, null once it's all done). Never saved.
    private transient RouteSection focusSection;

    // Legacy flat-step format; migrated into a default section on load.
    @SerializedName("steps")
    private List<RouteStep> legacySteps;

    public Route(String name) {
        this.name = name;
    }

    /** Routes are told apart by identity: two routes with the same contents are still two routes. */
    @Override
    public boolean equals(Object o) {
        return this == o;
    }

    @Override
    public int hashCode() {
        return System.identityHashCode(this);
    }

    public List<RouteStep> getAllSteps() {
        List<RouteStep> all = new ArrayList<>();
        if (sections != null) {
            for (RouteSection sec : sections) {
                if (sec.getSteps() != null) all.addAll(sec.getSteps());
            }
        }
        return all;
    }

    /** Flattened read accessor used across the codebase. */
    public List<RouteStep> getSteps() {
        return getAllSteps();
    }

    public void migrateIfNeeded() {
        if (sections == null) sections = new ArrayList<>();
        if (sections.isEmpty() && legacySteps != null && !legacySteps.isEmpty()) {
            RouteSection def = new RouteSection(UUID.randomUUID().toString(), "Steps");
            def.getSteps().addAll(legacySteps);
            sections.add(def);
        }
        legacySteps = null;
        // Every step names the section it's in (older saves and hand-written files may not)
        for (RouteSection sec : sections) {
            if (sec.getSteps() == null) continue;
            for (RouteStep st : sec.getSteps()) {
                if (sec.getId() != null && !sec.getId().equals(st.getSectionId())) st.setSectionId(sec.getId());
                st.migrateUseUp();
                st.migrateFarmPatch();
            }
        }
        // Agility steps saved with the old StepType.AGILITY load with type==null: turn them into
        // skilling steps (skill=AGILITY) at the course's start.
        for (RouteSection sec : sections) {
            if (sec.getSteps() == null) continue;
            for (RouteStep st : sec.getSteps()) {
                if (st.getType() == null && st.getAgilityCourse() != null) {
                    st.setType(StepType.SKILLING);
                    st.setSkillingSkill("AGILITY");
                    SkillGoalType goal = SkillGoalType.parse(st.getAgilityGoalType());
                    st.setSkillingGoalType(goal != null ? goal : SkillGoalType.LEVEL);
                    st.setSkillingGoalValue(st.getAgilityGoalValue());
                    WorldPoint loc =
                        AgilityCoursePresets.startLocation(st.getAgilityCourse());
                    if (loc != null && st.getWorldPoint() == null) st.setWorldPoint(loc);
                    if (st.getName() == null || st.getName().isEmpty()) {
                        st.setName("Agility: " + st.getAgilityCourse());
                    }
                }
            }
        }
    }

    /** The section holding this step, or null. */
    public RouteSection sectionOf(RouteStep step) {
        if (sections == null || step == null) return null;
        for (RouteSection s : sections) {
            if (s.getSteps() != null && s.getSteps().contains(step)) return s;
        }
        return null;
    }

    public RouteSection findSection(String id) {
        if (id == null || sections == null) return null;
        for (RouteSection s : sections) if (id.equals(s.getId())) return s;
        return null;
    }

    public RouteSection ensureLastSection() {
        if (sections == null) sections = new ArrayList<>();
        if (sections.isEmpty()) {
            sections.add(new RouteSection(UUID.randomUUID().toString(), "Section 1"));
        }
        return sections.get(sections.size() - 1);
    }

    public void addStepToSection(RouteStep step, String sectionId) {
        RouteSection sec = findSection(sectionId);
        if (sec == null) sec = ensureLastSection();
        step.setSectionId(sec.getId());
        sec.getSteps().add(step);
    }

    public void addStepToLastSection(RouteStep step) {
        RouteSection sec = ensureLastSection();
        step.setSectionId(sec.getId());
        sec.getSteps().add(step);
    }

    public void removeStep(RouteStep step) {
        if (sections == null) return;
        for (RouteSection sec : sections) {
            if (sec.getSteps() != null && sec.getSteps().remove(step)) return;
        }
    }

    public RouteStep getActiveStep() {
        if (testStep != null) return testStep;
        if (sections == null) return null;
        if (focusSection != null && sections.contains(focusSection)) {
            for (RouteStep s : focusSection.getSteps()) if (!s.isCompleted()) return s;
            return null;
        }
        for (RouteSection sec : sections) {
            if (sec.getSteps() == null) continue;
            for (RouteStep s : sec.getSteps()) if (!s.isCompleted()) return s;
        }
        return null;
    }

    public void resetProgress() {
        getAllSteps().forEach(s -> {
            s.setCompleted(false);
            s.resetProgress();
        });
    }
}

