package com.routeplanner.model;

import lombok.Data;
import net.runelite.api.Skill;
import net.runelite.api.coords.*;
import java.util.Map;

@Data
public class RouteStep {
    private String name;
    private StepType type;
    private WorldPoint worldPoint;
    private int targetId;
    private boolean completed;
    private transient boolean locationReached; // true once player reached worldPoint; nav visuals off (sticky)
    private String sectionId;   // which RouteSection this step belongs to

    // Agility task fields
    private String agilityCourse;
    private String agilityGoalType;
    private long agilityGoalValue;

    // Quest step fields
    private String questName;          // matches net.runelite.api.Quest enum name
    private boolean questComplete;     // true = auto-complete step when quest is FINISHED

    // Item/Bank step fields
    private String itemList;  // comma separated, / for alternatives e.g. "Spade,Rune pouch/Divine Rune pouch"
    private ItemMode itemMode = ItemMode.BANK;  // null (left out of older saves) means BANK
    private transient boolean sellArmed = false;  // SELL / USE_UP: true once the items were seen in the inventory
    private Map<String, Long> pickupBaseline;  // PICKUP/SHOP: carried and worn counts when step became active
    // The account the step's baselines (pickupBaseline, skillingStartXp) were taken on when it became
    // active; 0 = not taken yet. Saved, so reloading keeps the progress; an imported route or another
    // account doesn't match, so those take their own.
    private long baselineAccount;

    /** PICKUP and SHOP count items gained since the step started, not items already carried. */
    public boolean countsGainedItems() {
        return itemMode == ItemMode.PICKUP || itemMode == ItemMode.SHOP;
    }

    // Guided quest (Quest Helper) step fields
    private int questStopIndex = -1;   // flat step index to stop at, -1 = whole quest
    private String questStopText;       // display text of the stop step

    // Teleport step fields
    private String teleportSpell;     // spell name e.g. "Varrock Teleport"
    private WorldPoint teleportDestination; // destination WorldPoint
    private int teleportSpellId;      // widget child ID for highlighting  // matches net.runelite.api.Quest enum name

    private String teleportMethod;    // "SPELL", "ITEM", "NEXUS" or "PORTAL" (null = walk only)
    private String teleportItem;      // item name for ITEM teleports (e.g. "Amulet of glory")
    private String teleportNexus;     // NEXUS: destination as shown in the nexus menu; PORTAL: house portal's destination ("Varrock" for Varrock Portal)

    // Skilling step fields
    private String skillingSkill;      // e.g. "THIEVING"
    private SkillGoalType skillingGoalType;
    private long skillingGoalValue;    // target value
    private long skillingStartXp;      // XP when step became active
    private long skillingProgress;     // current XP gained (for XP_GAIN)
    private String skillingTargetNpc;  // NPC to highlight (e.g. "Knight of Ardougne")
    private String skillingTargetObject; // game object to highlight (e.g. "Baker's stall")
    private String gearReminder; // fishing gear reminder (e.g. "Fly fishing rod, Feathers")
    private String herblorePotion; // potion for Herblore steps (drives the bank highlight)
    private String bankHighlightItems; // generic bank highlight for skilling steps (Cooking, etc.)
    private String inventoryHighlightItems; // items to outline in the inventory, e.g. "Cocktail shaker, Lemon"

    // Area (optional): two opposite corner tiles on one floor, in any order. Arriving anywhere inside
    // counts, instead of only the few tiles around worldPoint (e.g. the grounds Hans walks around).
    private WorldPoint areaFrom;
    private WorldPoint areaTo;
    // A painted area's exact tiles (TileArea.encode). areaFrom/areaTo then hold its bounding box,
    // which is what older versions of the plugin read.
    private String areaTiles;
    // Highlights (NPCs, objects, ground items) only inside the area, not everywhere in range
    private boolean highlightInAreaOnly;
    private transient TileArea areaCache;
    private transient String areaCacheKey;

    public boolean hasArea() {
        return areaFrom != null && areaTo != null;
    }

    /** The area: its painted tiles, else the rectangle on areaFrom's floor; null when there's none. */
    public TileArea area() {
        if (!hasArea()) return null;
        String key = areaTiles != null ? areaTiles : areaFrom + "/" + areaTo;
        if (key.equals(areaCacheKey)) return areaCache;
        TileArea a = areaTiles != null ? TileArea.decode(areaTiles) : null;
        if (a == null) {
            int x = Math.min(areaFrom.getX(), areaTo.getX()), y = Math.min(areaFrom.getY(), areaTo.getY());
            a = TileArea.of(new WorldArea(x, y, Math.abs(areaFrom.getX() - areaTo.getX()) + 1,
                Math.abs(areaFrom.getY() - areaTo.getY()) + 1, areaFrom.getPlane()));
        }
        areaCache = a;
        areaCacheKey = key;
        return a;
    }

    /** Set the area (null clears it). A rectangle is kept as just its corners. */
    public void setArea(TileArea a) {
        if (a == null) {
            areaFrom = null;
            areaTo = null;
            areaTiles = null;
            return;
        }
        WorldArea b = a.bounds();
        areaFrom = new WorldPoint(b.getX(), b.getY(), b.getPlane());
        areaTo = new WorldPoint(b.getX() + b.getWidth() - 1, b.getY() + b.getHeight() - 1, b.getPlane());
        areaTiles = a.isRectangle() ? null : a.encode();
    }

    // Transition point: when set, the step first paths to transitionPoint (the staircase/ladder
    // tile), then, once the player is on worldPoint's floor, on to worldPoint.
    private WorldPoint transitionPoint;
    private int transitionObjectId = -1; // game object ID to highlight as the transition object (-1 = none)

    // Boarding point (Sailing): when set, the step starts by getting on a boat: path to boardPoint
    // (the dock by the gangplank) and highlight the gangplank, then once aboard, sail to worldPoint.
    // With no worldPoint, boarding is the step.
    private WorldPoint boardPoint;
    private int boardObjectId = -1;      // the gangplank's object ID, if known (-1 = find it by name)
    private transient boolean boarded;   // true once the player got on a boat during this step

    // Catch goal (Sailing trawling): fish caught into the net, counted from the catch messages
    // since they never reach the inventory. Progress is saved so a reload carries on.
    private String catchFish;       // e.g. "Giant krill"
    private int catchGoal;          // how many to catch (0 = none)
    private int catchProgress;      // caught so far while this step is active

    public boolean hasCatchGoal() {
        return catchGoal > 0 && catchFish != null;
    }

    public boolean hasBoarding() {
        return boardPoint != null;
    }

    // Farming patch: the patch's own object id (the same whatever grows in it), so a step works for
    // any seed. With farmReplant the step is done once something is planted in it; without, once it
    // gave Farming XP and has nothing left to pick, harvest or check (a bush, a tree).
    // -1 = the patch nearest the step's tile, looked up (and kept) the first time it's in view.
    private int farmPatchId;
    private boolean farmReplant;
    private transient boolean farmDone;

    public boolean hasFarmPatch() {
        return farmPatchId != 0;
    }

    /** The patch is still to be looked up from the step's tile. */
    public boolean farmPatchUnresolved() {
        return farmPatchId < 0;
    }

    // Game progress: a quest stage or diary task the game records, e.g. "varbit 3185 >= 4" or
    // "varp 1194 bit 6" (see ProgressCheck). Once the game shows it, the step is done whatever
    // else it asks for, so steps already done before (or done another way) tick themselves off.
    private String progressCheck;
    private transient String parsedCheckText;
    private transient ProgressCheck parsedCheck;

    /** The step's game progress check, or null when it has none (or it can't be read). */
    public ProgressCheck progress() {
        if (progressCheck == null) return null;
        if (!progressCheck.equals(parsedCheckText)) {
            parsedCheck = ProgressCheck.parse(progressCheck);
            parsedCheckText = progressCheck;
        }
        return parsedCheck;
    }

    // Note step (informational, not tracked)
    private String noteText;
    private boolean noteAutoComplete; // NOTE step: done on arrival, no manual tick (off = wait for the tick)
    private String npcHighlight; // NOTE step: optional NPC name to highlight
    private boolean highlightEnabled; // master toggle: light up this step's in-game targets (default off)
    private String recipeLabel; // editor: the exact recipe/method dropdown label chosen (for reverse-prefill)
    private int npcKillCount;    // NOTE step: kills to auto-complete (0 = manual)
    private int npcKillProgress;           // kills so far while this step is active; saved so a reload carries on
    private String dialogOptions;          // NOTE step: chat option sequence to highlight, e.g. "3,1""

    public RouteStep(String name, StepType type, WorldPoint worldPoint, int targetId) {
        this.name = name;
        this.type = type;
        this.worldPoint = worldPoint;
        this.targetId = targetId;
        this.completed = false;
    }

    // Constructor for skilling steps
    public RouteStep(String name, String skill, SkillGoalType goalType, long goalValue, long startXp) {
        this.name = name;
        this.type = StepType.SKILLING;
        this.worldPoint = null;
        this.targetId = -1;
        this.completed = false;
        this.skillingSkill = skill;
        this.skillingGoalType = goalType;
        this.skillingGoalValue = goalValue;
        this.skillingStartXp = startXp;
        this.skillingProgress = 0;
    }

    /**
     * Clear the progress made on this step (not its completed tick), so it starts fresh: location
     * nav re-arms, SELL re-arms, and the item/XP baselines are taken again.
     */
    public void resetProgress() {
        locationReached = false;
        boarded = false;
        sellArmed = false;
        pickupBaseline = null;
        baselineAccount = 0;
        catchProgress = 0;
        npcKillProgress = 0;
        skillingProgress = 0;
        farmDone = false;
        if (skillingGoalType == SkillGoalType.XP_GAIN) skillingStartXp = 0; // re-captured on the next StatChanged
    }

    /** Steps are told apart by identity: two steps with the same contents are still two steps. */
    @Override
    public boolean equals(Object o) {
        return this == o;
    }

    @Override
    public int hashCode() {
        return System.identityHashCode(this);
    }

    public boolean hasItems() {
        return (itemList != null && !itemList.trim().isEmpty())
            || itemMode == ItemMode.DEPOSIT_ALL;
    }

    /** The skill goal's skill, or null when there's none or the saved name isn't a skill. */
    public Skill skill() {
        if (!hasSkillGoal()) return null;
        try {
            return Skill.valueOf(skillingSkill.trim().toUpperCase());
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    public boolean hasSkillGoal() {
        return skillingSkill != null && !skillingSkill.trim().isEmpty();
    }

    /** Anything the highlight toggle lights up: NPCs, objects, and bank/inventory items. */
    public boolean hasHighlight() {
        return farmPatchId != 0 || notBlank(skillingTargetNpc) || notBlank(skillingTargetObject) || notBlank(npcHighlight)
            || notBlank(bankHighlightItems) || notBlank(herblorePotion) || notBlank(inventoryHighlightItems);
    }

    private static boolean notBlank(String s) {
        return s != null && !s.trim().isEmpty();
    }

    public boolean hasQuest() {
        return questName != null && !questName.trim().isEmpty();
    }

    /**
     * Leprechaun-noting and herb-cleaning steps recorded before "use up" existed were saved as
     * plain item steps, so they completed as soon as the items were carried. Turn them into
     * use-up steps.
     */
    public void migrateUseUp() {
        if (itemMode != null && itemMode != ItemMode.BANK) return;
        if (itemList == null || itemList.trim().isEmpty() || name == null) return;
        boolean noting = "Tool Leprechaun".equalsIgnoreCase(npcHighlight) && name.startsWith("Note ");
        boolean cleaning = name.startsWith("Clean the grimy herbs") && itemList.trim().equalsIgnoreCase("Grimy *");
        if (noting || cleaning) itemMode = ItemMode.USE_UP;
    }

    /** "Harvest and replant the herb patch at ...", "Tend the bush patch": what older recordings named patch steps. */
    private static final java.util.regex.Pattern OLD_PATCH_STEP =
        java.util.regex.Pattern.compile("^(Harvest and replant|Tend) the .*patch\\b.*");

    /**
     * Patch steps recorded before patches were saved on the step carry only their tile, so they
     * completed on arrival. Mark their patch as unresolved: it's looked up near the tile once in
     * view, and the step then waits for the patch to be worked.
     */
    public void migrateFarmPatch() {
        if (farmPatchId != 0 || worldPoint == null || name == null) return;
        if (!OLD_PATCH_STEP.matcher(name).matches()) return;
        farmPatchId = -1;
        if (name.startsWith("Harvest and replant")) farmReplant = true;
    }

    public boolean hasNote() {
        return noteText != null && !noteText.trim().isEmpty();
    }
}

package com.routeplanner.model;

/** What a skill goal's value means. Saved by name, so these names must never change. */
public enum SkillGoalType {
    /** XP gained since the step started. */
    XP_GAIN,
    /** A total XP to reach. */
    XP_TARGET,
    /** A real (unboosted) level to reach. */
    LEVEL;

    /** The type with this name, or null when it isn't one (e.g. a blank legacy agility goal). */
    public static SkillGoalType parse(String name) {
        if (name == null) return null;
        try {
            return valueOf(name.trim().toUpperCase());
        } catch (IllegalArgumentException e) {
            return null;
        }
    }
}

package com.routeplanner.model;

public enum StepType {
    LOCATION,
    ITEM,
    SKILLING,
    TELEPORT,
    NOTE
}

package com.routeplanner.model;

import net.runelite.api.coords.*;
import java.util.*;

/**
 * A step's area: any set of tiles on one floor, a plain rectangle or a painted room shape.
 * Stored as the rectangles that make it up ("plane|x,y,w,h;x,y,w,h"), which keeps big areas short.
 */
public final class TileArea {

    private final int plane;
    private final Set<Long> tiles;
    private final List<int[]> rects;      // x, y, w, h: the tiles as rectangles, for drawing fills
    private final List<int[]> edges;      // x0, y0, x1, y1 in tile-corner coordinates: the outline
    private final int minX, minY, maxX, maxY;

    private TileArea(int plane, Set<Long> tiles) {
        this.plane = plane;
        this.tiles = Collections.unmodifiableSet(tiles);
        int x0 = Integer.MAX_VALUE, y0 = Integer.MAX_VALUE, x1 = Integer.MIN_VALUE, y1 = Integer.MIN_VALUE;
        for (long t : tiles) {
            int x = x(t), y = y(t);
            x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y);
        }
        minX = x0; minY = y0; maxX = x1; maxY = y1;
        rects = toRects(tiles);
        edges = toEdges(tiles);
    }

    /** The tiles given (world x, y), on {@code plane}; null when there are none. */
    public static TileArea of(int plane, Collection<WorldPoint> points) {
        Set<Long> set = new HashSet<>();
        for (WorldPoint p : points) if (p.getPlane() == plane) set.add(key(p.getX(), p.getY()));
        return set.isEmpty() ? null : new TileArea(plane, set);
    }

    public static TileArea of(WorldArea r) {
        Set<Long> set = new HashSet<>();
        for (int x = r.getX(); x < r.getX() + r.getWidth(); x++)
            for (int y = r.getY(); y < r.getY() + r.getHeight(); y++) set.add(key(x, y));
        return new TileArea(r.getPlane(), set);
    }

    /** Reads {@link #encode()}'s text; null when blank or unreadable. */
    public static TileArea decode(String s) {
        if (s == null || s.isEmpty()) return null;
        try {
            int bar = s.indexOf('|');
            int plane = Integer.parseInt(s.substring(0, bar));
            Set<Long> set = new HashSet<>();
            for (String r : s.substring(bar + 1).split(";")) {
                if (r.isEmpty()) continue;
                String[] p = r.split(",");
                int x = Integer.parseInt(p[0]), y = Integer.parseInt(p[1]);
                int w = Integer.parseInt(p[2]), h = Integer.parseInt(p[3]);
                for (int i = 0; i < w; i++) for (int j = 0; j < h; j++) set.add(key(x + i, y + j));
            }
            return set.isEmpty() ? null : new TileArea(plane, set);
        } catch (RuntimeException e) {
            return null;
        }
    }

    public String encode() {
        StringBuilder sb = new StringBuilder().append(plane).append('|');
        for (int[] r : rects) {
            if (sb.charAt(sb.length() - 1) != '|') sb.append(';');
            sb.append(r[0]).append(',').append(r[1]).append(',').append(r[2]).append(',').append(r[3]);
        }
        return sb.toString();
    }

    public int getPlane() { return plane; }
    public int size() { return tiles.size(); }

    public boolean contains(WorldPoint p) {
        return p != null && p.getPlane() == plane && tiles.contains(key(p.getX(), p.getY()));
    }

    public boolean contains(int x, int y) {
        return tiles.contains(key(x, y));
    }

    /** The box around every tile. */
    public WorldArea bounds() {
        return new WorldArea(minX, minY, maxX - minX + 1, maxY - minY + 1, plane);
    }

    /** True when the tiles fill their box exactly (a plain rectangle). */
    public boolean isRectangle() {
        return tiles.size() == (maxX - minX + 1) * (maxY - minY + 1);
    }

    /** The area's tile nearest the middle of its box (a room shaped like an L may not cover its middle). */
    public WorldPoint centre() {
        int cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
        long best = 0;
        int bestDist = Integer.MAX_VALUE;
        for (long t : tiles) {
            int d = Math.abs(x(t) - cx) + Math.abs(y(t) - cy);
            if (d < bestDist || (d == bestDist && t < best)) { bestDist = d; best = t; }
        }
        return new WorldPoint(x(best), y(best), plane);
    }

    /** Every tile, as world points. */
    public List<WorldPoint> points() {
        List<WorldPoint> out = new ArrayList<>(tiles.size());
        for (long t : tiles) out.add(new WorldPoint(x(t), y(t), plane));
        return out;
    }

    /** The tiles as rectangles (x, y, w, h); together they cover the area exactly once. */
    public List<int[]> rects() { return rects; }

    /** The outline as straight segments between tile corners (x0, y0, x1, y1), holes included. */
    public List<int[]> edges() { return edges; }

    // ------------------------------------------------------------------ helpers

    private static long key(int x, int y) { return ((long) x << 32) | (y & 0xffffffffL); }
    private static int x(long key) { return (int) (key >> 32); }
    private static int y(long key) { return (int) key; }

    /** Runs of tiles along each row, then runs with the same span on following rows stacked into one. */
    private static List<int[]> toRects(Set<Long> tiles) {
        TreeMap<Integer, TreeSet<Integer>> rows = new TreeMap<>();
        for (long t : tiles) rows.computeIfAbsent(y(t), k -> new TreeSet<>()).add(x(t));
        List<int[]> done = new ArrayList<>();
        List<int[]> open = new ArrayList<>();   // rects still growing upward, keyed by their span
        Integer prevY = null;
        for (int y : rows.keySet()) {
            List<int[]> spans = new ArrayList<>();
            Integer start = null, last = null;
            for (int x : rows.get(y)) {
                if (start != null && x == last + 1) { last = x; continue; }
                if (start != null) spans.add(new int[]{start, last});
                start = x; last = x;
            }
            spans.add(new int[]{start, last});

            List<int[]> next = new ArrayList<>();
            boolean adjacent = prevY != null && y == prevY + 1;
            for (int[] s : spans) {
                int[] grown = null;
                if (adjacent) {
                    for (int[] r : open) {
                        if (r[0] == s[0] && r[2] == s[1] - s[0] + 1) { grown = r; break; }
                    }
                }
                if (grown != null) { open.remove(grown); grown[3]++; next.add(grown); }
                else next.add(new int[]{s[0], y, s[1] - s[0] + 1, 1});
            }
            done.addAll(open);
            open = next;
            prevY = y;
        }
        done.addAll(open);
        return Collections.unmodifiableList(done);
    }

    /** Tile sides with no area tile across them, joined into straight runs. */
    private static List<int[]> toEdges(Set<Long> tiles) {
        // Horizontal sides by the y of their line, vertical sides by the x of theirs
        TreeMap<Integer, TreeSet<Integer>> hBelow = new TreeMap<>(), hAbove = new TreeMap<>();
        TreeMap<Integer, TreeSet<Integer>> vLeft = new TreeMap<>(), vRight = new TreeMap<>();
        for (long t : tiles) {
            int x = x(t), y = y(t);
            if (!tiles.contains(key(x, y - 1))) hBelow.computeIfAbsent(y, k -> new TreeSet<>()).add(x);
            if (!tiles.contains(key(x, y + 1))) hAbove.computeIfAbsent(y + 1, k -> new TreeSet<>()).add(x);
            if (!tiles.contains(key(x - 1, y))) vLeft.computeIfAbsent(x, k -> new TreeSet<>()).add(y);
            if (!tiles.contains(key(x + 1, y))) vRight.computeIfAbsent(x + 1, k -> new TreeSet<>()).add(y);
        }
        List<int[]> out = new ArrayList<>();
        runs(hBelow, out, true);
        runs(hAbove, out, true);
        runs(vLeft, out, false);
        runs(vRight, out, false);
        return Collections.unmodifiableList(out);
    }

    private static void runs(TreeMap<Integer, TreeSet<Integer>> lines, List<int[]> out, boolean horizontal) {
        for (int line : lines.keySet()) {
            Integer start = null, last = null;
            for (int v : lines.get(line)) {
                if (start != null && v == last + 1) { last = v; continue; }
                if (start != null) out.add(segment(line, start, last + 1, horizontal));
                start = v; last = v;
            }
            out.add(segment(line, start, last + 1, horizontal));
        }
    }

    private static int[] segment(int line, int from, int to, boolean horizontal) {
        return horizontal ? new int[]{from, line, to, line} : new int[]{line, from, line, to};
    }
}

package com.routeplanner.quest;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.util.Text;
import javax.inject.*;
import java.awt.*;

/**
 * On a step that completes with a whole quest, highlights that quest in the open quest list,
 * where Quest Helper's right-click "Start Quest Helper" loads it. Quest Helper takes no messages
 * from other plugins, so pointing at its menu option is as far as this can go.
 * Highlight only: never clicks.
 */
@Singleton
public class QuestListOverlay extends Overlay {
    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public QuestListOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasQuest() || !step.isQuestComplete()) return null;
        String quest = questName(step.getQuestName());
        if (quest == null) return null;

        Widget target = questRow(quest);
        if (target == null) return null;
        Rectangle b = target.getBounds();
        if (b == null) return null;

        Color outline = plugin.getConfig().npcHighlightColor();
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        graphics.setColor(HighlightColors.fill(outline));
        graphics.fillRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        return null;
    }

    /** The quest's name as the quest list shows it, from its Quest enum name. */
    private static String questName(String enumName) {
        try {
            return Quest.valueOf(enumName).getName();
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    /** The quest's row in the open quest list, the scrollbar if it's scrolled out of view, or null. */
    private Widget questRow(String quest) {
        Widget list = visible(InterfaceID.Questlist.LIST);
        Widget view = visible(InterfaceID.Questlist.LIST_CONTAINER);
        if (list == null || view == null) return null;
        Widget[] rows = list.getDynamicChildren();
        if (rows == null) return null;
        for (Widget row : rows) {
            if (row == null || row.isHidden() || row.getText() == null) continue;
            if (!Text.removeTags(row.getText()).trim().equalsIgnoreCase(quest)) continue;
            Rectangle r = row.getBounds();
            if (view.getBounds().contains(r.getCenterX(), r.getCenterY())) return row;
            return visible(InterfaceID.Questlist.SCROLLBAR);
        }
        return null;
    }

    private Widget visible(int componentId) {
        Widget w = client.getWidget(componentId);
        return w == null || w.isHidden() ? null : w;
    }
}

package com.routeplanner.record;

import com.routeplanner.model.*;
import com.routeplanner.agility.*;
import com.routeplanner.util.*;
import net.runelite.api.*;
import com.routeplanner.farming.FarmingTracker;
import net.runelite.api.coords.WorldPoint;
import java.util.*;

/**
 * The skilling and combat half of Record mode: turns XP drops and kills into steps.
 *
 *  - Gathering (woodcutting, mining, fishing, hunter): the items you got become a PICKUP-style
 *    item count ("28 Yew logs"), with the tree / rock / fishing spot as the highlight target.
 *  - Agility: XP on a known course becomes an XP goal on that course, started at its start tile.
 *  - Any other skill: the XP gained becomes an "Gain XP amount" goal, with the NPC or object
 *    you were using (a pickpocket NPC, a stall, a range) as the highlight target.
 *  - Kills: NPCs you were fighting that die become a kill-count step highlighting that NPC.
 *  - Farming patches: XP from a patch becomes a step on the patch itself (any seed will do),
 *    done once it's replanted, or for a bush or tree once it has nothing left to pick or check.
 *  - Cleaning herbs: done once no grimy herbs are left; noting them at the Tool Leprechaun: done
 *    once none are left unnoted. Neither depends on the herb or how many there were.
 *
 * Repeating the same thing in the same spot adds to one step rather than making many. Like the
 * rest of the recorder it only reads game state; it never acts for the player.
 */
class ActivityRecorder {

    /** Same activity if the next XP / kill comes within this many tiles of where it started. */
    private static final int ACTIVITY_RADIUS = 15;
    /** While XP keeps coming this recently, the player is busy here: no idle location steps. */
    private static final int BUSY_TICKS = 30;
    /** A clicked NPC / object explains XP that arrives within this many ticks. */
    private static final int TARGET_WINDOW_TICKS = 30;
    /** Teleport spells give Magic XP; ignore Magic this soon after a teleport click. */
    private static final int TELEPORT_XP_TICKS = 10;

    private static final Set<Skill> GATHERING = EnumSet.of(
        Skill.WOODCUTTING, Skill.MINING, Skill.FISHING, Skill.HUNTER);
    /** Combat XP is recorded as kills instead. */
    private static final Set<Skill> COMBAT = EnumSet.of(
        Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.HITPOINTS, Skill.SLAYER);

    private final Client client;
    private final RouteRecorder host;

    private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);

    /** The NPC or object the player last used. */
    private String targetName;
    private String targetOption;
    private boolean targetIsNpc;
    private int targetObjectId = -1;
    private WorldPoint targetPos;   // where the player stood when they clicked it
    private WorldPoint targetObjectTile; // the clicked object's own tile, when it was an object
    private int targetTick = -1000;
    /** "Use Torstol seed -> Herb patch": the item used, "Torstol seed". */
    private String targetUsed;
    private int cleanTick = -1000;

    /** The latest farming patch step, its patch, and the latest clean / leprechaun step. */
    private RouteStep farmStep;
    private int farmStepPatch = -1;
    private RouteStep cleanStep;
    private RouteStep leprechaunStep;
    /** Patch work, cleaning and noting keep the player busy where they are, like XP does. */
    private int choreTick = -1000;
    private WorldPoint chorePos;
    private int teleportTick = -1000;
    private int combatTick = -1000;

    /** The step being added to, and what it's for. */
    private RouteStep step;
    private Skill skill;            // null for a kill step
    private String stepTarget;      // what it highlights (NPC / object / course name)
    private WorldPoint stepPos;
    private long stepXp;
    private int lastXpTick = -1000;
    private int stepBeganTick = -1000;
    /** XP added to the current step in the last few ticks, so a quest reward can be taken back out. */
    private long recentXp;
    private int recentXpTick = -1000;
    private int ignoreXpUntil = -1000;
    private final Map<String, Long> gathered = new LinkedHashMap<>();
    /** Items gained this tick before the XP drop that explains them arrived. */
    private final Map<String, Long> pendingGains = new LinkedHashMap<>();
    private int pendingTick = -1;
    /** Salvaging, sorting and trawling (Sailing), which run as sessions. */
    private final SailingActivity sailing;

    ActivityRecorder(Client client, RouteRecorder host) {
        this.client = client;
        this.host = host;
        this.sailing = new SailingActivity(client, host);
    }

    void start() {
        xp.clear();
        for (Skill s : Skill.values()) {
            if (s == Skill.OVERALL) continue;
            xp.put(s, client.getSkillExperience(s));
        }
        targetName = null;
        targetTick = teleportTick = combatTick = lastXpTick = cleanTick = choreTick = -1000;
        farmStep = cleanStep = leprechaunStep = null;
        farmStepPatch = -1;
        step = null;
        gathered.clear();
        pendingGains.clear();
        sailing.start();
    }

    /** An NPC or object was clicked (not walking or examining). */
    void onTargetClick(String option, String target, boolean npc, int objectId, WorldPoint at, WorldPoint objectTile, int tick) {
        targetPos = at;
        targetObjectTile = objectTile;
        targetObjectId = npc ? -1 : objectId;
        targetName = cleanName(target);
        targetUsed = FarmingTracker.usedItem(target);
        targetOption = option;
        targetIsNpc = npc;
        targetTick = tick;
        // A ship's cannon fights too: its hits give Sailing XP the way an attack gives Ranged
        if ("Attack".equalsIgnoreCase(option)
            || ("Operate".equalsIgnoreCase(option) && target != null && target.toLowerCase().contains("cannon"))) {
            combatTick = tick;
        }
        sailing.onTargetClick(option, target, at, tick);
    }

    /** Fish caught by a trawling net: they make the trawl's catch step (see SailingActivity). */
    void onCatch(String fish, int count, WorldPoint pos, int tick) {
        if (sailing.onCatch(fish, count, pos, tick)) step = null; // a catch step isn't an XP activity
    }

    /** "Lower net" in the Sailing panel: trawling is on. */
    void onLowerNet(int tick) {
        sailing.onLowerNet(tick);
    }

    /** "Clean" on a grimy herb. */
    void onCleanClick(int tick) {
        cleanTick = tick;
    }

    /** An item was used on the Tool Leprechaun, which notes it. */
    void onNoteAtLeprechaun(String item, WorldPoint pos, int tick) {
        if (item == null) return;
        String entry = Herbs.isHerb(item) ? Herbs.ANY_HERB : item;
        if (leprechaunStep == null || host.lastDraft() != leprechaunStep || !host.isNear(leprechaunStep, pos, ACTIVITY_RADIUS)) {
            leprechaunStep = host.stepAt(pos, "Note items with the Tool Leprechaun" + LocationNames.at(pos));
            leprechaunStep.setItemMode(ItemMode.USE_UP);
            leprechaunStep.setNpcHighlight("Tool Leprechaun");
            leprechaunStep.setHighlightEnabled(true);
            step = null;
        }
        List<String> items = new ArrayList<>();
        if (leprechaunStep.getItemList() != null) items.addAll(Arrays.asList(leprechaunStep.getItemList().split(",\\s*")));
        if (!items.contains(entry)) items.add(entry);
        String list = String.join(", ", items);
        leprechaunStep.setItemList(list);
        leprechaunStep.setInventoryHighlightItems(list);
        leprechaunStep.setName((items.size() == 1 && Herbs.ANY_HERB.equals(entry) ? "Note the herbs" : "Note " + list)
            + " with the Tool Leprechaun" + LocationNames.at(pos));
        chore(pos, tick);
        host.trace("LEPRECHAUN noted " + item + " -> " + RouteRecorder.describeStep(leprechaunStep));
    }

    private void chore(WorldPoint pos, int tick) {
        choreTick = tick;
        chorePos = pos;
    }

    void onTeleportClick(int tick) {
        teleportTick = tick;
    }

    /** True while the player is busy with an activity here, so standing still isn't a new stop. */
    boolean isBusy(WorldPoint pos, int tick) {
        // Mid-fight: standing (or stopping the boat) between kills isn't a stop either; nor is
        // waiting for a shoal mid-trawl
        if (tick - combatTick <= BUSY_TICKS) return true;
        if (tick - choreTick <= BUSY_TICKS && (pos == null || chorePos == null || pos.distanceTo2D(chorePos) <= ACTIVITY_RADIUS)) return true;
        if (sailing.isBusy(tick)) return true;
        if (step == null || host.lastDraft() != step || tick - lastXpTick > BUSY_TICKS) return false;
        if (skill == Skill.AGILITY) return true; // a lap ranges all over (and up) the course
        return pos == null || stepPos == null || pos.distanceTo2D(stepPos) <= ACTIVITY_RADIUS;
    }

    /**
     * The course an obstacle belongs to, by its object id (courses can span several map
     * regions, so the id is the reliable part), falling back to the region the player is in.
     */
    private static AgilityCourse courseFor(int objectId, WorldPoint pos) {
        if (objectId > 0) {
            for (AgilityCourse c : AgilityCoursePresets.ALL) {
                for (AgilityObstacle o : c.getObstacles()) if (o.matchesId(objectId)) return c;
            }
        }
        return pos == null ? null : AgilityCoursePresets.getCourseForRegion(pos.getRegionID());
    }

    /** Running a course right now: agility XP came recently. */
    boolean runningCourse(WorldPoint pos, int tick) {
        return skill == Skill.AGILITY && step != null && host.lastDraft() == step && tick - lastXpTick <= BUSY_TICKS;
    }

    /** True when the player is running a known agility course (its jumps and climbs aren't travel). */
    boolean onAgilityCourse(WorldPoint pos, int clickedObjectId, int tick) {
        // Mid-lap any obstacle counts, even one the course table doesn't list by id.
        if (runningCourse(pos, tick)) return true;
        for (AgilityCourse c : AgilityCoursePresets.ALL) {
            for (AgilityObstacle o : c.getObstacles()) if (o.matchesId(clickedObjectId)) return true;
        }
        return false;
    }

    /** XP that belongs to something else (a shortcut): only keeps the count current. */
    void noteXp(Skill s, int newXp) {
        xp.put(s, newXp);
    }

    void onXp(Skill s, int newXp, WorldPoint pos, int tick) {
        Integer old = xp.put(s, newXp);
        if (old == null || old <= 0 || newXp <= old) return;
        long gained = newXp - old;
        if (tick <= ignoreXpUntil) { host.trace("XP+" + gained + " " + s + " ignored (quest reward)"); return; }
        if (COMBAT.contains(s)) { host.trace("XP+" + gained + " " + s + " ignored (combat)"); return; }
        if (s == Skill.MAGIC && (tick - teleportTick <= TELEPORT_XP_TICKS || tick - combatTick <= TARGET_WINDOW_TICKS)) {
            host.trace("XP+" + gained + " MAGIC ignored (teleport/combat)");
            return;
        }
        if (s == Skill.FARMING && onFarmingXp(pos, tick)) return;
        if (s == Skill.HERBLORE && tick - cleanTick <= TARGET_WINDOW_TICKS) {
            onCleaningXp(pos, tick);
            return;
        }
        // Trawling: its XP (the net's Sailing, the catches' Fishing) belongs to it; the catches make the
        // step (see onCatch), since the fish are the point and a crewmate's catches give no Fishing XP
        if (sailing.absorbTrawlXp(s, tick)) return;
        // Fighting at sea: the kills make the step ("Kill 3 Vampyre kraken"), like any combat XP
        if (s == Skill.SAILING && tick - combatTick <= TARGET_WINDOW_TICKS) {
            host.trace("XP+" + gained + " SAILING ignored (sea combat, recorded as kills)");
            return;
        }
        // Salvaging or sorting: a session; otherwise Sailing XP only counts after clicking a wreck
        String session = s == Skill.SAILING ? sailing.session(pos, tick) : null;
        boolean anywhere = sailing.anywhere(session);
        if (s == Skill.SAILING && session == null
                && (tick - targetTick > TARGET_WINDOW_TICKS || !SailingActivity.trainingClick(targetOption, targetName))) {
            host.trace("XP+" + gained + " SAILING ignored (travel or boat facility, last target=" + targetOption + " " + targetName + ")");
            return;
        }

        String target = session != null ? session : tick - targetTick <= TARGET_WINDOW_TICKS ? targetName : null;
        AgilityCourse course = s == Skill.AGILITY
            ? courseFor(tick - targetTick <= TARGET_WINDOW_TICKS ? targetObjectId : -1, pos) : null;
        if (course != null) target = course.getName();

        // A lap that began on an obstacle the course list doesn't know: once a later obstacle
        // names the course, the step takes it on instead of splitting the lap.
        if (course != null && s == Skill.AGILITY && skill == s && step != null && host.lastDraft() == step
            && stepTarget == null && tick - lastXpTick <= BUSY_TICKS) {
            stepTarget = course.getName();
            step.setRecipeLabel(course.getName());
        }
        // Back to this wreck's Salvage or Sort step after the other one (or a chat) came in between
        RouteStep resume = sailing.sessionStep(session);
        boolean resumed = false;
        if (resume != null && resume != step) {
            step = resume;
            skill = s;
            stepTarget = target;
            stepPos = resume.getWorldPoint();
            stepXp = sailing.xp(resume);
            gathered.clear();
            resumed = true;
        }
        boolean same = resumed || step != null && host.lastDraft() == step && skill == s
            && (course != null ? course.getName().equals(stepTarget)
                // A course the plugin doesn't know: every obstacle has its own name, so keep
                // the lap together while the XP keeps coming instead of matching the target.
                : s == Skill.AGILITY ? stepTarget == null && tick - lastXpTick <= BUSY_TICKS
                : (anywhere || near(pos)) && (target == null || target.equals(stepTarget)));
        if (s == Skill.AGILITY && course == null) target = null;
        host.trace("XP+" + gained + " " + s + " target=" + target + " course=" + (course == null ? null : course.getName())
            + " -> " + (same ? "add to current step" : "new activity (current=" + RouteRecorder.describeStep(step)
            + ", lastDraftIsCurrent=" + (step != null && host.lastDraft() == step) + ")"));
        if (!same) {
            begin(s, target, course, anywhere ? null : pos);
            sailing.began(session, step);
        }
        stepXp += gained;
        sailing.recordXp(step, stepXp);
        if (tick - recentXpTick > 2) recentXp = 0;
        recentXp += gained;
        recentXpTick = tick;
        lastXpTick = tick;
        if (GATHERING.contains(s) && pendingTick >= tick - 1) {
            pendingGains.forEach((k, v) -> gathered.merge(k, v, Long::sum));
        }
        pendingGains.clear();
        refresh(pos);
    }

    /**
     * Farming XP from a patch (anything whose look changes with what grows in it): a step on the
     * patch, the same for any seed. False when it isn't from a patch.
     */
    private boolean onFarmingXp(WorldPoint pos, int tick) {
        return onFarmingXp(pos, tick, false);
    }

    private boolean onFarmingXp(WorldPoint pos, int tick, boolean planted) {
        boolean clicked = tick - targetTick <= TARGET_WINDOW_TICKS && !targetIsNpc && targetObjectId > 0;
        int patch;
        if (clicked && isPatch(targetObjectId)) {
            patch = targetObjectId;
        } else if (farmStep != null && host.hasDraft(farmStep) && tick - choreTick <= BUSY_TICKS
                && host.isNear(farmStep, pos, ACTIVITY_RADIUS)) {
            patch = farmStepPatch; // still harvesting from the last click
        } else {
            return false;
        }
        boolean seed = planted && clicked && patch == targetObjectId;
        // The same patch again (after cleaning or noting in between, too) stays one step
        boolean same = farmStep != null && host.hasDraft(farmStep) && farmStepPatch == patch
            && host.isNear(farmStep, pos, ACTIVITY_RADIUS);
        if (!same) {
            farmStep = host.stepAt(pos, "Tend the patch" + LocationNames.at(pos));
            farmStep.setFarmPatchId(patch);
            farmStep.setHighlightEnabled(true);
            farmStepPatch = patch;
        }
        if (seed) farmStep.setFarmReplant(true);
        if (clicked || !same) {
            // Named after the patch, not what grew in it: "herb patch", not "Torstol"
            String what = patchName(patch, clicked ? targetName : null);
            String at = LocationNames.at(farmStep.getWorldPoint());
            farmStep.setName(farmStep.isFarmReplant() ? "Harvest and replant the " + what + at : "Tend the " + what + at);
        }
        step = null; // not an XP activity: no XP goal, so any seed and any yield will do
        chore(pos, tick);
        host.trace("FARMING patch " + patch + (seed ? " planted" : "") + " -> " + RouteRecorder.describeStep(farmStep));
        return true;
    }

    /** "You plant ...": planting gives no XP, so the message marks the patch step as a replant. */
    void onPlantMessage(WorldPoint pos, int tick) {
        onFarmingXp(pos, tick, true);
    }

    /** Herblore XP from cleaning: one step, done once no grimy herbs are left (any herb, any amount). */
    private void onCleaningXp(WorldPoint pos, int tick) {
        if (cleanStep == null || host.lastDraft() != cleanStep || !host.isNear(cleanStep, pos, ACTIVITY_RADIUS)) {
            cleanStep = host.stepAt(pos, "Clean the grimy herbs" + LocationNames.at(pos));
            cleanStep.setItemMode(ItemMode.USE_UP);
            cleanStep.setItemList("Grimy *");
            cleanStep.setInventoryHighlightItems("Grimy *");
            cleanStep.setHighlightEnabled(true);
            host.trace("CLEANING -> " + RouteRecorder.describeStep(cleanStep));
        }
        step = null;
        chore(pos, tick);
    }

    /** Farming patches (and bushes, trees) change look with what grows in them: an object with variants. */
    private boolean isPatch(int objectId) {
        ObjectComposition comp = client.getObjectDefinition(objectId);
        return comp != null && comp.getImpostorIds() != null;
    }

    /** "herb patch": the name its empty form goes by, else the name it was clicked by, lowercased. */
    private String patchName(int objectId, String clickedName) {
        ObjectComposition comp = client.getObjectDefinition(objectId);
        if (comp != null && comp.getImpostorIds() != null) {
            for (int id : comp.getImpostorIds()) {
                ObjectComposition v = id > 0 ? client.getObjectDefinition(id) : null;
                String n = v == null ? null : v.getName();
                String l = n == null ? "" : n.toLowerCase();
                if (l.endsWith("patch") || l.equals("allotment")) return l;
            }
        }
        return clickedName != null ? clickedName.toLowerCase() : "patch";
    }

    /**
     * A quest was just finished: its reward XP isn't training. XP that arrived in the last couple
     * of ticks is taken back off the step (removing the step if that was all it had), and XP
     * for a few ticks more is ignored (reward lamps and the scroll can come slightly later).
     */
    void onQuestComplete(int tick) {
        ignoreXpUntil = tick + 10;
        if (step == null || tick - recentXpTick > 2 || recentXp <= 0) return;
        stepXp -= recentXp;
        recentXp = 0;
        host.trace("QUEST reward XP removed from " + RouteRecorder.describeStep(step));
        if (stepXp <= 0 && tick - stepBeganTick <= 2) {
            host.removeDraft(step);
            step = null;
        } else if (stepXp > 0) {
            refresh(null);
        }
    }

    /** Items arrived in the inventory that weren't picked up, bought or withdrawn. */
    void onItemsGained(Map<String, Long> gains, int tick) {
        if (step != null && GATHERING.contains(skill) && host.lastDraft() == step && tick - lastXpTick <= 2) {
            gains.forEach((k, v) -> gathered.merge(k, v, Long::sum));
            refresh(null);
            return;
        }
        // The XP for these may come later this tick: hold on to them until it does.
        if (pendingTick != tick) pendingGains.clear();
        gains.forEach((k, v) -> pendingGains.merge(k, v, Long::sum));
        pendingTick = tick;
    }

    /** One of the player's kills: it joins the current kill step, or starts one. */
    void onKill(NPC npc, WorldPoint pos) {
        if (npc.getName() == null) return;
        String name = cleanName(npc.getName());
        RouteStep last = host.lastDraft();
        boolean same = last != null && name.equalsIgnoreCase(last.getNpcHighlight()) && last.getNpcKillCount() > 0
            && host.isNear(last, pos, ACTIVITY_RADIUS);
        if (!same) {
            // Loot picked up after a kill sits on the same step, so fighting and looting stay together.
            last = host.stepAt(pos, "Kill " + name + LocationNames.at(pos), ActivityRecorder::canTakeKills);
            last.setNpcHighlight(name);
            last.setNpcKillCount(0);
            step = null; // a kill step isn't an XP activity
        }
        last.setNpcKillCount(last.getNpcKillCount() + 1);
        last.setNoteText("Kill " + last.getNpcKillCount() + " " + name + ".");
    }

    private static boolean canTakeKills(RouteStep s) {
        return s.getItemMode() == ItemMode.PICKUP && !s.hasSkillGoal()
            && s.getSkillingTargetNpc() == null && s.getSkillingTargetObject() == null && !s.hasNote();
    }

    private void begin(Skill s, String target, AgilityCourse course, WorldPoint pos) {
        WorldPoint at = pos;
        if (s == Skill.AGILITY) {
            // Best: the course's first obstacle as actually clicked. Then the course preset.
            WorldPoint startTile = null;
            if (course != null && targetObjectTile != null && !course.getObstacles().isEmpty()
                && course.getObstacles().get(0).matchesId(targetObjectId)) startTile = targetObjectTile;
            if (startTile == null && course != null) startTile = AgilityCoursePresets.startLocation(course.getName());
            // No known start: the lap starts where its first obstacle was clicked (on the ground,
            // not wherever on the rooftops the first XP landed you).
            if (startTile == null && targetPos != null) startTile = targetPos;
            if (startTile != null) at = startTile;
        }
        step = host.stepAt(at, "Train " + cap(s.name()) + LocationNames.at(pos), null);
        skill = s;
        stepTarget = target;
        stepPos = pos;
        stepXp = 0;
        stepBeganTick = host.currentTick();
        gathered.clear();
        if (course != null) {
            step.setRecipeLabel(course.getName());
        } else if (SailingActivity.SALVAGING.equals(target) || SailingActivity.SORTING.equals(target)) {
            sailing.setUp(target, step);
        } else if (target != null) {
            if (targetIsNpc) step.setSkillingTargetNpc(target);
            else step.setSkillingTargetObject(target);
        }
    }

    /** Rewrite the step from what's been recorded so far. */
    private void refresh(WorldPoint pos) {
        WorldPoint where = stepPos != null ? stepPos : pos;
        String verb = targetOption != null && stepTarget != null && stepTarget.equals(targetName)
            ? targetOption : null;
        if (GATHERING.contains(skill) && !gathered.isEmpty()) {
            // Gathering is about what you come away with, so it's an item count.
            List<String> entries = new ArrayList<>();
            gathered.forEach((k, v) -> entries.add(v > 1 ? v + " " + k : k));
            step.setItemMode(ItemMode.PICKUP);
            step.setItemList(String.join(", ", entries));
            step.setSkillingSkill(null);
            step.setSkillingGoalType(null);
            step.setName((verb != null ? verb + " " + stepTarget : "Gather") + LocationNames.at(where));
            return;
        }
        step.setSkillingSkill(skill.name());
        step.setSkillingGoalType(SkillGoalType.XP_GAIN);
        step.setSkillingGoalValue(stepXp);
        step.setSkillingStartXp(0); // captured when the step becomes active during playback
        if (skill == Skill.AGILITY) {
            step.setName(step.getRecipeLabel() != null
                ? "Agility: " + step.getRecipeLabel() + " course" : "Agility" + LocationNames.at(where));
        } else if (sailing.name(stepTarget, step, stepPos, where) != null) {
            step.setName(sailing.name(stepTarget, step, stepPos, where));
        } else if (verb != null) {
            step.setName(verb + " " + stepTarget + LocationNames.at(where));
        } else {
            step.setName("Train " + cap(skill.name()) + LocationNames.at(where));
        }
    }

    private boolean near(WorldPoint pos) {
        if (pos == null || stepPos == null) return pos == null && stepPos == null;
        return pos.distanceTo2D(stepPos) <= ACTIVITY_RADIUS;
    }

    /** "Man  (level-2)" -> "Man". */
    private static String cleanName(String raw) {
        if (raw == null) return null;
        // "Use Raw shrimps -> Range": the thing used on is the target.
        int arrow = raw.lastIndexOf("->");
        if (arrow >= 0) raw = raw.substring(arrow + 2);
        return raw.replaceAll("\\s*\\(level-\\d+\\)", "").trim();
    }

    private static String cap(String s) {
        return s.isEmpty() ? s : s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
    }

}

package com.routeplanner.record;

import lombok.RequiredArgsConstructor;
import com.routeplanner.dialog.DialogOptions;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.LocationNames;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;
import java.util.*;

/**
 * The conversation half of Record mode: dialogue choices and finished quests.
 *
 *  - Talking to an NPC becomes a "Talk to ..." step that highlights them.
 *  - Each option picked in a chat menu is added to that step's dialogue sequence ("2,1,3"),
 *    which playback highlights in turn. A mouse pick is read from the clicked line; a keyboard
 *    pick from the player repeating that line in the next chat box. A pick that can't be read
 *    either way is recorded as 0 (no highlight) so the rest of the sequence stays in step.
 *  - "Congratulations, you've completed a quest" puts that quest on the step, set to complete
 *    when the quest is finished.
 *
 * Like the rest of the recorder it only reads what's on screen; it never answers for the player.
 */
@RequiredArgsConstructor
class DialogRecorder {

    /** A Talk-to click explains a conversation that opens within this many ticks (walking there). */
    private static final int TALK_WINDOW_TICKS = 30;
    /** After a menu closes, the player's echo of their choice shows up within this many ticks. */
    private static final int ECHO_WINDOW_TICKS = 4;
    /** The conversation is over once no chat box has shown for this many ticks. */
    private static final int END_TICKS = 3;
    private static final int[] DIALOGUE_GROUPS = {219, 231, 217, 229, 233, 193};
    private static final String QUEST_DONE = "congratulations, you've completed a quest:";
    private static final String MINIQUEST_DONE = "congratulations, you've completed a miniquest:";

    private final Client client;
    private final RouteRecorder host;

    private String talkNpc;
    private int talkTick = -1000;

    private boolean inConversation;
    /** A crewmate on the boat was just clicked; the chat it opens isn't part of the route. */
    private int crewTick = -1000;
    private boolean muted;
    private int lastOpenTick;
    private RouteStep step;          // the step this conversation's picks go on (made on demand)
    private String convNpc;

    /** The options menu currently (or last) on screen, and whether its pick is known yet. */
    private List<String> menu = new ArrayList<>();
    private boolean menuOpen;
    private boolean picked;
    private int closedTick = -1;

    void start() {
        talkNpc = null;
        talkTick = -1000;
        crewTick = -1000;
        muted = false;
        inConversation = false;
        step = null;
        menu = new ArrayList<>();
        menuOpen = false;
        closedTick = -1;
    }

    /** An NPC was clicked; "Talk-to" means a conversation is coming. */
    /**
     * A crewmate or a facility on the player's boat was clicked: the conversation or menu that follows
     * (chatting to the crew, where to send the net's fish) isn't recorded.
     */
    void onCrewClick(int tick) {
        crewTick = tick;
        talkNpc = null;
    }

    void onNpcClick(String option, String target, int tick) {
        if (!"Talk-to".equalsIgnoreCase(option)) return;
        talkNpc = target.replaceAll("\\s*\\(level-\\d+\\)", "").trim();
        talkTick = tick;
    }

    /** A click inside the options menu: the clicked line is the pick. */
    void onMenuClick(int widgetId, int childIndex, WorldPoint pos) {
        if (widgetId != InterfaceID.Chatmenu.OPTIONS || !menuOpen) return;
        Widget container = DialogOptions.container(client);
        Widget line = container != null && childIndex >= 0 ? container.getChild(childIndex) : null;
        String text = line != null ? DialogOptions.clean(line.getText()) : null;
        int idx = text == null ? -1 : menu.indexOf(text);
        host.trace("DIALOG click child=" + childIndex + " text='" + text + "' -> option " + (idx + 1));
        if (idx >= 0) pick(idx + 1, pos);
    }

    void onTick(WorldPoint pos, int tick) {
        List<String> now = DialogOptions.texts(client);
        boolean open = !now.isEmpty();

        // Picking a line (key or mouse) first swaps it for "Please wait..." in the same menu:
        // that's the pick. Keep the original lines as the menu so the swap isn't a new menu.
        int waiting = open && menuOpen ? waitIndex(menu, now) : -1;
        if (waiting >= 0) {
            if (!picked) {
                host.trace("DIALOG wait on line " + (waiting + 1) + " -> option " + (waiting + 1));
                pick(waiting + 1, pos);
            }
        } else if (open && menuOpen && !now.equals(menu)) {
            // A menu replaced straight by a different one: the old pick can't be read any more.
            resolveUnread(pos);
            menu = now;
            picked = false;
            host.trace("DIALOG menu " + menu);
        } else if (open && !menuOpen) {
            menu = now;
            picked = false;
            host.trace("DIALOG menu " + menu);
        } else if (!open && menuOpen && !picked) {
            closedTick = tick;          // pick still unknown: watch for the echo
        }
        menuOpen = open;

        // Keyboard picks: the player says the chosen line in the next chat box.
        if (!menuOpen && !picked && closedTick >= 0) {
            String said = playerLine();
            int idx = said == null ? -1 : indexOfSaid(said);
            if (idx >= 0) {
                host.trace("DIALOG echo '" + said + "' -> option " + (idx + 1));
                pick(idx + 1, pos);
            } else if (tick - closedTick > ECHO_WINDOW_TICKS) {
                resolveUnread(pos);
            }
        }

        boolean anyOpen = anyDialogueOpen();
        if (anyOpen) {
            if (!inConversation) beginConversation(pos, tick);
            lastOpenTick = tick;
        } else if (inConversation && tick - lastOpenTick > END_TICKS && closedTick < 0) {
            inConversation = false;
            muted = false;
            step = null;
            closedTick = -1;
        }
    }

    /** Game messages: a finished quest goes on the step where it was finished. True if it was one. */
    boolean onGameMessage(String message, WorldPoint pos) {
        String msg = Text.removeTags(message).trim();
        String lower = msg.toLowerCase();
        String name = null;
        if (lower.startsWith(QUEST_DONE)) name = msg.substring(QUEST_DONE.length()).trim();
        else if (lower.startsWith(MINIQUEST_DONE)) name = msg.substring(MINIQUEST_DONE.length()).trim();
        if (name == null) return false;
        Quest quest = questNamed(name);
        host.trace("QUEST done '" + name + "' -> " + quest);
        if (quest == null) return true;
        RouteStep target = step != null ? step : host.lastDraft();
        if (target == null || target.hasQuest() || !host.isNear(target, pos, 15)) {
            target = host.stepAt(pos, "Finish " + quest.getName() + LocationNames.at(pos));
        }
        target.setQuestName(quest.name());
        target.setQuestComplete(true);
        return true;
    }

    private void beginConversation(WorldPoint pos, int tick) {
        inConversation = true;
        step = null;
        if (tick - crewTick <= TALK_WINDOW_TICKS) {
            muted = true;
            host.trace("DIALOG with a crewmate, not recorded");
            return;
        }
        convNpc = tick - talkTick <= TALK_WINDOW_TICKS ? talkNpc : null;
        talkNpc = null;
        if (convNpc != null) {
            step = host.stepAt(pos, "Talk to " + convNpc + LocationNames.at(pos));
            if (step.getSkillingTargetNpc() == null) step.setSkillingTargetNpc(convNpc);
        } else {
            // Reading a book, a puzzle, a lever's "Are you sure?": its picks go on the object's step
            step = host.recentObjectStep(tick);
        }
        host.trace("DIALOG start npc=" + convNpc + " step=" + RouteRecorder.describeStep(step));
    }

    private void pick(int option, WorldPoint pos) {
        picked = true;
        closedTick = -1;
        if (muted) return;
        if (step == null) {
            // Options without a Talk-to first (an object, an item, a cutscene): still a step.
            step = host.stepAt(pos, "Dialogue" + LocationNames.at(pos));
        }
        String seq = step.getDialogOptions();
        step.setDialogOptions(seq == null || seq.trim().isEmpty() ? String.valueOf(option) : seq + "," + option);
        host.trace("DIALOG sequence now " + step.getDialogOptions());
    }

    /** The pick for the last menu couldn't be read: keep the sequence aligned with a blank. */
    private void resolveUnread(WorldPoint pos) {
        if (picked || menu.isEmpty()) { closedTick = -1; return; }
        host.trace("DIALOG pick for " + menu + " not readable, recorded as 0");
        pick(0, pos);
    }

    /** The line swapped for "Please wait..." if {@code now} is {@code before} with just that change, else -1. */
    private static int waitIndex(List<String> before, List<String> now) {
        if (before.size() != now.size()) return -1;
        int found = -1;
        for (int i = 0; i < now.size(); i++) {
            if (now.get(i).equals(before.get(i))) continue;
            if (found >= 0 || !now.get(i).toLowerCase().startsWith("please wait")) return -1;
            found = i;
        }
        return found;
    }

    private int indexOfSaid(String said) {
        String s = normalize(said);
        for (int i = 0; i < menu.size(); i++) {
            String o = normalize(menu.get(i));
            if (!o.isEmpty() && (s.equals(o) || s.startsWith(o) || o.startsWith(s))) return i;
        }
        return -1;
    }

    private static String normalize(String s) {
        return s.toLowerCase().replaceAll("[^a-z0-9 ]", "").replaceAll("\\s+", " ").trim();
    }

    /** What the player is saying in the chat box right now, if anything. */
    private String playerLine() {
        Widget w = client.getWidget(InterfaceID.ChatRight.TEXT);
        if (w == null || w.isHidden()) return null;
        String t = DialogOptions.clean(w.getText());
        return t.isEmpty() ? null : t;
    }

    private boolean anyDialogueOpen() {
        for (int g : DIALOGUE_GROUPS) {
            Widget w = client.getWidget(g, 0);
            if (w != null && !w.isHidden()) return true;
        }
        return false;
    }

    private static Quest questNamed(String name) {
        String n = name.replaceAll("[!.]+$", "").trim();
        for (Quest q : Quest.values()) if (q.getName().equalsIgnoreCase(n)) return q;
        return null;
    }

}

package com.routeplanner.record;

import lombok.RequiredArgsConstructor;
import com.routeplanner.model.*;
import com.routeplanner.bank.BankItemManager;
import com.routeplanner.util.LocationNames;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.*;
import net.runelite.client.game.*;
import java.util.*;
import java.util.regex.*;

/**
 * The item half of Record mode: turns inventory changes into item steps.
 *
 *  - Bank / seed vault: inventory when it opens vs when it closes. Items you end up holding
 *    more of become a BANK step; emptying your inventory becomes a DEPOSIT_ALL step.
 *  - Shop: items gained become a SHOP step, items given away a SELL step (currency ignored).
 *  - Ground items: a "Take" click followed by that item arriving becomes a PICKUP step.
 *
 * Quantities follow how each mode completes: BANK checks your inventory total, so it records
 * what you ended up holding; SHOP and PICKUP check what you gained, so they record that.
 * Read-only like the rest of the recorder: it only looks at the inventory and interfaces.
 */
@RequiredArgsConstructor
class ItemRecorder {

    /** A "Take" click counts for the item that arrives within this many ticks (walking to it). */
    private static final int PICKUP_WINDOW_TICKS = 50;
    private static final int SHOP_GROUP = 300;
    private static final int SHOP_STOCK_CHILD = 16;
    /** Shop currencies: spent when buying, received when selling, never a step's item. */
    private static final Set<String> CURRENCIES = new HashSet<>(Arrays.asList(
        "coins", "tokkul", "trading sticks", "platinum token", "numulite", "golden nugget",
        "mark of grace", "stardust", "warrior guild token", "castle wars ticket"));
    private static final Pattern CHARGED = Pattern.compile("^(.+)\\((\\d+)\\)$");

    private final Client client;
    private final ItemManager itemManager;
    private final RouteRecorder host;

    private boolean bankOpen;
    private boolean shopOpen;
    /** Inventory when the current bank/shop session started (or last emptied). */
    private Inventory sessionStart;
    /** Inventory at the last change, for spotting what a pickup added. */
    private Inventory lastInv;
    /** Lowercased item name -> tick its "Take" was clicked. */
    private final Map<String, Integer> pendingTakes = new HashMap<>();
    /** Running totals for a PICKUP draft, so repeated pickups at one spot become one step. */
    private RouteStep pickupStep;
    private final Map<String, Long> pickupCounts = new LinkedHashMap<>();

    /** Inventory contents by recorded name (noted items count as their normal form). */
    private static final class Inventory {
        final Map<String, Long> qty = new LinkedHashMap<>();
        boolean isEmpty() { return qty.isEmpty(); }
        long get(String name) { return qty.getOrDefault(name, 0L); }
    }

    void start() {
        bankOpen = false;
        shopOpen = false;
        sessionStart = null;
        lastInv = snapshot();
        pendingTakes.clear();
        pickupStep = null;
        pickupCounts.clear();
    }

    /** A ground item's "Take" was clicked. */
    void onTake(int itemId, int tick) {
        String name = keyOf(itemId);
        if (name != null) pendingTakes.put(name.toLowerCase(), tick);
    }

    /** Called every tick with the player's tile (null inside instances). */
    void onTick(WorldPoint pos) {
        boolean bankNow = visible(ComponentID.BANK_ITEM_CONTAINER) || visible(InterfaceID.SeedVault.OBJ_LIST);
        if (bankNow && !bankOpen) sessionStart = snapshot();
        if (bankNow && sessionStart != null && !sessionStart.isEmpty()) {
            // Emptied the inventory: that's its own step; what's withdrawn after counts from empty.
            Inventory now = snapshot();
            if (now.isEmpty()) {
                RouteStep step = host.stepAt(pos, "Deposit all" + LocationNames.at(pos));
                step.setItemMode(ItemMode.DEPOSIT_ALL);
                sessionStart = now;
            }
        }
        if (!bankNow && bankOpen) finishBank(pos);
        bankOpen = bankNow;

        boolean shopNow = visible(SHOP_GROUP, SHOP_STOCK_CHILD);
        if (shopNow && !shopOpen) sessionStart = snapshot();
        if (!shopNow && shopOpen) finishShop(pos);
        shopOpen = shopNow;
    }

    /** The inventory changed; outside a bank or shop, look for picked-up items. */
    void onInventoryChanged(WorldPoint pos, int tick) {
        Inventory now = snapshot();
        if (!bankOpen && !shopOpen && lastInv != null) {
            Map<String, Long> other = new LinkedHashMap<>();
            for (Map.Entry<String, Long> e : now.qty.entrySet()) {
                long gained = e.getValue() - lastInv.get(e.getKey());
                if (gained <= 0) continue;
                Integer took = pendingTakes.get(e.getKey().toLowerCase());
                if (took == null || tick - took > PICKUP_WINDOW_TICKS) other.put(e.getKey(), gained);
                else addPickup(pos, e.getKey(), gained);
            }
            if (!other.isEmpty()) host.onItemsGained(other, tick);
        }
        lastInv = now;
    }

    private void finishBank(WorldPoint pos) {
        Inventory end = snapshot();
        List<String> entries = new ArrayList<>();
        for (Map.Entry<String, Long> e : end.qty.entrySet()) {
            if (e.getValue() > sessionStart.get(e.getKey())) {
                entries.add(itemEntry(e.getKey(), e.getValue()));
            }
        }
        if (!entries.isEmpty()) {
            RouteStep step = host.stepAt(pos, "Withdraw from bank" + LocationNames.at(pos));
            step.setItemMode(ItemMode.BANK);
            step.setItemList(String.join(", ", entries));
        }
        sessionStart = null;
    }

    private void finishShop(WorldPoint pos) {
        Inventory end = snapshot();
        List<String> sold = new ArrayList<>();
        List<String> bought = new ArrayList<>();
        Set<String> names = new LinkedHashSet<>(sessionStart.qty.keySet());
        names.addAll(end.qty.keySet());
        for (String name : names) {
            if (CURRENCIES.contains(name.toLowerCase())) continue;
            long delta = end.get(name) - sessionStart.get(name);
            // SELL completes once none are left, so it lists names only.
            if (delta < 0) sold.add(itemEntry(name, 1));
            else if (delta > 0) bought.add(itemEntry(name, delta));
        }
        if (!sold.isEmpty()) {
            RouteStep step = host.stepAt(pos, "Sell to shop" + LocationNames.at(pos));
            step.setItemMode(ItemMode.SELL);
            step.setItemList(String.join(", ", sold));
        }
        if (!bought.isEmpty()) {
            RouteStep step = host.stepAt(pos, "Buy from shop" + LocationNames.at(pos));
            step.setItemMode(ItemMode.SHOP);
            step.setItemList(String.join(", ", bought));
        }
        sessionStart = null;
    }

    private void addPickup(WorldPoint pos, String name, long gained) {
        if (host.runningCourse(pos)) {
            // Marks of grace mid-lap: a bonus, not something the route should wait for.
            host.trace("PICKUP " + gained + " " + name + " ignored (agility lap)");
            return;
        }
        host.trace("PICKUP " + gained + " " + name);
        // Keep adding to the current pickup step while it's still the latest step nearby.
        // Loot from a kill step joins that step, so "kill and loot" stays one step.
        boolean renamable = true;
        if (pickupStep == null || host.lastDraft() != pickupStep || !host.isNear(pickupStep, pos)) {
            RouteStep last = host.lastDraft();
            if (last != null && last.getNpcKillCount() > 0 && !last.hasItems()
                && host.isNear(last, pos, 15)) {
                pickupStep = last;
            } else {
                pickupStep = host.stepAt(pos, "Pick up items" + LocationNames.at(pos));
            }
            pickupStep.setItemMode(ItemMode.PICKUP);
            pickupCounts.clear();
        }
        if (pickupStep.getNpcKillCount() > 0) renamable = false;
        pickupCounts.merge(name, gained, Long::sum);
        List<String> entries = new ArrayList<>();
        for (Map.Entry<String, Long> e : pickupCounts.entrySet()) {
            entries.add(itemEntry(e.getKey(), e.getValue()));
        }
        pickupStep.setItemList(String.join(", ", entries));
        if (renamable) pickupStep.setName(pickupCounts.size() == 1
            ? "Pick up " + name + LocationNames.at(pos)
            : "Pick up items" + LocationNames.at(pos));
    }

    /** One item-list entry, e.g. "28 Yew logs" or "3 Amulet of glory(*)". */
    private static String itemEntry(String name, long qty) {
        return qty > 1 ? qty + " " + name : name;
    }

    /**
     * The name an item is recorded under. Charged jewellery and gear (glory(4), games
     * necklace(8)) becomes "Amulet of glory(*)" so any charge counts and they add up; doses
     * (potions) keep their exact name, since a 1-dose potion isn't a full one.
     */
    private String keyOf(int itemId) {
        int id = itemManager.canonicalize(itemId);
        String name = nameOf(id);
        if (name == null) return null;
        Matcher m = CHARGED.matcher(name);
        if (!m.matches()) return name;
        ItemStats stats = itemManager.getItemStats(id);
        if (stats == null || !stats.isEquipable()) return name;
        int charges = 0;
        for (int v : ItemVariationMapping.getVariations(ItemVariationMapping.map(id))) {
            String n = nameOf(v);
            Matcher vm = n == null ? null : CHARGED.matcher(n);
            if (vm != null && vm.matches() && vm.group(1).equals(m.group(1))) charges++;
        }
        return charges >= 2 ? m.group(1) + BankItemManager.ANY_CHARGE : name;
    }

    private Inventory snapshot() {
        Inventory inv = new Inventory();
        ItemContainer c = client.getItemContainer(InventoryID.INVENTORY);
        if (c == null) return inv;
        for (Item it : c.getItems()) {
            if (it.getId() <= 0) continue;
            String name = keyOf(it.getId());
            if (name == null) continue;
            inv.qty.merge(name, (long) it.getQuantity(), Long::sum);
        }
        return inv;
    }

    private String nameOf(int itemId) {
        String n = itemManager.getItemComposition(itemManager.canonicalize(itemId)).getName();
        return n == null || n.isEmpty() || n.equalsIgnoreCase("null") ? null : n;
    }

    private boolean visible(int componentId) {
        Widget w = client.getWidget(componentId);
        return w != null && !w.isHidden();
    }

    private boolean visible(int group, int child) {
        Widget w = client.getWidget(group, child);
        return w != null && !w.isHidden();
    }

}

package com.routeplanner.record;

import lombok.RequiredArgsConstructor;
import com.routeplanner.model.*;
import com.routeplanner.util.LocationNames;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import java.util.*;
import java.util.regex.Pattern;

/**
 * Object interactions that aren't skilling: searching a crate, opening a chest, inspecting a
 * painting, using a key on a door, taking an agility shortcut, entering a cave. Most give no XP,
 * so the activity recorder never sees them, but routes and quests are full of them.
 *
 *  - A click on an object is remembered until the player stands next to it and stops; then it
 *    becomes "Search Crate" (the menu option and the object), highlighting the object. "Use X ->
 *    Y" becomes "Use X on Y" and outlines X in the inventory.
 *  - Items that turn up right after (a key from the crate) go on that step as a pickup, so it
 *    ticks itself off. A conversation that opens (reading a book, a puzzle) puts its dialogue
 *    choices on it too.
 *  - XP straight after means it was skilling after all: the step is dropped and the activity
 *    recorder's step stands instead. Agility XP is the exception: off an agility course it means
 *    the object was a shortcut (a rope swing, a log), so the shortcut is the step and the XP
 *    isn't an Agility step. A shortcut that carries the player along (a swing) never lets them
 *    stop next to it, so its XP makes the step, at the object.
 *  - An object that moves the player (a shortcut, a cave entrance) can do so the moment they
 *    reach it; the step is then made where they stood before the move.
 *  - Doors, gates, curtains, stairs and ladders (the climb becomes the next step's stairs),
 *    banking, boarding, teleports and agility course obstacles are left to the rest of the
 *    recorder.
 */
@RequiredArgsConstructor
class ObjectRecorder {

    /** Give up on a click if the player hasn't reached the object within this many ticks. */
    private static final int REACH_TICKS = 30;
    /** Standing this close (tiles, from the object's tile) counts as at it; big objects need 2. */
    private static final int REACH_TILES = 2;
    /** Items or a conversation this soon after the interaction belong to it. */
    static final int FOLLOW_TICKS = 6;
    /** XP this soon after means the click was skilling. */
    private static final int XP_TICKS = 6;
    /** A long shortcut (a log balance, a pipe) can take this many ticks before its XP comes. */
    private static final int SHORTCUT_XP_TICKS = 20;

    /** Options the rest of the recorder covers: boarding, teleports, banking, trading. */
    private static final Pattern SKIP_OPTION = Pattern.compile(
        "(?i)^(walk here|examine|cancel|board.*|teleport.*|travel|use-quickly|quick-.*|bank|collect|deposit.*|trade)$");
    /** Objects that are plain travel or banking whatever the option. */
    private static final Pattern SKIP_OBJECT = Pattern.compile(
        "(?i).*\\b(door|doors|gate|gates|curtain|curtains|trapdoor|staircase|stairs|ladder|bank booth|bank chest|"
            + "deposit box|portal|gangplank|fairy ring|fairy tree|spirit tree)\\b.*");

    private final Client client;
    private final RouteRecorder host;

    private String option;
    private String target;
    private String used;
    private int clickTick = -1000;
    private int sceneX;
    private int sceneY;
    private WorldPoint objectTile;   // the clicked object's tile (null in instances)

    private RouteStep step;          // the latest interaction's step
    private int stepTick = -1000;
    private boolean stepHadItems;
    private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);

    void start() {
        option = null;
        step = null;
        clickTick = stepTick = -1000;
        xp.clear();
        for (Skill s : Skill.values()) {
            if (s == Skill.OVERALL) continue;
            try {
                xp.put(s, client.getSkillExperience(s));
            } catch (RuntimeException ignored) {
                // a skill the client doesn't report (newer than the API)
            }
        }
    }

    /** Whether this click is one this recorder handles (not plain travel, banking or an examine). */
    static boolean interesting(String option, String target) {
        if (option == null || target == null || target.isEmpty()) return false;
        if (SKIP_OPTION.matcher(option.trim()).matches()) return false;
        // Using an item on a door or gate (a key) is part of the quest; opening one is travel
        return usedItem(target) != null || !SKIP_OBJECT.matcher(objectName(target)).matches();
    }

    /**
     * An object was clicked (any option); scene coordinates are the object's tile. Obstacles of
     * an agility course ({@code courseObstacle}) are the course's lap, not steps.
     */
    void onClick(String option, String target, boolean courseObstacle, WorldPoint objectTile, int sceneX, int sceneY, int tick) {
        if (courseObstacle || !interesting(option, target)) {
            this.option = null;
            return;
        }
        this.option = option.trim();
        this.target = objectName(target);
        this.used = usedItem(target);
        this.objectTile = objectTile;
        this.sceneX = sceneX;
        this.sceneY = sceneY;
        this.clickTick = tick;
        host.trace("OBJECT click '" + this.option + "' on '" + this.target + "'" + (used != null ? " using '" + used + "'" : ""));
    }

    /** The player walked off or went to an NPC instead: a pending object click is off. */
    void onOtherClick() {
        option = null;
    }

    /**
     * Each tick: once the player is next to the clicked object and has stopped, the interaction
     * is a step. {@code playerSceneX/Y} are the player's scene coordinates, which work in
     * instances too.
     */
    void onTick(WorldPoint pos, int playerSceneX, int playerSceneY, boolean moving, int tick) {
        if (option == null) return;
        if (tick - clickTick > REACH_TICKS) {
            host.trace("OBJECT '" + option + " " + target + "' never reached");
            option = null;
            return;
        }
        int d = Math.max(Math.abs(playerSceneX - sceneX), Math.abs(playerSceneY - sceneY));
        // Next to it, or close and stopped (a big object's far side)
        if (d > REACH_TILES || (moving && d > 1)) return;
        makeStep(pos, tick);
    }

    /**
     * The player was moved (a jump, a climb) while a click was pending: the object did it, so the
     * interaction happened at {@code from}, where they stood before.
     */
    void onJump(WorldPoint from, int tick) {
        if (option == null || tick - clickTick > REACH_TICKS) return;
        host.trace("OBJECT '" + option + " " + target + "' moved the player");
        makeStep(from, tick);
    }

    private void makeStep(WorldPoint pos, int tick) {
        String name = used != null ? "Use " + used + " on " + target : cap(option) + " " + target;
        RouteStep last = host.lastDraft();
        // Clicking the same thing again (searching twice, a puzzle): one step
        if (last != null && last == step && name.equals(stripAt(last.getName())) && host.isNear(last, pos, 3)) {
            host.trace("OBJECT repeat of '" + name + "', same step");
            stepTick = tick;
            option = null;
            return;
        }
        RouteStep s = host.stepAt(pos, name + LocationNames.at(pos));
        s.setSkillingTargetObject(target);
        s.setHighlightEnabled(true);
        if (used != null) s.setInventoryHighlightItems(used);
        step = s;
        stepTick = tick;
        stepHadItems = s.hasItems();
        option = null;
        host.trace("OBJECT step " + RouteRecorder.describeStep(s));
    }

    /** The latest interaction's step, if it was just made (a conversation opening goes on it). */
    RouteStep recentStep(int tick) {
        return step != null && tick - stepTick <= FOLLOW_TICKS && host.lastDraft() == step ? step : null;
    }

    /**
     * Items that arrived without a pickup, purchase or withdrawal. True if they went on the
     * interaction's step. Items can turn up before the player has stopped by the object (picking
     * a banana takes a tick); they prove the interaction happened, so they make the step.
     */
    boolean onItemsGained(Map<String, Long> gains, int tick) {
        if (gains.isEmpty()) return false;
        if (recentStep(tick) == null && option != null && tick - clickTick <= REACH_TICKS) makeStep(objectTile, tick);
        RouteStep s = recentStep(tick);
        if (s == null || stepHadItems) return false;
        s.setItemList(addItems(s.getItemMode() == ItemMode.PICKUP ? s.getItemList() : null, gains));
        s.setItemMode(ItemMode.PICKUP);
        host.trace("OBJECT items " + gains + " -> " + RouteRecorder.describeStep(s));
        return true;
    }

    private static final Pattern COUNTED = Pattern.compile("^(\\d+) (.+)$");

    /** An item list with {@code gains} added, same items summed: "Banana" + 1 Banana = "2 Banana". */
    static String addItems(String list, Map<String, Long> gains) {
        Map<String, Long> counts = new LinkedHashMap<>();
        if (list != null) {
            for (String e : list.split(",")) {
                String t = e.trim();
                if (t.isEmpty()) continue;
                java.util.regex.Matcher m = COUNTED.matcher(t);
                if (m.matches()) counts.merge(m.group(2), Long.parseLong(m.group(1)), Long::sum);
                else counts.merge(t, 1L, Long::sum);
            }
        }
        for (Map.Entry<String, Long> g : gains.entrySet()) counts.merge(g.getKey(), g.getValue(), Long::sum);
        List<String> entries = new ArrayList<>();
        for (Map.Entry<String, Long> c : counts.entrySet()) {
            entries.add(c.getValue() > 1 ? c.getValue() + " " + c.getKey() : c.getKey());
        }
        return String.join(", ", entries);
    }

    /**
     * XP gained: if it came right after the interaction, that was skilling, so the step goes.
     * Returns true for Agility XP from a shortcut, which belongs to the shortcut's step and isn't
     * an activity of its own. (Course obstacles never get here: their clicks aren't taken.)
     */
    boolean onXp(Skill skill, int newXp, int tick) {
        Integer prev = xp.put(skill, newXp);
        if (prev == null || newXp <= prev) return false;
        if (skill == Skill.AGILITY) {
            if (option != null && tick - clickTick <= REACH_TICKS) {
                host.trace("OBJECT agility XP from '" + option + " " + target + "': a shortcut, step at the object");
                makeStep(objectTile, tick);
                return true;
            }
            // Shortcut XP comes when the obstacle finishes, which can be a while after reaching it
            if (step != null && host.lastDraft() == step && tick - stepTick <= SHORTCUT_XP_TICKS) {
                host.trace("OBJECT agility XP from shortcut '" + step.getName() + "', kept as its step");
                return true;
            }
        }
        RouteStep s = step;
        if (s != null && tick - stepTick <= XP_TICKS && host.lastDraft() == s && !s.hasItems()
            && (s.getDialogOptions() == null || s.getDialogOptions().trim().isEmpty()) && !s.hasQuest()) {
            host.trace("OBJECT '" + s.getName() + "' gave " + skill + " XP: skilling, step dropped");
            host.removeDraft(s);
            step = null;
        }
        if (option != null && tick - clickTick <= REACH_TICKS) option = null; // still walking there: skilling
        return false;
    }

    static String objectName(String target) {
        int arrow = target.lastIndexOf("->");
        String t = arrow >= 0 ? target.substring(arrow + 2) : target;
        return t.trim();
    }

    static String usedItem(String target) {
        int arrow = target.indexOf("->");
        return arrow < 0 ? null : target.substring(0, arrow).trim();
    }

    private static String stripAt(String name) {
        int at = name.indexOf(" at ");
        return at < 0 ? name : name.substring(0, at);
    }

    private static String cap(String s) {
        String t = s.replace('-', ' ').trim();
        return t.isEmpty() ? t : t.substring(0, 1).toUpperCase(Locale.ROOT) + t.substring(1);
    }
}

package com.routeplanner.record;

import static com.routeplanner.ui.Ui.*;

import com.routeplanner.util.HighlightColors;
import com.routeplanner.*;
import com.routeplanner.model.*;
import net.runelite.client.ui.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;

/**
 * After re-recording a section: the section and the recording side by side as one list. New
 * steps are green, steps the recording fills in or changes are orange (one tick box per field),
 * steps the recording didn't see are grey, and everything else is plain. Apply writes the ticked
 * changes into the section; Discard leaves it as it was.
 */
public class ReRecordDialog extends JDialog {

    static final Color GREEN = new Color(80, 200, 120);
    static final Color ORANGE = new Color(255, 160, 50);
    static final Color GREY = new Color(130, 130, 130);

    private final RoutePlannerPlugin plugin;
    private final ReRecordSession session;
    private final List<SectionDiff.Row> rows;
    /** NEW rows: add the step. UNSEEN rows: keep the step. */
    private final Map<SectionDiff.Row, JCheckBox> rowBoxes = new IdentityHashMap<>();
    private final Map<SectionDiff.FieldChange, JCheckBox> fieldBoxes = new IdentityHashMap<>();

    public ReRecordDialog(RoutePlannerPlugin plugin, ReRecordSession session, List<RouteStep> drafts) {
        this.plugin = plugin;
        this.session = session;
        this.rows = SectionDiff.compare(session.getOriginalSteps(), drafts, session.getTickedAt());

        RouteSection section = session.getSection();
        setTitle("Re-recorded: " + section.getName());
        setAlwaysOnTop(true);
        setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
        addWindowListener(new WindowAdapter() {
            @Override public void windowClosing(WindowEvent e) { onDiscard(); }
        });

        JPanel root = new JPanel(new BorderLayout(0, 8));
        root.setBorder(new EmptyBorder(10, 10, 10, 10));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);

        int added = 0, changed = 0, unseen = 0;
        for (SectionDiff.Row r : rows) {
            if (r.kind == SectionDiff.Kind.NEW) added++;
            else if (r.kind == SectionDiff.Kind.CHANGED) changed++;
            else if (r.kind == SectionDiff.Kind.UNSEEN) unseen++;
        }
        JPanel head = bare(new JPanel());
        head.setLayout(new BoxLayout(head, BoxLayout.Y_AXIS));
        JLabel title = new JLabel("<html><b>" + HighlightColors.escapeHtml(section.getName()) + "</b></html>");
        title.setForeground(Color.WHITE);
        head.add(title);
        JLabel legend = new JLabel("<html>"
            + swatch(GREEN, added + " new") + " &nbsp; "
            + swatch(ORANGE, changed + " changed") + " &nbsp; "
            + swatch(GREY, unseen + " not seen") + "<br>"
            + "<span style='color:#aaaaaa'>Untick anything you don't want. Double-click a new step to edit it.</span></html>");
        legend.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        head.add(Box.createVerticalStrut(4));
        head.add(legend);
        root.add(head, BorderLayout.NORTH);

        JPanel list = new JPanel();
        list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
        list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        list.setBorder(new EmptyBorder(4, 4, 4, 4));
        int n = 1;
        for (SectionDiff.Row r : rows) list.add(rowPanel(r, n++));
        list.add(Box.createVerticalGlue());
        JScrollPane scroll = new JScrollPane(list);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        root.add(scroll, BorderLayout.CENTER);

        JPanel bottom = bare(new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0)));
        JButton discard = new JButton("Discard");
        discard.addActionListener(e -> onDiscard());
        JButton apply = new JButton("Apply to section");
        apply.setForeground(new Color(0, 200, 0));
        apply.addActionListener(e -> onApply());
        bottom.add(discard);
        bottom.add(apply);
        root.add(bottom, BorderLayout.SOUTH);

        setContentPane(root);
        setSize(560, 520);
        setLocationRelativeTo(null);
    }

    private JPanel rowPanel(SectionDiff.Row r, int number) {
        JPanel p = bareLeft(new JPanel());
        p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
        Color color = colorOf(r.kind);
        p.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 3, 0, 0, color == null ? ColorScheme.DARKER_GRAY_COLOR : color),
            new EmptyBorder(3, 6, 3, 2)));

        RouteStep shown = r.step != null ? r.step : r.recorded;
        String text = number + ". " + shown.getName() + tag(r.kind);
        Component top;
        if (r.kind == SectionDiff.Kind.NEW || r.kind == SectionDiff.Kind.UNSEEN) {
            JCheckBox box = new JCheckBox(text, true);
            box.setToolTipText(r.kind == SectionDiff.Kind.NEW ? "Add this recorded step to the section"
                : "Keep this step (the recording never reached it). Untick to delete it.");
            style(box, color);
            rowBoxes.put(r, box);
            if (r.kind == SectionDiff.Kind.NEW) {
                box.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
                box.addMouseListener(new MouseAdapter() {
                    @Override public void mouseClicked(MouseEvent e) {
                        if (e.getClickCount() != 2) return;
                        box.setSelected(true);
                        QuickStepDialog editor = new QuickStepDialog(plugin, session.getRoute(), r.recorded);
                        editor.setOnSaved(() -> box.setText(number + ". " + r.recorded.getName() + tag(r.kind)));
                        editor.setVisible(true);
                    }
                });
            }
            top = box;
        } else {
            JLabel l = smallText(new JLabel(text), color != null ? color : ColorScheme.LIGHT_GRAY_COLOR);
            l.setBorder(new EmptyBorder(2, 0, 2, 0));
            top = l;
        }
        ((javax.swing.JComponent) top).setAlignmentX(Component.LEFT_ALIGNMENT);
        p.add(top);

        for (SectionDiff.FieldChange c : r.changes) {
            String change = "<html><span style='color:#cccccc'>" + HighlightColors.escapeHtml(c.label) + ":</span> "
                + (c.fill ? "<i>none</i>" : HighlightColors.escapeHtml(clip(c.oldText))) + " &rarr; " + HighlightColors.escapeHtml(clip(c.newText)) + "</html>";
            JCheckBox box = new JCheckBox(change, c.fill);
            box.setToolTipText(c.fill ? "The step had nothing here; the recording fills it in."
                : "Different from what the step had. Tick to replace it with the recorded value.");
            style(box, ColorScheme.LIGHT_GRAY_COLOR);
            box.setBorder(new EmptyBorder(0, 16, 0, 0));
            box.setAlignmentX(Component.LEFT_ALIGNMENT);
            fieldBoxes.put(c, box);
            p.add(box);
        }
        p.setMaximumSize(new Dimension(Integer.MAX_VALUE, p.getPreferredSize().height));
        return p;
    }

    private void onApply() {
        RouteSection section = session.getSection();
        if (!plugin.getRoutes().contains(session.getRoute()) || !session.getRoute().getSections().contains(section)) {
            JOptionPane.showMessageDialog(this, "The section \"" + section.getName()
                + "\" no longer exists, so the recording can't be applied to it.");
            return;
        }
        plugin.getRouteHistory().push(session.getRoute(), "Re-record section \"" + section.getName() + "\"",
            plugin.getRouteGson());
        List<RouteStep> merged = new ArrayList<>();
        for (SectionDiff.Row r : rows) {
            switch (r.kind) {
                case NEW:
                    if (!rowBoxes.get(r).isSelected()) break;
                    r.recorded.setSectionId(section.getId());
                    r.recorded.setCompleted(true); // just done while recording
                    merged.add(r.recorded);
                    break;
                case UNSEEN:
                    if (!rowBoxes.get(r).isSelected()) break;
                    r.step.setCompleted(session.doneBeforeOrDuring(r.step));
                    merged.add(r.step);
                    break;
                default: // SAME, CHANGED
                    for (SectionDiff.FieldChange c : r.changes) {
                        if (fieldBoxes.get(c).isSelected()) c.applyTo(r.step, r.recorded);
                    }
                    // Paired with a recorded step means it was done during the recording
                    r.step.setCompleted(r.recorded != null || session.doneBeforeOrDuring(r.step));
                    merged.add(r.step);
            }
        }
        // One swap, so the game never reads a half-built list
        section.setSteps(merged);
        plugin.saveRoutes();
        plugin.refreshHighlights();
        dispose();
    }

    private void onDiscard() {
        int c = JOptionPane.showConfirmDialog(this, "Discard the recording and leave the section as it was?",
            "Discard re-recording", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        if (c != JOptionPane.YES_OPTION) return;
        session.restoreTicks();
        plugin.saveRoutes();
        plugin.refreshHighlights();
        dispose();
    }

    private static void style(JCheckBox box, Color fg) {
        smallText(bare(box), fg);
        box.setFocusPainted(false);
        box.setHorizontalAlignment(SwingConstants.LEFT);
    }

    private static Color colorOf(SectionDiff.Kind k) {
        switch (k) {
            case NEW: return GREEN;
            case CHANGED: return ORANGE;
            case UNSEEN: return GREY;
            default: return null;
        }
    }

    private static String tag(SectionDiff.Kind k) {
        switch (k) {
            case NEW: return "  (new)";
            case UNSEEN: return "  (not seen)";
            default: return "";
        }
    }

    private static String swatch(Color c, String text) {
        return String.format("<span style='color:#%02x%02x%02x'>&#9632; %s</span>", c.getRed(), c.getGreen(), c.getBlue(), text);
    }

    private static String clip(String s) {
        return s.length() > 60 ? s.substring(0, 57) + "..." : s;
    }

}

package com.routeplanner.record;

import com.routeplanner.model.*;
import lombok.Getter;
import java.util.*;

/**
 * Re-recording one section: the section's ticks from before, and which of its steps the route
 * ticked off while recording (with how many steps had been recorded at that moment, which tells
 * the comparison roughly which recorded step goes with it).
 */
public class ReRecordSession {
    @Getter private final Route route;
    @Getter private final RouteSection section;
    /** The section's steps as they were when the re-record started, in order. */
    @Getter private final List<RouteStep> originalSteps;
    private final Map<RouteStep, Boolean> priorCompleted = new HashMap<>();
    @Getter private final Map<RouteStep, Integer> tickedAt = new HashMap<>();

    public ReRecordSession(Route route, RouteSection section) {
        this.route = route;
        this.section = section;
        this.originalSteps = new ArrayList<>(section.getSteps());
        for (RouteStep s : originalSteps) priorCompleted.put(s, s.isCompleted());
    }

    /** The route ticked {@code step} off when {@code draftCount} steps had been recorded. */
    public void ticked(RouteStep step, int draftCount) {
        if (priorCompleted.containsKey(step)) tickedAt.putIfAbsent(step, draftCount);
    }

    /** Ticked before the re-record started, or ticked off during it. */
    public boolean doneBeforeOrDuring(RouteStep step) {
        return Boolean.TRUE.equals(priorCompleted.get(step)) || tickedAt.containsKey(step);
    }

    /** Put the section's ticks back (keeping anything ticked off while recording). */
    public void restoreTicks() {
        for (RouteStep s : originalSteps) s.setCompleted(doneBeforeOrDuring(s));
    }
}

package com.routeplanner.record;

import com.routeplanner.util.*;
import com.routeplanner.*;
import com.routeplanner.model.*;
import net.runelite.client.ui.ColorScheme;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.List;

/**
 * Review screen shown when a recording stops. Drafts are edited here (with the normal step
 * editor), then saved as a new section of the route the recording was started on. Nothing
 * reaches the route until Save, and closing with unsaved steps asks first.
 */
public class RecordReviewDialog extends JDialog {

    private final RoutePlannerPlugin plugin;
    private final Route route;
    private final List<RouteStep> drafts;
    private final DefaultListModel<RouteStep> model = new DefaultListModel<>();
    private final JList<RouteStep> list = new JList<>(model);

    public RecordReviewDialog(RoutePlannerPlugin plugin, Route route, List<RouteStep> drafts) {
        this.plugin = plugin;
        this.route = route;
        this.drafts = new ArrayList<>(drafts);

        setTitle("Review recording");
        setAlwaysOnTop(true);
        setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
        addWindowListener(new WindowAdapter() {
            @Override public void windowClosing(WindowEvent e) { onDiscard(); }
        });

        JPanel root = new JPanel(new BorderLayout(0, 8));
        root.setBorder(new EmptyBorder(10, 10, 10, 10));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel header = new JLabel("<html>" + drafts.size() + " recorded steps for <b>"
            + HighlightColors.escapeHtml(route.getName()) + "</b>. Edit or remove anything before saving.</html>");
        header.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        root.add(header, BorderLayout.NORTH);

        for (RouteStep s : this.drafts) model.addElement(s);
        list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        list.setCellRenderer(new StepRenderer());
        list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        list.addMouseListener(new MouseAdapter() {
            @Override public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 2) onEdit();
            }
        });
        if (!model.isEmpty()) list.setSelectedIndex(0);
        root.add(new JScrollPane(list), BorderLayout.CENTER);

        JPanel side = new JPanel(new GridLayout(0, 1, 0, 4));
        side.setBackground(ColorScheme.DARK_GRAY_COLOR);
        side.add(button("Edit", e -> onEdit()));
        side.add(button("Delete", e -> onDelete()));
        side.add(button("Move up", e -> move(-1)));
        side.add(button("Move down", e -> move(1)));
        JPanel sideWrap = new JPanel(new BorderLayout());
        sideWrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
        sideWrap.add(side, BorderLayout.NORTH);
        root.add(sideWrap, BorderLayout.EAST);

        JPanel bottom = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        bottom.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bottom.add(button("Discard", e -> onDiscard()));
        JButton save = button("Save to route", e -> onSave());
        save.setForeground(new Color(0, 200, 0));
        bottom.add(save);
        root.add(bottom, BorderLayout.SOUTH);

        setContentPane(root);
        setSize(520, 420);
        setLocationRelativeTo(null);
    }

    private JButton button(String text, ActionListener action) {
        JButton b = new JButton(text);
        b.setFocusPainted(false);
        b.addActionListener(action);
        return b;
    }

    private void onEdit() {
        RouteStep step = list.getSelectedValue();
        if (step == null) return;
        // The editor edits the draft in place; it isn't in the route yet, so nothing is saved.
        QuickStepDialog editor = new QuickStepDialog(plugin, route, step);
        editor.setOnSaved(list::repaint);
        editor.setVisible(true);
    }

    private void onDelete() {
        int i = list.getSelectedIndex();
        if (i < 0) return;
        model.remove(i);
        if (!model.isEmpty()) list.setSelectedIndex(Math.min(i, model.size() - 1));
    }

    private void move(int delta) {
        int i = list.getSelectedIndex();
        int j = i + delta;
        if (i < 0 || j < 0 || j >= model.size()) return;
        RouteStep s = model.remove(i);
        model.add(j, s);
        list.setSelectedIndex(j);
    }

    private void onSave() {
        if (model.isEmpty()) {
            JOptionPane.showMessageDialog(this, "There are no steps left to save.");
            return;
        }
        if (!plugin.getRoutes().contains(route)) {
            JOptionPane.showMessageDialog(this, "The route \"" + route.getName()
                + "\" no longer exists, so these steps can't be saved to it.");
            return;
        }
        String defaultName = "Recording " + new SimpleDateFormat("MMM d HH:mm").format(new Date());
        String name = (String) JOptionPane.showInputDialog(this, "Section name:", "Save recording",
            JOptionPane.PLAIN_MESSAGE, null, null, defaultName);
        if (name == null || name.trim().isEmpty()) return;
        String err = RouteTextValidator.checkField("Section name", name.trim());
        if (err != null) {
            JOptionPane.showMessageDialog(this, err, "Links not allowed", JOptionPane.WARNING_MESSAGE);
            return;
        }

        plugin.getRouteHistory().push(route, "Record section \"" + name.trim() + "\"", plugin.getRouteGson());
        RouteSection section = new RouteSection(UUID.randomUUID().toString(), name.trim());
        route.getSections().add(section);
        for (int i = 0; i < model.size(); i++) route.addStepToSection(model.get(i), section.getId());
        plugin.saveRoutes();
        plugin.refreshHighlights();
        dispose();
    }

    private void onDiscard() {
        if (!model.isEmpty()) {
            int choice = JOptionPane.showConfirmDialog(this,
                "Are you sure? You will lose all " + model.size() + " recorded steps.",
                "Discard recording", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
            if (choice != JOptionPane.YES_OPTION) return;
        }
        dispose();
    }

    /** One line per draft: its name plus tags for the components it carries. */
    private static class StepRenderer extends DefaultListCellRenderer {
        @Override
        public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                      boolean selected, boolean focus) {
            super.getListCellRendererComponent(list, value, index, selected, focus);
            RouteStep s = (RouteStep) value;
            StringBuilder tags = new StringBuilder();
            if (s.getTeleportMethod() != null) tags.append(" [Teleport]");
            else if (s.getWorldPoint() != null) tags.append(" [Location]");
            if (s.getTransitionPoint() != null) tags.append(" [Stairs]");
            if (s.hasBoarding()) tags.append(" [Boat]");
            if (s.hasItems()) tags.append(" [Items]");
            if (s.hasSkillGoal()) tags.append(" [Skill]");
            if (s.hasHighlight()) tags.append(" [Highlight]");
            if (s.getDialogOptions() != null && !s.getDialogOptions().trim().isEmpty()) tags.append(" [Dialog]");
            if (s.hasQuest()) tags.append(" [Quest]");
            if (s.hasNote()) tags.append(" [Note]");
            setText((index + 1) + ". " + s.getName() + tags);
            setBorder(new EmptyBorder(4, 6, 4, 6));
            return this;
        }
    }
}

