package com.routeplanner.teleport;

import com.routeplanner.*;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.*;
import net.runelite.api.*;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;
import java.util.*;
import java.util.List;

/**
 * On a fairy ring or spirit tree step inside an instance (a player-owned house), highlights
 * every ring or tree there, in any of its forms: the plain ring, the spirit tree, and the
 * spiritual fairy tree that is both. Outside instances the path already leads to, and lights,
 * the nearest one in the world.
 */
@Singleton
public class FairyRingObjectOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;

    /** The rings found in the scene, looked for again once a tick. */
    private final List<GameObject> rings = new ArrayList<>();
    private int scannedTick = -1;
    private boolean scannedForRing;

    @Inject
    public FairyRingObjectOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        WorldView wv = client.getTopLevelWorldView();
        if (step == null || !step.isHighlightEnabled() || wv == null || !wv.isInstance()) return null;
        boolean ring = FairyRings.isFairyRingStep(step);
        if (!ring && !SpiritTrees.isSpiritTreeStep(step)) return null;

        if (client.getTickCount() != scannedTick || ring != scannedForRing) {
            scannedTick = client.getTickCount();
            scannedForRing = ring;
            scan(wv, ring);
        }
        for (GameObject obj : rings) draw(graphics, obj.getConvexHull());
        return null;
    }

    private void scan(WorldView wv, boolean ring) {
        rings.clear();
        if (wv.getScene() == null) return;
        for (Tile[] column : wv.getScene().getTiles()[wv.getPlane()]) {
            for (Tile tile : column) {
                if (tile == null || tile.getGameObjects() == null) continue;
                for (GameObject obj : tile.getGameObjects()) {
                    if (!SceneObjects.isObject(obj)) continue;
                    // A big object is listed on each of its tiles: keep it once, from its corner
                    if (!tile.getSceneLocation().equals(obj.getSceneMinLocation())) continue;
                    String name = name(obj.getId());
                    if (ring ? FairyRings.isRingName(name) : SpiritTrees.isTreeName(name)) rings.add(obj);
                }
            }
        }
    }

    private String name(int id) {
        ObjectComposition comp = client.getObjectDefinition(id);
        if (comp != null && comp.getImpostorIds() != null) comp = comp.getImpostor();
        return comp == null || comp.getName() == null ? null : comp.getName().toLowerCase();
    }

    private void draw(Graphics2D graphics, Shape hull) {
        if (hull == null) return;
        HighlightColors.paint(graphics, hull, plugin.getConfig().npcHighlightColor());
        HighlightIcon.drawAbove(graphics, plugin, hull);
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;

/**
 * In the fairy ring interface, for a fairy ring step: lights the button that turns the next dial
 * towards the step's code, then the Teleport button once all three show it.
 */
@Singleton
public class FairyRingOverlay extends Overlay {

    private static final int[][] DIAL_BUTTONS = {
        {InterfaceID.Fairyrings._1_CLOCKWISE, InterfaceID.Fairyrings._1_ANTICLOCKWISE},
        {InterfaceID.Fairyrings._2_CLOCKWISE, InterfaceID.Fairyrings._2_ANTICLOCKWISE},
        {InterfaceID.Fairyrings._3_CLOCKWISE, InterfaceID.Fairyrings._3_ANTICLOCKWISE},
    };

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public FairyRingOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (!FairyRings.isFairyRingStep(step)) return null;
        Widget confirm = client.getWidget(InterfaceID.Fairyrings.CONFIRM);
        if (confirm == null || confirm.isHidden()) return null;

        String code = step.getTeleportNexus();
        if (FairyRings.normalize(code).equals(FairyRings.dialledCode(client))) {
            highlight(graphics, confirm);
            return null;
        }
        // A code already in the travel log sets all three dials with one click
        if (highlightLogEntry(graphics, code)) return null;
        for (int dial = 0; dial < 3; dial++) {
            int turns = FairyRings.turns(client, dial, code);
            if (turns == 0) continue;
            // One dial at a time, left to right, so there's only ever one thing to click
            highlight(graphics, client.getWidget(DIAL_BUTTONS[dial][turns > 0 ? 0 : 1]));
            return null;
        }
        highlight(graphics, confirm);
        return null;
    }

    /**
     * Highlights the code's travel log entry, or the log's scrollbar while the entry is scrolled
     * out of view. False when the log doesn't list the code (never visited, or searched away).
     */
    private boolean highlightLogEntry(Graphics2D graphics, String code) {
        int id = FairyRings.logEntry(code);
        if (id < 0) return false;
        if (highlightFavourite(graphics, code)) return true;
        Widget entry = client.getWidget(id);
        Widget list = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
        if (entry == null || entry.isHidden() || list == null || list.isHidden()) return false;
        Rectangle view = list.getBounds();
        Rectangle b = entry.getBounds();
        if (view == null || b == null || b.width <= 0) return false;
        if (view.contains(b)) {
            highlight(graphics, entry);
        } else {
            highlight(graphics, client.getWidget(InterfaceID.FairyringsLog.SCROLLBAR));
        }
        return true;
    }

    private static final int[] FAVE_ROWS = {
        InterfaceID.FairyringsLog.FAVE_1, InterfaceID.FairyringsLog.FAVE_2, InterfaceID.FairyringsLog.FAVE_3,
        InterfaceID.FairyringsLog.FAVE_4, InterfaceID.FairyringsLog.FAVE_5, InterfaceID.FairyringsLog.FAVE_6,
        InterfaceID.FairyringsLog.FAVE_7, InterfaceID.FairyringsLog.FAVE_8, InterfaceID.FairyringsLog.FAVE_9,
        InterfaceID.FairyringsLog.FAVE_10};
    private static final int[] FAVE_CODES = {
        InterfaceID.FairyringsLog.FAVE_CODE_1, InterfaceID.FairyringsLog.FAVE_CODE_2, InterfaceID.FairyringsLog.FAVE_CODE_3,
        InterfaceID.FairyringsLog.FAVE_CODE_4, InterfaceID.FairyringsLog.FAVE_CODE_5, InterfaceID.FairyringsLog.FAVE_CODE_6,
        InterfaceID.FairyringsLog.FAVE_CODE_7, InterfaceID.FairyringsLog.FAVE_CODE_8, InterfaceID.FairyringsLog.FAVE_CODE_9,
        InterfaceID.FairyringsLog.FAVE_CODE_10};

    /** A favourited code sits in its own row at the top of the travel log, not in the list below. */
    private boolean highlightFavourite(Graphics2D graphics, String code) {
        String want = FairyRings.normalize(code);
        for (int i = 0; i < FAVE_CODES.length; i++) {
            Widget codeText = client.getWidget(FAVE_CODES[i]);
            if (codeText == null || codeText.isHidden() || codeText.getText() == null) continue;
            String shown = Text.removeTags(codeText.getText()).replaceAll("[^A-Za-z]", "").toUpperCase(java.util.Locale.ROOT);
            if (!shown.startsWith(want)) continue;
            Widget row = client.getWidget(FAVE_ROWS[i]);
            highlight(graphics, row != null && !row.isHidden() && row.getWidth() > 0 ? row : codeText);
            return true;
        }
        return false;
    }

    private void highlight(Graphics2D graphics, Widget w) {
        if (w == null || w.isHidden()) return;
        Rectangle b = w.getBounds();
        if (b == null || b.width <= 0) return;
        Color c = plugin.getConfig().npcHighlightColor();
        HighlightColors.paint(graphics, b, c);
    }
}

package com.routeplanner.teleport;

import lombok.RequiredArgsConstructor;
import com.routeplanner.util.DataFiles;
import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import java.util.*;
import java.util.regex.*;

/**
 * Fairy rings: where the rings stand, where each three-letter code lands, and the interface's
 * dials. Read from the pathfinder's fairy_rings.tsv (rings are rows with an origin, codes are rows
 * with a destination and the code in the last column).
 */
public final class FairyRings {

    /** The teleport method saved on a step; its code (e.g. "CKR") is kept in teleportNexus. */
    public static final String METHOD = "FAIRY_RING";
    /** Zanaris is reached by its own option on any ring, not a code. */
    public static final String ZANARIS = "ZANARIS";

    /**
     * Each dial's letters in the order its varbit counts them (0 is the first letter). Pressing
     * a dial's clockwise button moves one letter on in this order.
     */
    private static final String[] DIALS = {"ADCB", "ILKJ", "PSRQ"};
    private static final int[] DIAL_VARBITS = {
        VarbitID.FAIRYRING_1, VarbitID.FAIRYRING_2, VarbitID.FAIRYRING_3};

    private static final Pattern CODE = Pattern.compile("^[ABCD][IJKL][PQRS]$");
    private static final Pattern LAST_DESTINATION = Pattern.compile("(?i)last-destination\\s*\\(([a-z]{3})\\)");

    /** A ring the player can step into. */
    @RequiredArgsConstructor
    public static final class Ring {
        public final WorldPoint tile;
        public final int objectId;

    }

    private static final Map<String, WorldPoint> DESTINATIONS = new LinkedHashMap<>();
    private static final List<Ring> RINGS = new ArrayList<>();

    static {
        load();
    }

    private FairyRings() {}

    private static void load() {
        for (String[] cols : DataFiles.rowsAt("/com/routeplanner/transports/fairy_rings.tsv")) {
            if (cols.length < 2) continue;
            WorldPoint origin = DataFiles.point(cols[0]);
            WorldPoint dest = DataFiles.point(cols[1]);
            if (origin != null) {
                RINGS.add(new Ring(origin, objectId(cols.length > 2 ? cols[2] : "")));
            } else if (dest != null && cols.length > 1) {
                String code = normalize(cols[cols.length - 1]);
                if (code != null) DESTINATIONS.putIfAbsent(code, dest);
            }
        }
    }

    /** "C K R", "ckr" -> "CKR"; "Zanaris" -> "ZANARIS"; null if it isn't a code. */
    public static String normalize(String code) {
        if (code == null) return null;
        String c = code.replaceAll("[^A-Za-z]", "").toUpperCase(Locale.ROOT);
        if (c.equals(ZANARIS)) return ZANARIS;
        return CODE.matcher(c).matches() ? c : null;
    }

    /** "CKR" -> "C K R", the way the game shows it. */
    public static String spaced(String code) {
        String c = normalize(code);
        if (c == null) return code;
        return c.equals(ZANARIS) ? "Zanaris" : c.charAt(0) + " " + c.charAt(1) + " " + c.charAt(2);
    }

    /** Where a code lands, or null for a code that goes nowhere. */
    public static WorldPoint destination(String code) {
        String c = normalize(code);
        return c == null ? null : DESTINATIONS.get(c);
    }

    /** How far from a code's destination a landing still counts as that code's. */
    private static final int LANDING_SLACK = 10;

    /** The code whose destination is at (or next to) {@code landed}, or null. */
    public static String codeLandingAt(WorldPoint landed) {
        if (landed == null) return null;
        String best = null;
        int bestDist = LANDING_SLACK + 1;
        for (Map.Entry<String, WorldPoint> e : DESTINATIONS.entrySet()) {
            WorldPoint d = e.getValue();
            if (d.getPlane() != landed.getPlane()) continue;
            int dist = d.distanceTo2D(landed);
            if (dist < bestDist) {
                bestDist = dist;
                best = e.getKey();
            }
        }
        return best;
    }

    /** Every code that goes somewhere, in the data's order. */
    public static List<String> codes() {
        return Collections.unmodifiableList(new ArrayList<>(DESTINATIONS.keySet()));
    }

    public static List<Ring> rings() {
        return Collections.unmodifiableList(RINGS);
    }

    /** The ring closest to {@code from} on the same floor, or null. */
    public static Ring nearest(WorldPoint from) {
        if (from == null) return null;
        Ring best = null;
        int bestDist = Integer.MAX_VALUE;
        for (Ring r : RINGS) {
            if (r.tile.getPlane() != from.getPlane()) continue;
            int d = r.tile.distanceTo2D(from);
            if (d < bestDist) {
                bestDist = d;
                best = r;
            }
        }
        return best;
    }

    /** Whether the step teleports by fairy ring (with a code that's known). */
    public static boolean isFairyRingStep(RouteStep step) {
        return step != null && METHOD.equals(step.getTeleportMethod()) && normalize(step.getTeleportNexus()) != null;
    }

    /** Whether an object's (lowercase) name is a fairy ring: plain rings and the spirit tree/ring combinations. */
    public static boolean isRingName(String lowerName) {
        return lowerName != null && (lowerName.contains("fairy ring") || lowerName.contains("fairy tree"));
    }

    /** The code a "Last-destination (CKR)" option dials, or null. */
    public static String lastDestinationCode(String option) {
        if (option == null) return null;
        Matcher m = LAST_DESTINATION.matcher(option);
        return m.find() ? normalize(m.group(1)) : null;
    }

    /** The code the interface's dials show now. Call on the client thread. */
    public static String dialledCode(Client client) {
        StringBuilder sb = new StringBuilder(3);
        for (int i = 0; i < 3; i++) {
            int v = client.getVarbitValue(DIAL_VARBITS[i]);
            if (v < 0 || v > 3) return null;
            sb.append(DIALS[i].charAt(v));
        }
        return sb.toString();
    }

    /**
     * Turns for dial {@code dial} (0-2) to show {@code code}'s letter: +1 or +2 for the clockwise
     * button (2 either way), -1 for anticlockwise, 0 when it's already there.
     */
    public static int turns(Client client, int dial, String code) {
        String c = normalize(code);
        if (c == null || c.equals(ZANARIS)) return 0;
        int want = DIALS[dial].indexOf(c.charAt(dial));
        int now = client.getVarbitValue(DIAL_VARBITS[dial]);
        int diff = Math.floorMod(want - now, 4);
        return diff == 3 ? -1 : diff;
    }

    /** The travel log's entry for a code: one per code, A I P first, each followed by its favourite star. */
    private static final int LOG_FIRST_ENTRY = net.runelite.api.gameval.InterfaceID.FairyringsLog.AIP;

    /**
     * The travel log widget for {@code code} (clicking it sets the dials to it), or -1 for Zanaris
     * or a code that isn't one. The log lists codes in alphabetical order of their letters.
     */
    public static int logEntry(String code) {
        String c = normalize(code);
        if (c == null || c.equals(ZANARIS)) return -1;
        int index = (c.charAt(0) - 'A') * 16 + (c.charAt(1) - 'I') * 4 + (c.charAt(2) - 'P');
        return LOG_FIRST_ENTRY + index * 2;
    }

    /** The object id at the end of a menu entry such as "Configure Fairy ring 29495", or -1. */
    static int objectId(String menu) {
        String[] parts = menu.trim().split("\\s+");
        try {
            return parts.length == 0 ? -1 : Integer.parseInt(parts[parts.length - 1]);
        } catch (NumberFormatException e) {
            return -1;
        }
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.util.Text;
import javax.inject.*;
import java.awt.*;
import java.util.*;
import java.util.List;

/**
 * Walks the player through a minigame teleport, one click at a time: the magic tab, the
 * Minigame Teleport spell (in every spellbook), then the minigame in the list it opens.
 * Highlight only: never clicks.
 */
@Singleton
public class MinigameTeleportOverlay extends Overlay {
    /** The magic tab's stone in each window layout (fixed, resizable classic, resizable modern, OSM). */
    private static final int[] MAGIC_TAB_STONES = {
        InterfaceID.Toplevel.STONE6, InterfaceID.ToplevelOsrsStretch.STONE6,
        InterfaceID.ToplevelPreEoc.STONE6, InterfaceID.ToplevelOsm.STONE6,
    };
    /** The Minigame Teleport spell, one per spellbook. */
    private static final int[] MINIGAME_SPELLS = {
        InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_STANDARD, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_ANCIENT,
        InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_LUNAR, InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_ARCEUUS,
    };

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public MinigameTeleportOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || step.getTeleportSpell() == null) return null;
        TeleportSpell spell = TeleportSpells.getByName(step.getTeleportSpell());
        String game = TeleportSpells.minigameName(spell);
        if (game == null || alreadyThere(step, spell)) return null;

        Widget target = nextClick(game);
        if (target == null) return null;
        Rectangle b = target.getBounds();
        if (b == null) return null;

        Color outline = plugin.getConfig().npcHighlightColor();
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        graphics.setColor(HighlightColors.fill(outline));
        graphics.fillRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        return null;
    }

    /** The widget the player should click next, or null if there is nothing to show. */
    private Widget nextClick(String game) {
        Widget list = visible(InterfaceID.Minigames.MINIGAMES);
        if (list != null) {
            Widget row = findRow(list, game);
            if (row == null) return null;   // every row exists even scrolled away, so it isn't unlocked
            // Scrolled out of view (its middle isn't in the list): point at the scrollbar instead.
            Rectangle r = row.getBounds();
            if (list.getBounds().contains(r.getCenterX(), r.getCenterY())) return row;
            return visible(InterfaceID.Minigames.SCROLLBAR);
        }
        for (int id : MINIGAME_SPELLS) {
            Widget spell = visible(id);
            if (spell != null) return spell;
        }
        for (int id : MAGIC_TAB_STONES) {
            Widget stone = visible(id);
            if (stone != null) return stone;
        }
        return null;
    }

    /**
     * Whether the teleport has been taken, or isn't needed: the player is by the landing spot, or
     * already nearer the step's tile than the teleport would put them (e.g. walking from Nightmare
     * Zone to the Dragon Inn).
     */
    private boolean alreadyThere(RouteStep step, TeleportSpell spell) {
        WorldPoint dest = spell.getDestination();
        WorldPoint goal = step.getWorldPoint() != null ? step.getWorldPoint() : dest;
        if (client.getLocalPlayer() == null || goal == null) return false;
        WorldPoint at = client.getLocalPlayer().getWorldLocation();
        if (at.getPlane() == dest.getPlane() && at.distanceTo2D(dest) <= LANDING) return true;
        // A goal through a door or stairs (inside the Blast Furnace) sits thousands of tiles off on
        // the map, which would make anywhere "nearer" than the landing; so only count it close by.
        int fromGoal = at.distanceTo2D(goal);
        return at.getPlane() == goal.getPlane() && fromGoal <= dest.distanceTo2D(goal) + NEAR && fromGoal <= MAX_WALK;
    }

    /** Tiles of slack around the teleport's landing spot. */
    private static final int NEAR = 15;
    /** Around the landing spot, the teleport counts as taken (walking on to the stairs, say). */
    private static final int LANDING = 30;
    /** Further from the step's tile than this, it's never "already there". */
    private static final int MAX_WALK = 300;

    private Widget visible(int componentId) {
        Widget w = client.getWidget(componentId);
        return w == null || w.isHidden() ? null : w;
    }

    private static boolean sameGame(String text, String game) {
        if (text == null) return false;
        // Rows read "Castle Wars<br><col=808080>West of Yanille": the name is the first line
        int br = text.indexOf("<br>");
        String t = Text.removeTags(br < 0 ? text : text.substring(0, br)).trim().replaceFirst("^\\w\\s*[:)]\\s*", "").trim();
        return t.equalsIgnoreCase(game);
    }

    /** The list row (a direct child of the list) holding the minigame's name. */
    private static Widget findRow(Widget list, String game) {
        for (Widget row : children(list)) {
            if (!row.isHidden() && mentions(row, game)) return row;
        }
        return null;
    }

    /** Whether this widget or anything under it shows the minigame's name (as text or as its name). */
    private static boolean mentions(Widget w, String game) {
        if (sameGame(w.getText(), game) || sameGame(w.getName(), game)) return true;
        for (Widget child : children(w)) {
            if (mentions(child, game)) return true;
        }
        return false;
    }

    private static List<Widget> children(Widget w) {
        List<Widget> out = new ArrayList<>();
        for (Widget[] kids : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()}) {
            if (kids == null) continue;
            for (Widget k : kids) if (k != null) out.add(k);
        }
        return out;
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;
import java.util.*;
import java.util.function.Predicate;
import java.util.List;

/**
 * For a Portal Nexus teleport step: highlights the nexus in the player's house, then the
 * step's destination row once the nexus teleport menu is open. For a house portal step:
 * highlights that portal ("Varrock Portal") in the portal chamber.
 * Highlight only: the plugin never clicks the nexus or picks the destination.
 */
@Singleton
public class NexusTeleportOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    // The scene search for the nexus or portal, redone once a game tick rather than every frame
    private List<GameObject> found = Collections.emptyList();
    private RouteStep foundFor;
    private int foundTick = -1;

    @Inject
    public NexusTeleportOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        Predicate<String> object = PortalNexus.houseObjectName(step);
        if (object == null) return null;

        Widget menu = client.getWidget(InterfaceID.TelenexusTeleport.UNIVERSE);
        String dest = step.getTeleportNexus();
        if ("NEXUS".equals(step.getTeleportMethod()) && dest != null && !dest.trim().isEmpty()
                && menu != null && !menu.isHidden()) {
            highlightRow(graphics, dest.trim());
        } else {
            highlightObjects(graphics, step, object);
        }
        return null;
    }

    /** Outline the whole line (text plus its clickable background) that names the destination. */
    private void highlightRow(Graphics2D graphics, String dest) {
        Rectangle[] line = {null};
        PortalNexus.forEachText(client, w -> {
            if (dest.equalsIgnoreCase(PortalNexus.cleanText(w.getText()))) {
                line[0] = line[0] == null ? w.getBounds() : line[0].union(w.getBounds());
            }
        });
        if (line[0] == null) return;
        // Stretch to the menu list's width so it reads as a row highlight, not just the words.
        Widget rows = client.getWidget(InterfaceID.TelenexusTeleport.ROWS1);
        Rectangle b = line[0];
        if (rows != null && !rows.isHidden()) {
            Rectangle r = rows.getBounds();
            b = new Rectangle(r.x, b.y, r.width, b.height);
        }
        HighlightColors.paint(graphics, b, plugin.getConfig().npcHighlightColor());
    }

    private void highlightObjects(Graphics2D graphics, RouteStep step, Predicate<String> nameMatches) {
        if (step != foundFor || client.getTickCount() != foundTick) {
            found = PortalNexus.findObjects(client, nameMatches);
            foundFor = step;
            foundTick = client.getTickCount();
        }
        for (GameObject obj : found) {
            Shape hull = obj.getConvexHull();
            if (hull == null) continue;
            HighlightColors.paint(graphics, hull, plugin.getConfig().npcHighlightColor());
        }
    }
}

package com.routeplanner.teleport;

import lombok.RequiredArgsConstructor;
import com.routeplanner.RoutePlannerConfig;
import com.routeplanner.util.SceneObjects;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.client.config.ConfigManager;
import javax.inject.*;
import java.util.*;

/**
 * Remembers, per character, which spirit tree patches have a grown tree the player can travel
 * from. A farming patch shows each player their own crop, so a grown tree seen in a patch is
 * the player's. Checked whenever a patch is in view, and kept between sessions.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PlantedSpiritTrees {

    private static final String KEY = "plantedSpiritTrees";
    /** How often the patches in view are looked at. */
    private static final int CHECK_TICKS = 5;

    private final Client client;
    private final ConfigManager configManager;

    /** The grown trees' keys ({@link SpiritTrees.Tree#key()}); null until read for this character. */
    private Set<String> grown;
    private String loadedFor;

    /** The trees grown in the player's patches, as far as the player has seen. */
    public Set<String> grown() {
        load();
        return grown == null ? Collections.emptySet() : grown;
    }

    public void onGameTick() {
        if (client.getGameState() != GameState.LOGGED_IN || client.getTickCount() % CHECK_TICKS != 0) return;
        WorldView wv = client.getTopLevelWorldView();
        if (wv == null || wv.isInstance() || wv.getScene() == null) return;
        load();
        if (grown == null) return;
        boolean changed = false;
        for (SpiritTrees.Tree tree : SpiritTrees.plantedTrees()) {
            Boolean ready = treeReady(wv, tree);
            if (ready == null) continue; // not in view
            changed |= ready ? grown.add(tree.key()) : grown.remove(tree.key());
        }
        if (changed) {
            configManager.setRSProfileConfiguration(RoutePlannerConfig.GROUP, KEY, String.join(";", grown));
        }
    }

    /**
     * Whether the patch's tree can be travelled from now; null when the patch isn't in the scene.
     * Each patch has its own object id (the data names them all 8355), so the patch is found as
     * the farming-patch object (one that changes with the player's crop) around the tree's tiles.
     */
    private Boolean treeReady(WorldView wv, SpiritTrees.Tree tree) {
        Tile[][] plane = wv.getScene().getTiles()[wv.getPlane()];
        WorldPoint wp = tree.tiles().get(0);
        if (wp.getPlane() != wv.getPlane()) return null;
        LocalPoint lp = LocalPoint.fromWorld(wv, wp);
        if (lp == null) return null;
        boolean patchSeen = false;
        // The patch stands in the middle of the tiles around it: look a few tiles in
        for (int dx = -3; dx <= 3; dx++) {
            for (int dy = -3; dy <= 3; dy++) {
                int x = lp.getSceneX() + dx, y = lp.getSceneY() + dy;
                if (x < 0 || y < 0 || x >= plane.length || y >= plane[x].length || plane[x][y] == null) continue;
                for (GameObject obj : plane[x][y].getGameObjects()) {
                    if (!SceneObjects.isObject(obj)) continue;
                    ObjectComposition comp = client.getObjectDefinition(obj.getId());
                    if (comp == null || comp.getImpostorIds() == null) continue;
                    patchSeen = true;
                    if (canTravel(comp.getImpostor())) return true;
                }
            }
        }
        return patchSeen ? false : null;
    }

    private static boolean canTravel(ObjectComposition comp) {
        if (comp == null || comp.getActions() == null) return false;
        for (String a : comp.getActions()) if (a != null && a.equalsIgnoreCase("Travel")) return true;
        return false;
    }

    /** Read the saved trees once per character (the RS profile changes when switching characters). */
    private void load() {
        String profile = configManager.getRSProfileKey();
        if (profile == null) {
            grown = null;
            loadedFor = null;
            return;
        }
        if (profile.equals(loadedFor)) return;
        loadedFor = profile;
        grown = new HashSet<>();
        String saved = configManager.getRSProfileConfiguration(RoutePlannerConfig.GROUP, KEY);
        if (saved != null) {
            for (String k : saved.split(";")) if (!k.trim().isEmpty()) grown.add(k.trim());
        }
    }
}

package com.routeplanner.teleport;

import com.routeplanner.util.SceneObjects;
import com.routeplanner.model.RouteStep;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;
import java.awt.Rectangle;
import java.util.*;
import java.util.function.*;

/**
 * Reading the Portal Nexus teleport menu. Each row is a clickable background with its text
 * drawn by a separate widget on the same line, so rows are matched up by position rather than
 * by relying on the menu's internal layout.
 */
public final class PortalNexus {

    private PortalNexus() {}

    public static final int MENU_GROUP = InterfaceID.TelenexusTeleport.UNIVERSE >>> 16;

    private static final String NEXUS_NAME = "portal nexus";

    /**
     * For a step that leaves the house by the nexus or a portal-chamber portal, a test for that
     * object's (lowercase) name; null for any other step.
     */
    public static Predicate<String> houseObjectName(RouteStep step) {
        if (step == null) return null;
        String dest = step.getTeleportNexus();
        if ("NEXUS".equals(step.getTeleportMethod())) return name -> name.startsWith(NEXUS_NAME);
        if ("PORTAL".equals(step.getTeleportMethod()) && dest != null && !dest.trim().isEmpty()) {
            String portal = dest.trim().toLowerCase() + " portal";
            return portal::equals;
        }
        return null;
    }

    /** Game objects on the player's floor whose (lowercase) name matches; built furniture by its impostor. */
    public static List<GameObject> findObjects(Client client, Predicate<String> nameMatches) {
        List<GameObject> found = new ArrayList<>();
        Scene scene = client.getScene();
        if (scene == null) return found;
        Tile[][][] tiles = scene.getTiles();
        int z = client.getPlane();
        if (z < 0 || z >= tiles.length) return found;
        for (Tile[] row : tiles[z]) {
            if (row == null) continue;
            for (Tile tile : row) {
                if (tile == null) continue;
                GameObject[] objects = tile.getGameObjects();
                if (objects == null) continue;
                for (GameObject obj : objects) {
                    if (!SceneObjects.isObject(obj)) continue;
                    // GameObjects span multiple tiles; only count them from the anchor tile
                    if (!obj.getSceneMinLocation().equals(tile.getSceneLocation())) continue;
                    ObjectComposition comp = client.getObjectDefinition(obj.getId());
                    if (comp == null) continue;
                    // Built furniture often uses an impostor (varbit-driven) definition.
                    if (comp.getImpostorIds() != null) {
                        ObjectComposition imp = comp.getImpostor();
                        if (imp != null) comp = imp;
                    }
                    String name = comp.getName();
                    if (name != null && nameMatches.test(name.toLowerCase())) found.add(obj);
                }
            }
        }
        return found;
    }

    /** Menu text looks like "<col=..>1</col> : Varrock"; keep just the destination name. */
    public static String cleanText(String raw) {
        if (raw == null) return null;
        String t = Text.removeTags(raw).trim().replaceFirst("^\\w\\s*[:)]\\s*", "").trim();
        return t.isEmpty() ? null : t;
    }

    /** The destination named on the same line as a clicked menu row, or null. */
    public static String rowText(Client client, Widget clicked) {
        if (clicked == null) return null;
        String own = cleanText(clicked.getText());
        if (own != null) return own;
        Rectangle row = clicked.getBounds();
        if (row == null || row.height <= 0) return null;
        String[] best = {null};
        forEachText(client, w -> {
            Rectangle b = w.getBounds();
            int centerY = b.y + b.height / 2;
            if (centerY < row.y || centerY > row.y + row.height) return;
            String t = cleanText(w.getText());
            // A row can also show its hotkey on its own; the longest text is the name.
            if (t != null && (best[0] == null || t.length() > best[0].length())) best[0] = t;
        });
        return best[0];
    }

    /** Every visible widget with text in the open nexus menu (nothing if it's closed). */
    public static void forEachText(Client client, Consumer<Widget> action) {
        Widget root = client.getWidget(InterfaceID.TelenexusTeleport.UNIVERSE);
        if (root != null && !root.isHidden()) visit(root, action);
    }

    private static void visit(Widget w, Consumer<Widget> action) {
        if (w == null || w.isHidden()) return;
        String text = w.getText();
        if (text != null && !text.isEmpty()) action.accept(w);
        for (Widget[] kids : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()}) {
            if (kids == null) continue;
            for (Widget k : kids) visit(k, action);
        }
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.sailing.Sailing;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.util.Text;
import javax.inject.*;
import java.awt.*;
import java.util.Locale;

/**
 * On a quetzal step: the whistle in the inventory (whistle steps), then the step's landing site on
 * the quetzal map, which Renu and the whistle both open. Renu himself is lit by the NPC highlighter.
 */
@Singleton
public class QuetzalOverlay extends Overlay {

    private static final int[] MAP_ICONS = {InterfaceID.QuetzalMenu.ICONS, InterfaceID.QuetzalwhistleMenu.ICONS};
    private static final int INVENTORY = InterfaceID.Inventory.ITEMS;

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public QuetzalOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (!Quetzals.isQuetzalStep(step) || Quetzals.arrived(step, Sailing.position(client))) return null;

        String site = Quetzals.site(step.getTeleportNexus()).toLowerCase(Locale.ROOT);
        for (int id : MAP_ICONS) {
            Widget icons = client.getWidget(id);
            if (icons == null || icons.isHidden()) continue;
            Widget icon = find(icons, site);
            if (icon != null) highlight(graphics, icon.getBounds());
            return null; // the map is open: the site is the only thing to click
        }

        if (Quetzals.isWhistleStep(step)) {
            Widget inv = client.getWidget(INVENTORY);
            if (inv != null && !inv.isHidden() && inv.getDynamicChildren() != null) {
                for (Widget item : inv.getDynamicChildren()) {
                    if (item != null && !item.isHidden() && Quetzals.isWhistle(item.getItemId())) {
                        highlight(graphics, item.getBounds());
                    }
                }
            }
        }
        return null;
    }

    /** The map icon named after the site (its name or one of its options), searching nested icons too. */
    private static Widget find(Widget parent, String site) {
        for (Widget[] kids : new Widget[][]{parent.getDynamicChildren(), parent.getStaticChildren(), parent.getNestedChildren()}) {
            if (kids == null) continue;
            for (Widget w : kids) {
                if (w == null || w.isHidden()) continue;
                if (names(w, site)) return w;
                Widget deeper = find(w, site);
                if (deeper != null) return deeper;
            }
        }
        return null;
    }

    private static boolean names(Widget w, String site) {
        if (w.getName() != null && Text.removeTags(w.getName()).toLowerCase(Locale.ROOT).contains(site)) return true;
        String[] actions = w.getActions();
        if (actions != null) {
            for (String a : actions) {
                if (a != null && Text.removeTags(a).toLowerCase(Locale.ROOT).contains(site)) return true;
            }
        }
        return false;
    }

    private void highlight(Graphics2D graphics, Rectangle b) {
        if (b == null || b.width <= 0) return;
        Color c = plugin.getConfig().npcHighlightColor();
        HighlightColors.paint(graphics, b, c);
    }
}

package com.routeplanner.teleport;

import com.routeplanner.util.DataFiles;
import com.routeplanner.model.RouteStep;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import java.util.*;

/**
 * Varlamore's quetzal transport: Renu, waiting at each landing site, flies between them, and the
 * Hunter Guild's quetzal whistle calls a quetzal to any of them from anywhere. Both open the same
 * map of landing sites. Read from the pathfinder's quetzals.tsv (sites with an origin are where
 * Renu waits, rows with a destination name the sites).
 */
public final class Quetzals {

    /** Flying with Renu from a landing site. The step's teleportNexus holds the site's name. */
    public static final String METHOD_RENU = "QUETZAL";
    /** Calling a quetzal with the whistle. The step's teleportNexus holds the site's name. */
    public static final String METHOD_WHISTLE = "QUETZAL_WHISTLE";

    public static final String RENU = "Renu";

    /** Every whistle: basic, enhanced, perfected, and the perfected one that never runs out. */
    private static final int[] WHISTLES = {
        ItemID.HG_QUETZALWHISTLE_BASIC, ItemID.HG_QUETZALWHISTLE_ENHANCED,
        ItemID.HG_QUETZALWHISTLE_PERFECTED, ItemID.HG_QUETZALWHISTLE_PERFECTED_INFINITE};

    /** How far from a site a landing still counts as that site. */
    private static final int LANDING_SLACK = 8;

    private static final Map<String, WorldPoint> SITES = new LinkedHashMap<>();
    private static final List<WorldPoint> RENU_TILES = new ArrayList<>();

    static {
        load();
    }

    private Quetzals() {}

    private static void load() {
        for (String[] cols : DataFiles.rowsAt("/com/routeplanner/transports/quetzals.tsv")) {
            if (cols.length < 2) continue;
            WorldPoint origin = DataFiles.point(cols[0]);
            WorldPoint dest = DataFiles.point(cols[1]);
            if (origin != null) {
                if (!RENU_TILES.contains(origin)) RENU_TILES.add(origin);
            } else if (dest != null && cols.length > 5 && !cols[5].trim().isEmpty()) {
                SITES.putIfAbsent(cols[5].trim(), dest);
            }
        }
    }

    /** Every landing site's name, in the data's order. */
    public static List<String> sites() {
        return Collections.unmodifiableList(new ArrayList<>(SITES.keySet()));
    }

    /** The site's name as the data spells it, matched without regard to case; null if unknown. */
    public static String site(String name) {
        if (name == null) return null;
        String n = name.trim().toLowerCase(Locale.ROOT);
        for (String s : SITES.keySet()) if (s.toLowerCase(Locale.ROOT).equals(n)) return s;
        return null;
    }

    /** Where a site's quetzal lands, or null. */
    public static WorldPoint destination(String site) {
        String s = site(site);
        return s == null ? null : SITES.get(s);
    }

    /** The site whose landing spot is at (or next to) {@code landed}, or null. */
    public static String siteAt(WorldPoint landed) {
        if (landed == null) return null;
        String best = null;
        int bestDist = LANDING_SLACK + 1;
        for (Map.Entry<String, WorldPoint> e : SITES.entrySet()) {
            WorldPoint d = e.getValue();
            if (d.getPlane() != landed.getPlane()) continue;
            int dist = d.distanceTo2D(landed);
            if (dist < bestDist) {
                bestDist = dist;
                best = e.getKey();
            }
        }
        return best;
    }

    /** The landing site with Renu closest to {@code from}, or null. */
    public static WorldPoint nearestRenu(WorldPoint from) {
        if (from == null) return null;
        WorldPoint best = null;
        int bestDist = Integer.MAX_VALUE;
        for (WorldPoint t : RENU_TILES) {
            if (t.getPlane() != from.getPlane()) continue;
            int d = t.distanceTo2D(from);
            if (d < bestDist) {
                bestDist = d;
                best = t;
            }
        }
        return best;
    }

    public static boolean isWhistle(int itemId) {
        for (int id : WHISTLES) if (id == itemId) return true;
        return false;
    }

    /** Whether the step flies by quetzal (either way) to a known site. */
    public static boolean isQuetzalStep(RouteStep step) {
        return step != null && (METHOD_RENU.equals(step.getTeleportMethod()) || METHOD_WHISTLE.equals(step.getTeleportMethod()))
            && site(step.getTeleportNexus()) != null;
    }

    public static boolean isRenuStep(RouteStep step) {
        return isQuetzalStep(step) && METHOD_RENU.equals(step.getTeleportMethod());
    }

    public static boolean isWhistleStep(RouteStep step) {
        return isQuetzalStep(step) && METHOD_WHISTLE.equals(step.getTeleportMethod());
    }

    /** Whether the player is already where the step's quetzal goes. */
    public static boolean arrived(RouteStep step, WorldPoint player) {
        WorldPoint dest = destination(step.getTeleportNexus());
        return player != null && dest != null && player.getPlane() == dest.getPlane() && player.distanceTo2D(dest) <= 25;
    }

}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;

/**
 * Highlights the teleport spell in the open spellbook for the active step,
 * when that step is a spell-teleport. Highlight only: never casts or clicks.
 * Spell is matched by its sprite id (from TeleportSpells) against spellbook widgets,
 * which is robust to spellbook child-id shifts.
 */
@Singleton
public class SpellbookOverlay extends Overlay {
    private static final int SPELLBOOK_GROUP = 218;

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public SpellbookOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;

        String spellName = step.getTeleportSpell();
        if (spellName == null || spellName.trim().isEmpty()) return null;

        TeleportSpell spell = TeleportSpells.getByName(spellName);
        if (spell == null) return null;
        int wantSprite = spell.getSpriteId();

        // spellbook must be open
        Widget book = client.getWidget(SPELLBOOK_GROUP, 0);
        if (book == null || book.isHidden()) return null;

        Widget match = findBySprite(book, wantSprite);
        if (match == null || match.isHidden()) return null;

        Rectangle b = match.getBounds();
        if (b == null) return null;

        Color outline = plugin.getConfig().npcHighlightColor();
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        graphics.setColor(HighlightColors.fill(outline));
        graphics.fillRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
        return null;
    }

    /** Depth-first search the spellbook widget tree for a child whose sprite id matches. */
    private Widget findBySprite(Widget root, int spriteId) {
        if (root == null) return null;
        if (root.getSpriteId() == spriteId && !root.isHidden()) return root;
        for (Widget child : allChildren(root)) {
            Widget found = findBySprite(child, spriteId);
            if (found != null) return found;
        }
        return null;
    }

    private Widget[] merge(Widget[] a, Widget[] b) {
        if (a == null) return b == null ? new Widget[0] : b;
        if (b == null) return a;
        Widget[] out = new Widget[a.length + b.length];
        System.arraycopy(a, 0, out, 0, a.length);
        System.arraycopy(b, 0, out, a.length, b.length);
        return out;
    }

    private Widget[] allChildren(Widget w) {
        Widget[] out = merge(w.getStaticChildren(), w.getDynamicChildren());
        out = merge(out, w.getNestedChildren());
        return out == null ? new Widget[0] : out;
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;

/**
 * In a spirit tree's destination menu, for a spirit tree step: highlights the step's destination
 * ("4: Grand Exchange"). The trees use the game's general list menu, in its old or new form.
 */
@Singleton
public class SpiritTreeOverlay extends Overlay {

    /** The list menu's roots: the older one and the newer one. */
    private static final int[] MENUS = {InterfaceID.Menu.LJ_LAYER2, InterfaceID.MenuNew.INFINITE};

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public SpiritTreeOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (!SpiritTrees.isSpiritTreeStep(step)) return null;
        String want = SpiritTrees.destinationName(step.getTeleportNexus());
        for (int id : MENUS) {
            Widget root = client.getWidget(id);
            if (root == null || root.isHidden()) continue;
            Widget row = find(root, want);
            if (row != null) {
                highlight(graphics, row.getBounds());
                return null;
            }
        }
        return null;
    }

    /** The menu line naming the destination, its key ("4:") and colour tags aside. */
    private static Widget find(Widget w, String want) {
        if (w == null || w.isHidden()) return null;
        String text = PortalNexus.cleanText(w.getText());
        if (text != null && text.equalsIgnoreCase(want)) return w;
        for (Widget[] kids : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()}) {
            if (kids == null) continue;
            for (Widget k : kids) {
                Widget found = find(k, want);
                if (found != null) return found;
            }
        }
        return null;
    }

    private void highlight(Graphics2D graphics, Rectangle b) {
        if (b == null || b.width <= 0) return;
        Color c = plugin.getConfig().npcHighlightColor();
        HighlightColors.paint(graphics, b, c);
    }
}

package com.routeplanner.teleport;

import com.routeplanner.util.DataFiles;
import com.routeplanner.model.RouteStep;
import net.runelite.api.coords.WorldPoint;
import java.util.*;

/**
 * Spirit trees: where they stand, and where each of them can send you. Read from the pathfinder's
 * spirit_trees.tsv: rows with an origin are the tiles around a tree (with its object id), rows
 * with a destination name a place in the trees' menu ("4: Grand Exchange").
 */
public final class SpiritTrees {

    /** The teleport method saved on a step; the destination's name is kept in teleportNexus. */
    public static final String METHOD = "SPIRIT_TREE";
    /** How the path's transition names a spirit tree trip: "Spirit tree to Grand Exchange". */
    public static final String TRANSITION_PREFIX = "Spirit tree to ";

    /** The spirit tree farming patch: a tree there only works for whoever planted it. */
    private static final int PLANTED_PATCH = 8355;
    /** The menu's own name for the tree in the player's house. */
    private static final String HOUSE = "Your house";

    /** A tree, by the tiles around it that its Travel option is used from. */
    public static final class Tree {
        public final int objectId;
        public final boolean planted;
        final List<WorldPoint> tiles = new ArrayList<>();

        Tree(int objectId) {
            this.objectId = objectId;
            this.planted = objectId == PLANTED_PATCH;
        }

        /** The tile beside the tree that's closest to {@code from}. */
        public WorldPoint tileNearest(WorldPoint from) {
            WorldPoint best = tiles.get(0);
            for (WorldPoint t : tiles) if (t.distanceTo2D(from) < best.distanceTo2D(from)) best = t;
            return best;
        }

        /** The tiles around the tree. */
        public List<WorldPoint> tiles() {
            return Collections.unmodifiableList(tiles);
        }

        /** Names the tree for saving: its first tile, "x,y,plane". */
        public String key() {
            WorldPoint t = tiles.get(0);
            return t.getX() + "," + t.getY() + "," + t.getPlane();
        }

        int distanceTo(WorldPoint from) {
            return tileNearest(from).distanceTo2D(from);
        }
    }

    private static final Map<String, WorldPoint> DESTINATIONS = new LinkedHashMap<>();
    private static final List<Tree> TREES = new ArrayList<>();

    static {
        load();
    }

    private SpiritTrees() {}

    private static void load() {
        for (String[] cols : DataFiles.rowsAt("/com/routeplanner/transports/spirit_trees.tsv")) {
            if (cols.length < 2) continue;
            WorldPoint origin = DataFiles.point(cols[0]);
            WorldPoint dest = DataFiles.point(cols[1]);
            if (origin != null && cols.length > 2) {
                addTreeTile(origin, FairyRings.objectId(cols[2]));
            } else if (dest != null && cols.length > 6) {
                String name = menuName(cols[6]);
                // The house is an instance: its tree's row has no tile worth walking to
                if (name != null) DESTINATIONS.putIfAbsent(name, HOUSE.equalsIgnoreCase(name) ? TeleportItems.HOUSE : dest);
            }
        }
    }

    /** A tile around a tree joins the tree with the same object id it's next to, or starts one. */
    private static void addTreeTile(WorldPoint tile, int objectId) {
        for (Tree t : TREES) {
            if (t.objectId == objectId && t.tiles.get(0).getPlane() == tile.getPlane() && t.distanceTo(tile) <= 6) {
                t.tiles.add(tile);
                return;
            }
        }
        Tree t = new Tree(objectId);
        t.tiles.add(tile);
        TREES.add(t);
    }

    /** "4: Grand Exchange" -> "Grand Exchange". */
    static String menuName(String display) {
        if (display == null) return null;
        String n = display.trim().replaceFirst("^\\w\\s*:\\s*", "").trim();
        return n.isEmpty() ? null : n;
    }

    /** Every destination's name, in the menu's order. */
    public static List<String> destinations() {
        return Collections.unmodifiableList(new ArrayList<>(DESTINATIONS.keySet()));
    }

    /** The destination's name as the menu spells it, matched without regard to case; null if unknown. */
    public static String destinationName(String name) {
        if (name == null) return null;
        String n = name.trim().toLowerCase(Locale.ROOT);
        for (String d : DESTINATIONS.keySet()) if (d.toLowerCase(Locale.ROOT).equals(n)) return d;
        return null;
    }

    /** Where a destination lands (the house marker for "Your house"), or null. */
    public static WorldPoint destination(String name) {
        String d = destinationName(name);
        return d == null ? null : DESTINATIONS.get(d);
    }

    /** The destination landing at (or next to) {@code landed}, or null. */
    public static String destinationAt(WorldPoint landed) {
        if (landed == null) return null;
        String best = null;
        int bestDist = 9;
        for (Map.Entry<String, WorldPoint> e : DESTINATIONS.entrySet()) {
            WorldPoint d = e.getValue();
            if (d.getPlane() != landed.getPlane() || TeleportItems.isHouse(d)) continue;
            int dist = d.distanceTo2D(landed);
            if (dist < bestDist) {
                bestDist = dist;
                best = e.getKey();
            }
        }
        return best;
    }

    /**
     * The tree closest to {@code from} on the same floor, or null. Trees grown in farming patches
     * are left out: they only work for whoever planted them, and the route can't tell whose they are.
     */
    public static Tree nearest(WorldPoint from) {
        return nearest(from, Collections.emptySet());
    }

    /** Like {@link #nearest(WorldPoint)}, but planted trees in {@code grown} (by key) count too. */
    public static Tree nearest(WorldPoint from, java.util.Set<String> grown) {
        if (from == null) return null;
        Tree best = null;
        int bestDist = Integer.MAX_VALUE;
        for (Tree t : TREES) {
            if ((t.planted && !grown.contains(t.key())) || t.tiles.get(0).getPlane() != from.getPlane()) continue;
            int d = t.distanceTo(from);
            if (d < bestDist) {
                bestDist = d;
                best = t;
            }
        }
        return best;
    }

    /** The trees grown in farming patches. */
    public static List<Tree> plantedTrees() {
        List<Tree> out = new ArrayList<>();
        for (Tree t : TREES) if (t.planted) out.add(t);
        return out;
    }

    public static boolean isSpiritTreeStep(RouteStep step) {
        return step != null && METHOD.equals(step.getTeleportMethod()) && destination(step.getTeleportNexus()) != null;
    }

    /** Whether an object's (lowercase) name is a spirit tree: a plain one, or the house's tree that's also a fairy ring. */
    public static boolean isTreeName(String lowerName) {
        return lowerName != null && (lowerName.contains("spirit tree") || lowerName.contains("spiritual fairy tree"));
    }

}

package com.routeplanner.teleport;

import lombok.*;
import net.runelite.api.coords.WorldPoint;

/**
 * A jewellery/item teleport destination. Unlike spells, a single physical item
 * (e.g. Amulet of glory) has multiple charge states, any of which can teleport;
 * chargeIds lists every item id that should be highlighted in the inventory.
 * iconId is the id used to render the picker icon (highest charge, the "full" look).
 * Highlight only: the plugin never clicks or operates the item.
 */
@Getter
@RequiredArgsConstructor
public class TeleportItem {
    private final String displayName;   // e.g. "Amulet of glory: Edgeville"
    private final String itemName;      // e.g. "Amulet of glory" (base item, for grouping)
    private final int[] chargeIds;      // all item ids to match in inventory (any charge)
    private final int iconId;           // item id to render as the picker icon
    private final WorldPoint destination;

    /** True if the given inventory item id is one of this teleport's charge states. */
    public boolean matchesItemId(int id) {
        for (int c : chargeIds) if (c == id) return true;
        return false;
    }

    @Override
    public String toString() {
        return displayName;
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import com.routeplanner.util.HighlightColors;
import net.runelite.api.*;
import net.runelite.api.gameval.*;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import javax.inject.*;
import java.awt.*;
import net.runelite.api.gameval.InventoryID;

/**
 * Highlights a teleport item in the inventory, or in the equipment tab when it's worn (e.g. a
 * construction cape), for the active step, when that step is an item-teleport. Matches ANY
 * charge state the player is holding (e.g. glory(3) or glory(6)).
 * Highlight only: the plugin never clicks or operates the item.
 */
@Singleton
public class TeleportItemOverlay extends Overlay {
    // Inventory widget group; children carry per-slot item ids and bounds.
    private static final int INVENTORY_GROUP = 149;

    /** Equipment tab slot widgets, indexed by EquipmentInventorySlot index (gaps are unused). */
    private static final int[] WORN_SLOT_WIDGETS = new int[14];
    static {
        WORN_SLOT_WIDGETS[0] = InterfaceID.Wornitems.SLOT0;    // head
        WORN_SLOT_WIDGETS[1] = InterfaceID.Wornitems.SLOT1;    // cape
        WORN_SLOT_WIDGETS[2] = InterfaceID.Wornitems.SLOT2;    // amulet
        WORN_SLOT_WIDGETS[3] = InterfaceID.Wornitems.SLOT3;    // weapon
        WORN_SLOT_WIDGETS[4] = InterfaceID.Wornitems.SLOT4;    // body
        WORN_SLOT_WIDGETS[5] = InterfaceID.Wornitems.SLOT5;    // shield
        WORN_SLOT_WIDGETS[7] = InterfaceID.Wornitems.SLOT7;    // legs
        WORN_SLOT_WIDGETS[9] = InterfaceID.Wornitems.SLOT9;    // gloves
        WORN_SLOT_WIDGETS[10] = InterfaceID.Wornitems.SLOT10;  // boots
        WORN_SLOT_WIDGETS[12] = InterfaceID.Wornitems.SLOT12;  // ring
        WORN_SLOT_WIDGETS[13] = InterfaceID.Wornitems.SLOT13;  // ammo
    }

    private final Client client;
    private final RoutePlannerPlugin plugin;

    @Inject
    public TeleportItemOverlay(Client client, RoutePlannerPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;

        String itemTele = step.getTeleportItem();
        if (itemTele == null || itemTele.trim().isEmpty()) return null;

        TeleportItem tele = TeleportItems.getByDisplayName(itemTele);
        if (tele == null) return null;

        Widget inv = client.getWidget(INVENTORY_GROUP, 0);
        if (inv != null && !inv.isHidden()) {
            for (Widget item : inventoryItemWidgets(inv)) {
                if (item == null || item.isHidden()) continue;
                if (tele.matchesItemId(item.getItemId())) highlight(graphics, item.getBounds());
            }
        }

        // Worn items: the equipment tab's slot widgets don't carry item ids, so match the
        // worn-items container and highlight that slot's widget (only drawn while the tab is open).
        ItemContainer worn = client.getItemContainer(InventoryID.WORN);
        if (worn != null) {
            Item[] items = worn.getItems();
            for (int slot = 0; slot < items.length && slot < WORN_SLOT_WIDGETS.length; slot++) {
                if (WORN_SLOT_WIDGETS[slot] == 0 || !tele.matchesItemId(items[slot].getId())) continue;
                Widget w = client.getWidget(WORN_SLOT_WIDGETS[slot]);
                if (w != null && !w.isHidden()) highlight(graphics, w.getBounds());
            }
        }
        return null;
    }

    private void highlight(Graphics2D graphics, Rectangle b) {
        HighlightColors.paintSlot(graphics, b, plugin.getConfig().npcHighlightColor());
    }

    /** Inventory item slots live as dynamic children of the inventory widget. */
    private Widget[] inventoryItemWidgets(Widget inv) {
        Widget[] dyn = inv.getDynamicChildren();
        if (dyn != null && dyn.length > 0) return dyn;
        Widget[] child = inv.getChildren();
        return child == null ? new Widget[0] : child;
    }
}

package com.routeplanner.teleport;

import lombok.RequiredArgsConstructor;
import com.routeplanner.util.*;
import net.runelite.api.coords.WorldPoint;
import java.util.*;

/**
 * Item-teleport data. Each entry is one pickable destination; entries for the same
 * physical item share the same chargeIds set (all charge states) and iconId.
 * The hand-made entries are in teleport_items.tsv.
 */
public class TeleportItems {

    /**
     * Marker destination for teleports into the player-owned house. The house is an instance,
     * so it has no real tile; matches "Teleport to House" in TeleportSpells.
     */
    public static final WorldPoint HOUSE = new WorldPoint(0, 0, 0);

    /** Where the data puts the inside of the house (the template's tile): read as {@link #HOUSE}. */
    private static final WorldPoint DATA_HOUSE = new WorldPoint(1923, 5709, 0);

    /** The hand-made entries: their names are what saved routes refer to, so they stay as they are. */
    private static final List<TeleportItem> HAND = DataFiles.load("teleport_items.tsv", r -> new TeleportItem(r[0], r[1], DataFiles.ints(r[2]), DataFiles.num(r[3]),
        "house".equals(r[4]) ? HOUSE : DataFiles.point(r[4])));

    /**
     * Every item teleport: the hand-made ones, then every other one in the pathfinder's
     * teleportation_items.tsv (diary rewards, capes, tablets, scrolls...).
     */
    public static final List<TeleportItem> ALL = build();

    private static List<TeleportItem> build() {
        List<TeleportItem> all = new ArrayList<>(HAND);
        Set<String> names = new HashSet<>();
        for (TeleportItem h : HAND) names.add(h.getDisplayName());
        for (TeleportItem it : load()) {
            if (coveredByHand(it)) continue;
            // A name the hand-made list already uses, for somewhere else: add the place to it
            if (!names.add(it.getDisplayName())) {
                String placed = it.getDisplayName() + " (" + LocationNames.describe(it.getDestination()) + ")";
                if (!names.add(placed)) continue;
                it = new TeleportItem(placed, it.getItemName(), it.getChargeIds(), it.getIconId(), it.getDestination());
            }
            all.add(it);
        }
        return Collections.unmodifiableList(all);
    }

    /**
     * The data's rows, one per name. Rows sharing a name and landing spot (charge or tier
     * variants) become one entry for all their items; a name that lands in several places
     * (the house's outside portal, wherever it was built) gets the place added to it.
     */
    static List<TeleportItem> load() {
        List<Row> rows = new ArrayList<>();
        for (String[] cols : DataFiles.rowsAt("/com/routeplanner/transports/teleportation_items.tsv")) {
            if (cols.length < 7) continue;
            WorldPoint dest = DataFiles.point(cols[0]);
            String name = cols[6].trim();
            int[] ids = itemIds(cols[3]);
            if (dest == null || name.isEmpty() || ids.length == 0) continue;
            rows.add(new Row(name, dest.equals(DATA_HOUSE) ? HOUSE : dest, ids));
        }

        // Group by name, then by landing spot within the name
        Map<String, Map<WorldPoint, Set<Integer>>> byName = new LinkedHashMap<>();
        for (Row r : rows) {
            Set<Integer> ids = byName.computeIfAbsent(r.name, k -> new LinkedHashMap<>())
                .computeIfAbsent(r.dest, k -> new LinkedHashSet<>());
            for (int id : r.ids) ids.add(id);
        }
        List<TeleportItem> out = new ArrayList<>();
        for (Map.Entry<String, Map<WorldPoint, Set<Integer>>> e : byName.entrySet()) {
            String name = e.getKey();
            boolean several = e.getValue().size() > 1;
            int colon = name.indexOf(':');
            String itemName = colon > 0 ? name.substring(0, colon).trim() : name;
            for (Map.Entry<WorldPoint, Set<Integer>> d : e.getValue().entrySet()) {
                int[] ids = d.getValue().stream().mapToInt(Integer::intValue).toArray();
                String display = several && !isHouse(d.getKey()) ? name + " (" + LocationNames.describe(d.getKey()) + ")" : name;
                out.add(new TeleportItem(display, itemName, ids, ids[0], d.getKey()));
            }
        }
        return out;
    }

    /** A data entry the hand-made list already has: one of the same items, landing in the same place. */
    private static boolean coveredByHand(TeleportItem it) {
        for (TeleportItem h : HAND) {
            boolean sameItem = false;
            for (int id : it.getChargeIds()) if (h.matchesItemId(id)) { sameItem = true; break; }
            if (!sameItem) continue;
            if (isHouse(h.getDestination()) || isHouse(it.getDestination())) {
                if (isHouse(h.getDestination()) && isHouse(it.getDestination())) return true;
                continue;
            }
            if (h.getDestination().getPlane() == it.getDestination().getPlane()
                && h.getDestination().distanceTo2D(it.getDestination()) <= 10) return true;
        }
        return false;
    }

    @RequiredArgsConstructor
    private static final class Row {
        final String name;
        final WorldPoint dest;
        final int[] ids;

    }

    /** "13121=1||13122=1" -> {13121, 13122}. */
    static int[] itemIds(String items) {
        List<Integer> ids = new ArrayList<>();
        for (String alt : items.split("\\|\\|")) {
            String id = alt.split("=")[0].trim();
            if (id.isEmpty()) continue;
            try {
                ids.add(Integer.parseInt(id));
            } catch (NumberFormatException ignored) {
                // not an item id
            }
        }
        return ids.stream().mapToInt(Integer::intValue).toArray();
    }

    /** Whether a teleport destination is the player's house, which has no fixed world tile. */
    public static boolean isHouse(WorldPoint dest) {
        return dest != null && dest.getX() == 0 && dest.getY() == 0;
    }

    public static TeleportItem getByDisplayName(String name) {
        return ALL.stream().filter(t -> t.getDisplayName().equals(name)).findFirst().orElse(null);
    }
}

package com.routeplanner.teleport;

import com.routeplanner.RoutePlannerPlugin;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;

/** The teleport choosers (spell, item, Portal Nexus), used by the step editor. */
public final class TeleportPickers {

    private static final Map<Integer, BufferedImage> SPRITES = new HashMap<>();

    private TeleportPickers() {}

    /** A spell's spellbook icon at 20px; null until it loads, then {@code onLoaded} runs. */
    public static Icon spellIcon(RoutePlannerPlugin plugin, TeleportSpell sp, Runnable onLoaded) {
        Integer key = sp.getSpriteId();
        BufferedImage cached = SPRITES.get(key);
        if (cached != null) return new ImageIcon(cached.getScaledInstance(20, 20, Image.SCALE_SMOOTH));
        try {
            plugin.getSpriteManager().getSpriteAsync(sp.getSpriteId(), 0, img -> {
                if (img != null) {
                    SPRITES.put(key, img);
                    SwingUtilities.invokeLater(onLoaded);
                }
            });
        } catch (RuntimeException ignored) {
            // no icon is fine; the name still shows
        }
        return null;
    }

    /** A teleport item's inventory icon at 20px, or null. */
    public static Icon itemIcon(RoutePlannerPlugin plugin, TeleportItem it) {
        try {
            BufferedImage img = plugin.getItemManager().getImage(it.getIconId());
            return img != null ? new ImageIcon(img.getScaledInstance(20, 20, Image.SCALE_SMOOTH)) : null;
        } catch (Exception ex) {
            return null;
        }
    }

}

