package com.routeplanner.ui;

import javax.swing.*;
import java.awt.*;
import java.util.*;
import java.util.List;

/**
 * Word-wrapped text at a fixed width, drawn directly: much cheaper than an HTML JLabel, which
 * parses and lays out a whole HTML document per label.
 */
public class WrapLabel extends JComponent {

    private final String text;
    private final int wrapWidth;
    private List<String> lines;
    private FontMetrics linesFor;

    public WrapLabel(String text, int wrapWidth) {
        this.text = text == null ? "" : text;
        this.wrapWidth = wrapWidth;
        setFont(UIManager.getFont("Label.font"));
        setForeground(UIManager.getColor("Label.foreground"));
    }

    private List<String> lines(FontMetrics fm) {
        if (lines != null && fm == linesFor) return lines;
        lines = wrap(text, fm, wrapWidth);
        linesFor = fm;
        return lines;
    }

    /** {@code text} broken into lines no wider than {@code width} (a too-long word gets its own line). */
    public static List<String> wrap(String text, FontMetrics fm, int width) {
        List<String> out = new ArrayList<>();
        StringBuilder line = new StringBuilder();
        for (String word : (text == null ? "" : text).split(" ")) {
            if (word.isEmpty()) continue;
            String tryLine = line.length() == 0 ? word : line + " " + word;
            if (line.length() > 0 && fm.stringWidth(tryLine) > width) {
                out.add(line.toString());
                line.setLength(0);
                line.append(word);
            } else {
                line.setLength(0);
                line.append(tryLine);
            }
        }
        if (line.length() > 0 || out.isEmpty()) out.add(line.toString());
        return out;
    }

    @Override
    public Dimension getPreferredSize() {
        if (isPreferredSizeSet()) return super.getPreferredSize();
        FontMetrics fm = getFontMetrics(getFont());
        return new Dimension(wrapWidth, lines(fm).size() * fm.getHeight());
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        // Same text smoothing as a JLabel gets.
        Object hints = Toolkit.getDefaultToolkit().getDesktopProperty("awt.font.desktophints");
        if (hints instanceof Map) g2.addRenderingHints((Map<?, ?>) hints);
        g2.setFont(getFont());
        g2.setColor(getForeground());
        FontMetrics fm = getFontMetrics(getFont());
        List<String> ls = lines(fm);
        int y = (getHeight() - ls.size() * fm.getHeight()) / 2 + fm.getAscent();
        for (String l : ls) {
            g2.drawString(l, 0, y);
            y += fm.getHeight();
        }
        g2.dispose();
    }
}

package com.routeplanner.util;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.Function;

/** Reads the plugin's tab-separated data files (blank lines and "#" comments are skipped). */
@Slf4j
public final class DataFiles {

    private DataFiles() {}

    /** The rows of a file under /com/routeplanner/data/, each split on tabs. */
    public static List<String[]> rows(String file) {
        return rowsAt("/com/routeplanner/data/" + file);
    }

    /** The rows of any resource, by its full path. Missing files read as empty. */
    public static List<String[]> rowsAt(String path) {
        List<String[]> out = new ArrayList<>();
        try (InputStream is = DataFiles.class.getResourceAsStream(path)) {
            if (is == null) {
                log.warn("Route Planner: {} missing", path);
                return out;
            }
            BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8));
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty() || line.startsWith("#")) continue;
                out.add(line.split("\t", -1));
            }
        } catch (IOException e) {
            log.warn("Route Planner: couldn't read {}", path, e);
        }
        return out;
    }

    /** Every row of a file under /com/routeplanner/data/, made into an entry. */
    public static <T> List<T> load(String file, Function<String[], T> entry) {
        List<T> out = new ArrayList<>();
        for (String[] r : rows(file)) out.add(entry.apply(r));
        return Collections.unmodifiableList(out);
    }

    /** "x y plane" as a tile; null if blank or not three numbers. */
    public static WorldPoint point(String s) {
        if (s == null) return null;
        String[] p = s.trim().split("\\s+");
        if (p.length != 3) return null;
        try {
            return new WorldPoint(Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2]));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /** "1,2,3" as numbers. */
    public static int[] ints(String s) {
        String[] p = s.split(",");
        int[] out = new int[p.length];
        for (int i = 0; i < p.length; i++) out[i] = Integer.parseInt(p[i].trim());
        return out;
    }

    public static int num(String s) {
        return Integer.parseInt(s.trim());
    }

    public static double dec(String s) {
        return Double.parseDouble(s.trim());
    }

    /** The column, or "" past the row's end (trailing blank columns may be left off). */
    public static String col(String[] r, int i) {
        return i < r.length ? r[i] : "";
    }
}

package com.routeplanner.util;

import java.util.*;

/** Herb names, so a step can say "Any herb" instead of naming the one that was grown. */
public final class Herbs {

    /** What an item list writes for any grimy or clean herb. */
    public static final String ANY_HERB = "Any herb";

    private static final Set<String> CLEAN = new HashSet<>(Arrays.asList(
        "guam leaf", "marrentill", "tarromin", "harralander", "ranarr weed", "toadflax", "irit leaf",
        "avantoe", "kwuarm", "huasca", "snapdragon", "cadantine", "lantadyme", "dwarf weed", "torstol"));

    private Herbs() {}

    /** True for a grimy or clean herb ("Grimy torstol", "Torstol"); any case. */
    public static boolean isHerb(String name) {
        if (name == null) return false;
        String n = name.trim().toLowerCase();
        if (n.startsWith("grimy ")) n = n.substring("grimy ".length());
        return CLEAN.contains(n);
    }

    public static boolean isGrimy(String name) {
        return name != null && name.trim().toLowerCase().startsWith("grimy ") && isHerb(name);
    }
}

package com.routeplanner.util;

import net.runelite.client.util.ColorUtil;
import java.awt.*;

/** Shared look for in-game highlights, all driven by the "NPC/Object Highlight Color" setting. */
public final class HighlightColors {

    private HighlightColors() {}

    /** The translucent fill for a highlight outlined in {@code outline} (same as object highlights). */
    public static Color fill(Color outline) {
        int a = Math.max(0, Math.min(255, (int) (outline.getAlpha() * 0.22)));
        return ColorUtil.colorWithAlpha(outline, a);
    }

    /** Fills a shape with the translucent fill and outlines it. */
    public static void paint(Graphics2D graphics, Shape shape, Color outline) {
        graphics.setColor(fill(outline));
        graphics.fill(shape);
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.draw(shape);
    }

    /** Outlines an inventory slot, then washes it with the translucent fill. */
    public static void paintSlot(Graphics2D graphics, Rectangle b, Color outline) {
        if (b == null) return;
        graphics.setColor(outline);
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(b.x, b.y, b.width, b.height);
        graphics.setColor(fill(outline));
        graphics.fillRect(b.x, b.y, b.width, b.height);
    }

    /** Text made safe to put inside a Swing HTML label. */
    public static String escapeHtml(String s) {
        return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.routeplanner.util;

import net.runelite.api.coords.WorldPoint;
import java.util.List;

/**
 * Common names for places, so recorded steps read "Go to Varrock" instead of raw coordinates.
 *
 * Each place is a centre tile plus a radius (in tiles, square). When areas overlap, the
 * smallest one containing the tile wins, so "Grand Exchange" beats "Varrock". Centres are
 * approximate surface positions; anything that matches nothing (dungeons, the wilderness,
 * unlisted spots) falls back to coordinates, and every name can be edited in the review.
 */
public final class LocationNames {

    private LocationNames() {}

    private static final class Place {
        final String name;
        final int x, y, radius;
        Place(String name, int x, int y, int radius) {
            this.name = name; this.x = x; this.y = y; this.radius = radius;
        }
    }

    private static final List<Place> PLACES = DataFiles.load("location_names.tsv", r -> new Place(r[0], DataFiles.num(r[1]), DataFiles.num(r[2]), DataFiles.num(r[3])));

    /** The best-known name for a tile, or null when it isn't in any listed place. */
    public static String nameOf(WorldPoint p) {
        if (p == null) return null;
        Place best = null;
        for (Place place : PLACES) {
            int d = Math.max(Math.abs(p.getX() - place.x), Math.abs(p.getY() - place.y));
            if (d <= place.radius && (best == null || place.radius < best.radius)) best = place;
        }
        return best == null ? null : best.name;
    }

    /**
     * " at Lunar Isle" for a step name, or nothing where the map has no name for the spot (most of
     * the open sea), since raw coordinates make a messy name.
     */
    public static String at(WorldPoint p) {
        String name = p == null ? null : nameOf(p);
        return name != null ? " at " + name : "";
    }

    /** A place name if known, otherwise "x, y". */
    public static String describe(WorldPoint p) {
        String name = nameOf(p);
        return name != null ? name : p.getX() + ", " + p.getY();
    }
}

package com.routeplanner.util;

import java.util.*;

/**
 * Matching NPCs against a step's target text: comma-separated NPCs, each with / for alternatives,
 * e.g. "Rommik,Shop assistant/Shop keeper". Case doesn't matter, and a name that starts with a
 * target followed by a space or "(" matches too, so "Guard" also matches "Guard captain".
 */
public final class NpcNames {

    private NpcNames() {
    }

    /** The target's names, trimmed and lower-cased; parse once and reuse when matching many NPCs. */
    public static List<String> parse(String target) {
        List<String> names = new ArrayList<>();
        if (target == null) return names;
        for (String entry : target.split(",")) {
            for (String alt : entry.split("/")) {
                String t = alt.trim().toLowerCase();
                if (!t.isEmpty()) names.add(t);
            }
        }
        return names;
    }

    /** Whether an NPC's name matches one of the parsed target names. */
    public static boolean matches(List<String> targets, String npcName) {
        if (npcName == null) return false;
        String lower = npcName.toLowerCase();
        for (String t : targets) {
            if (lower.equals(t) || lower.startsWith(t + " ") || lower.startsWith(t + "(")) return true;
        }
        return false;
    }

    /** The parsed target an NPC's name equals (not just starts with), or null. */
    public static String exactTarget(List<String> targets, String npcName) {
        if (npcName == null) return null;
        String lower = npcName.toLowerCase();
        for (String t : targets) {
            if (lower.equals(t)) return t;
        }
        return null;
    }

    /**
     * Like {@link #matches(List, String)}, but a target in {@code exactNearby} (one an NPC nearby is
     * named exactly) no longer matches longer names: with Shantay standing there, "Shantay" doesn't
     * also light every "Shantay Guard".
     */
    public static boolean matches(List<String> targets, String npcName, Set<String> exactNearby) {
        if (npcName == null) return false;
        String lower = npcName.toLowerCase();
        for (String t : targets) {
            if (lower.equals(t)) return true;
            if (!exactNearby.contains(t) && (lower.startsWith(t + " ") || lower.startsWith(t + "("))) return true;
        }
        return false;
    }

    public static boolean matches(String target, String npcName) {
        return matches(parse(target), npcName);
    }
}

package com.routeplanner.util;

import com.google.gson.*;
import com.google.gson.reflect.TypeToken;
import com.routeplanner.model.*;
import net.runelite.api.coords.WorldPoint;
import java.lang.reflect.Type;
import java.util.*;

public class RouteSerializer {

    private RouteSerializer() {
    }

    public static String toJson(List<Route> routes, Gson gson) {
        return gson.toJson(routes);
    }

    /**
     * Parses saved routes. Empty input is an empty list, but text that doesn't parse throws: an
     * empty list there would look like "no routes" and the next save would overwrite them.
     */
    public static List<Route> fromJson(String json, Gson gson) {
        if (json == null || json.isEmpty()) return new ArrayList<>();
        Type listType = new TypeToken<List<Route>>(){}.getType();
        List<Route> loaded = gson.fromJson(json, listType);
        if (loaded == null) return new ArrayList<>();
        for (Route r : loaded) r.migrateIfNeeded();
        return loaded;
    }

    /**
     * A copy of the route to give to other people (export, the Route Hub): the steps and their ticks,
     * without this player's progress on them (account, inventory counts, XP, kills, catches).
     */
    public static Route shareableCopy(Route route, Gson gson) {
        Route copy = gson.fromJson(gson.toJson(route), Route.class);
        copy.migrateIfNeeded();
        for (RouteStep step : copy.getAllSteps()) {
            step.resetProgress();
            step.setSkillingStartXp(0);
        }
        return copy;
    }

    public static class WorldPointAdapter implements JsonSerializer<WorldPoint>, JsonDeserializer<WorldPoint> {
        @Override
        public JsonElement serialize(WorldPoint src, Type typeOfSrc, JsonSerializationContext ctx) {
            JsonObject obj = new JsonObject();
            obj.addProperty("x", src.getX());
            obj.addProperty("y", src.getY());
            obj.addProperty("plane", src.getPlane());
            return obj;
        }

        @Override
        public WorldPoint deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext ctx) {
            JsonObject obj = json.getAsJsonObject();
            return new WorldPoint(
                obj.get("x").getAsInt(),
                obj.get("y").getAsInt(),
                obj.get("plane").getAsInt()
            );
        }
    }
}

package com.routeplanner.util;

import java.util.regex.Pattern;

/**
 * Validates user-entered route text. Its main job is to keep links out of any free-text field --
 * route names, section names, step names, and note text, so shared routes cannot be used to point
 * players at external sites. Enforced at creation time (the step editor) and again at import time
 * (the Route Hub), because imported JSON cannot be assumed to have passed through the editor.
 *
 * <p>The link check is deliberately moderate: it catches obvious URLs and common chat-invite shapes,
 * not exotic obfuscation. Determined obfuscation is caught by human review of Route Hub submissions
 * and by the standing "community content" warning, not by regex.
 */
public final class RouteTextValidator {

    private RouteTextValidator() {}

    // http:// or https:// followed by something
    private static final Pattern SCHEME = Pattern.compile("(?i)\\bhttps?://\\S+");
    // www.something
    private static final Pattern WWW = Pattern.compile("(?i)\\bwww\\.\\S+");
    // a bare domain like example.com / foo.gg / bar.io, with a known-ish TLD, optionally with a path.
    // Kept to a curated TLD list so ordinary text ("meet at lvl.99", "1.5m gp") does not trip it.
    private static final Pattern BARE_DOMAIN = Pattern.compile(
        "(?i)\\b[a-z0-9][a-z0-9-]{0,62}\\.(?:com|net|org|io|gg|gved|co|me|tv|xyz|link|site|shop|store|"
        + "info|app|dev|discord|invite)\\b(?:/\\S*)?");
    // explicit well-known invite/link shapes
    private static final Pattern KNOWN = Pattern.compile(
        "(?i)\\b(?:discord\\.gg|discord\\.com/invite|discordapp\\.com/invite|t\\.me|bit\\.ly|"
        + "tinyurl\\.com|youtu\\.be)\\b");

    /** @return true if the text appears to contain a web link or invite. */
    public static boolean containsLink(String text) {
        if (text == null || text.isEmpty()) return false;
        return SCHEME.matcher(text).find()
            || WWW.matcher(text).find()
            || KNOWN.matcher(text).find()
            || BARE_DOMAIN.matcher(text).find();
    }

    /**
     * Check a single field. Returns null if OK, or a short user-facing error message if not.
     * @param label human name of the field, used in the message (e.g. "Step name", "Note")
     */
    public static String checkField(String label, String text) {
        if (containsLink(text)) {
            return label + " can't contain a web link. Please remove it.";
        }
        return null;
    }
}

package com.routeplanner.util;

import net.runelite.api.*;

/** Helpers for reading objects out of the scene. */
public final class SceneObjects {

    private SceneObjects() {}

    /**
     * Whether a tile's game object is a real object. The scene also lists the players and NPCs
     * standing on a tile among its game objects, and their ids can match an object's (a player
     * would light up as a "Crate").
     */
    public static boolean isObject(GameObject obj) {
        return obj != null && !(obj.getRenderable() instanceof Actor);
    }
}

package com.routeplanner.util;

import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import java.util.*;

/**
 * A short walk over the loaded scene's own collision data. Works where the world map pathfinders
 * can't, inside instances such as the player's house, whose tiles aren't in any static map.
 */
public final class ScenePath {

    private ScenePath() {}

    // N, S, E, W: step, the wall flag on the tile being left
    private static final int[][] DIRS = {
        {0, 1, CollisionDataFlag.BLOCK_MOVEMENT_NORTH},
        {0, -1, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH},
        {1, 0, CollisionDataFlag.BLOCK_MOVEMENT_EAST},
        {-1, 0, CollisionDataFlag.BLOCK_MOVEMENT_WEST},
    };

    /**
     * Tiles from the player's scene tile to one beside any of {@code objects}, or an empty list when
     * already there or no way is found. The path starts with the player's own tile.
     */
    public static List<WorldPoint> toObjects(WorldView wv, int startX, int startY, List<GameObject> objects) {
        int plane = wv.getPlane();
        CollisionData[] maps = wv.getCollisionMaps();
        if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null) return Collections.emptyList();
        int[][] flags = maps[plane].getFlags();
        int w = flags.length, h = flags[0].length;
        if (!inside(startX, startY, w, h)) return Collections.emptyList();

        // Goals: the ring of tiles around each object's footprint.
        boolean[][] goal = new boolean[w][h];
        for (GameObject obj : objects) {
            int minX = obj.getSceneMinLocation().getX(), minY = obj.getSceneMinLocation().getY();
            int maxX = obj.getSceneMaxLocation().getX(), maxY = obj.getSceneMaxLocation().getY();
            for (int x = minX - 1; x <= maxX + 1; x++) {
                for (int y = minY - 1; y <= maxY + 1; y++) {
                    boolean footprint = x >= minX && x <= maxX && y >= minY && y <= maxY;
                    if (!footprint && inside(x, y, w, h)) goal[x][y] = true;
                }
            }
        }
        if (goal[startX][startY]) return Collections.emptyList();

        int[] prev = new int[w * h];
        Arrays.fill(prev, -1);
        int start = startX * h + startY;
        prev[start] = start;
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.add(start);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            int x = cur / h, y = cur % h;
            if (goal[x][y]) return walkBack(wv, prev, cur, h, plane);
            for (int[] d : DIRS) {
                int nx = x + d[0], ny = y + d[1];
                if (!inside(nx, ny, w, h) || prev[nx * h + ny] != -1) continue;
                if ((flags[x][y] & d[2]) != 0 || (flags[nx][ny] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) != 0) continue;
                prev[nx * h + ny] = cur;
                queue.add(nx * h + ny);
            }
        }
        return Collections.emptyList();
    }

    private static List<WorldPoint> walkBack(WorldView wv, int[] prev, int end, int h, int plane) {
        List<WorldPoint> path = new ArrayList<>();
        for (int cur = end; ; cur = prev[cur]) {
            path.add(WorldPoint.fromScene(wv, cur / h, cur % h, plane));
            if (prev[cur] == cur) break;
        }
        Collections.reverse(path);
        return path;
    }

    private static boolean inside(int x, int y, int w, int h) {
        return x >= 0 && y >= 0 && x < w && y < h;
    }
}

package com.routeplanner.util;

import java.awt.BasicStroke;

/** Round-capped strokes, made once per width instead of on every frame. */
public final class Strokes {

    private static final BasicStroke[] ROUND = new BasicStroke[33];

    private Strokes() {}

    /** A solid stroke with round caps and joins, as the route lines use. */
    public static BasicStroke round(int width) {
        if (width < 0 || width >= ROUND.length) {
            return new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
        }
        BasicStroke s = ROUND[width];
        if (s == null) {
            s = new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
            ROUND[width] = s;
        }
        return s;
    }
}

package com.routeplanner;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import static org.junit.Assert.*;

public class AreaFillTest {

    /** The outline of a 5x5 square (16 tiles), with its centre 3x3 empty. */
    private static Set<WorldPoint> ring() {
        Set<WorldPoint> out = new LinkedHashSet<>();
        for (int x = 0; x < 5; x++) for (int y = 0; y < 5; y++)
            if (x == 0 || y == 0 || x == 4 || y == 4) out.add(p(x, y));
        return out;
    }

    private static WorldPoint p(int x, int y) {
        return new WorldPoint(3200 + x, 3200 + y, 0);
    }

    @Test
    public void closingARingFillsItsMiddle() {
        Set<WorldPoint> painted = ring();
        List<WorldPoint> added = new ArrayList<>(painted);
        Set<WorldPoint> fill = AreaDrawer.enclosedBy(painted, added, 0);
        assertEquals(9, fill.size());
        assertTrue(fill.contains(p(2, 2)));
    }

    @Test
    public void aRingWithAGapLeaksAndStaysEmpty() {
        Set<WorldPoint> painted = ring();
        painted.remove(p(2, 0));
        assertTrue(AreaDrawer.enclosedBy(painted, new ArrayList<>(painted), 0).isEmpty());
    }

    @Test
    public void aDiagonalRingStillCloses() {
        // A diamond: corners touch only diagonally, like a painted circle
        Set<WorldPoint> painted = new LinkedHashSet<>();
        for (int[] c : new int[][]{{2, 0}, {3, 1}, {4, 2}, {3, 3}, {2, 4}, {1, 3}, {0, 2}, {1, 1}}) painted.add(p(c[0], c[1]));
        Set<WorldPoint> fill = AreaDrawer.enclosedBy(painted, new ArrayList<>(painted), 0);
        // The middle and the tile beside it on each side
        assertEquals(5, fill.size());
        assertTrue(fill.contains(p(2, 2)));
        assertTrue(fill.contains(p(2, 1)));
        assertFalse(fill.contains(p(1, 1))); // part of the ring itself
    }

    @Test
    public void anErasedHoleElsewhereIsLeftAlone() {
        // A filled 5x5 block with a hole erased in it, then a stroke added far off to the east
        Set<WorldPoint> painted = new LinkedHashSet<>();
        for (int x = 0; x < 5; x++) for (int y = 0; y < 5; y++) painted.add(p(x, y));
        painted.remove(p(2, 2));
        List<WorldPoint> added = new ArrayList<>();
        for (int x = 8; x < 11; x++) { painted.add(p(x, 0)); added.add(p(x, 0)); }
        assertTrue(AreaDrawer.enclosedBy(painted, added, 0).isEmpty());
    }
}

